  ["CODE RUSH  ·  Times Square"] = "コードラッシュ  ·  タイムズスクエア",
  ["CODE RUSH  ·  the Python round"] = "CODE RUSH  ·  Python ラウンド",
  ["CODE RUSH  ·  the Rust round"] = "CODE RUSH  ·  Rust ラウンド",
  ["COMBO x%d"] = "コンボ x%d",
  ["COMBO x10"] = "コンボ x10",
  ["COMBO x5"] = "コンボ x5",
  ["COPIED  %s"] = "コピーしました  %s",
  ["COPY  (ask your AI why)"] = "コピー  (AI に理由を聞く)",
  ["Call the map API over HTTP with one line. Which popular async client crate?"] = "地図 API を HTTP で1行で呼ぶ。人気の async クライアントクレートは？",
  ["Callback round, Chef. Whiteboard, no keyboard. First: are these brackets balanced?"] = "コールバックラウンドだ、シェフ。ホワイトボード、キーボードなし。まずは: この括弧は釣り合っているか？",
  ["Callback round, Mei. No buzzer this time, just the whiteboard. Warm-up: are these brackets balanced?"] = "コールバックラウンドだ、メイ。今回はブザーなし、ホワイトボードだけ。ウォームアップ: この括弧は釣り合ってるか？",
  ["Cancel automatically after two seconds. Fill: context.___(ctx, 2*time.Second)"] = "2秒後に自動キャンセル。埋めて：context.___(ctx, 2*time.Second)",
  ["Capital = exported. Small = private to the package. Same rule for types and fields."] = "大文字 = エクスポート。小文字 = package内だけ。型やフィールドも同じルールです。",
  ["Capital E, returns string. That one method is the whole error interface."] = "大文字の E、string を返します。そのひとつのメソッドが error interface のすべてです。",
  ["Capital M. MarshalIndent pretty-prints. The opposite is on the next blank."] = "大文字の M。MarshalIndent は整形して出力。逆向きは次の空欄です。",
  ["Capital N. Go's nil, Rust's Option::None. Compare it with is, not ==."] = "大文字の N。Go の nil、Rust の Option::None。== ではなく is で比べる。",
  ["Capital S. The fmt.Stringer interface has exactly this one method."] = "大文字のS。fmt.Stringer interface はこのメソッドただ1つです。",
  ["Capital first letter. Lower-case fields are invisible outside the package, json included."] = "先頭は大文字。小文字のフィールドはパッケージ外から見えません。json も同じです。",
  ["Cargo, the build tool"] = "ビルドツール Cargo",
  ["Carry the order id through five calls of logging. Which constructor?"] = "注文 id をログ五段分の呼び出しに運ぶ。どのコンストラクタ？",
  ["Causeway Bay"] = "銅鑼湾",
  ["Causeway Bay station"] = "銅鑼湾駅",
  ["Channel pipelines, closed and nil"] = "channel のパイプライン、閉じたものと nil",
  ["Channels"] = "Channel",
  ["Channels in Go, mpsc in Rust, and now a Queue. Same kitchen every time."] = "Go では channel、Rust では mpsc、そして今度は Queue。いつも同じキッチンだ。",
  ["Check bounds before touching g[r][c]: Python would raise IndexError on the right edge, and g[-1] silently wraps."] = "g[r][c] に触る前に範囲チェック: 右端では Python が IndexError を投げ、g[-1] は黙って回り込む。",
  ["Check bounds before you index, or the recursion panics at the shoreline."] = "添字の前に範囲を確認せよ。さもないと再帰が海岸線で panic する。",
  ["Check for an order without waiting; the till must keep beeping. Which method?"] = "待たずに注文を確認する。レジはピッと鳴り続けなければならない。メソッドは？",
  ["Check the hints before running the shift. Which tool, the classic one?"] = "シフトを走らせる前にヒントをチェックする。どのツール、定番のやつは？",
  ["Checking every guest against every other guest for a double booking. Fine with 20. Not with 2000."] = "二重予約を探して各客を他のすべての客と照合する。20人なら問題ない。2000人では無理。",
  ["Checking every guest against every other guest for a double booking. It was fine with 20. It is not fine with 2000."] = "二重予約を探して各客を他のすべての客と照合する。20人なら問題なかった。2000人では無理だ。",
  ["Chef Bo"] = "ボー料理長",
  ["Close results only after every worker is done. Fill: wg.___(); close(results)"] = "全 worker が終わってから results を閉じる。穴埋め: wg.___(); close(results)",
  ["Close the receipt printer whether the refund worked or not. Which clause always runs?"] = "返金がうまくいっても行かなくても、レシートプリンタを閉じる。常に走る節は？",
  ["Code is done. Now build it like a Rustacean: one tool for everything. Ticket six."] = "コードは完成。次は Rustacean らしくビルド: ツールひとつで全部。チケット6。",
  ["Coin c on top of the best answer for a - c, if that beats what we have. Which built-in keeps the smaller?"] = "a - c の最良解の上にコイン c、それが今の値より良ければ。小さい方を残す組み込みは？",
  ["Coin change, fewest coins. Before the loop, mark every amount with a value no real answer can reach. Which?"] = "コイン両替、最少枚数。ループの前に、どの本当の答えも届かない値を全金額に付ける。どれ？",
  ["Coin change: dp[a] is the fewest coins for amount a. The table starts full of 'impossible'. Which amount costs zero coins?"] = "両替: dp[a] は金額 a の最少コイン数。表は「不可能」で満たして始める。コイン0枚で済む金額は？",
  ["Coin change: fewest coins for each amount. Unreachable amounts start at infinity. Fill the float."] = "コイン両替: 各金額の最少枚数。届かない金額は無限大から始まる。float を埋めろ。",
  ["Coins [2] for 3 returns -1. Table, transition, base case, impossible marker: every DP has the four."] = "コイン [2] で 3 は -1 を返す。表、遷移、基底ケース、不可能マーカー: どの DP にも4つがある。",
  ["Colon then equals. Only inside a function."] = "コロンのあとにイコール。関数の中でだけ使えます。",
  ["Compare characters, not bytes, so 銅鑼灣 works. Fill: r := []___(s)"] = "バイトでなく文字を比較、だから 銅鑼灣 でも動く。穴埋め: r := []___(s)",
  ["Compare code against several patterns and pick one arm. Which keyword?"] = "code を複数のパターンと比べてアームを 1 つ選ぶ。キーワードは？",
  ["Compare the start with the end of the last block in out. Equal counts as touching."] = "開始を out の最後のブロックの終わりと比べる。等しければ触れているとみなす。",
  ["CompareAndSwap returns false when someone beat you to it, so the loop reads and tries again. That retry loop is how lock-free code is written."] = "先を越されると CompareAndSwap は false を返し、ループはもう一度読んで試す。この再試行ループがロックフリーの書き方だ。",
  ["Comparing each pair once is n(n-1)/2 checks. For 100 guests, how many?"] = "各組を1回比べると n(n-1)/2 回。100人の客なら何回？",
  ["Compile everything into one binary called delivery. Fill: go ___ -o delivery ."] = "すべてを delivery というひとつのバイナリにコンパイル。埋めてください: go ___ -o delivery .",
  ["Compile with optimisations for the live server. Which flag?"] = "本番サーバ向けに最適化してコンパイルする。どのフラグ？",
  ["Compute, remember, return. Fill the second term: fib(n-1) + fib(___)"] = "計算して、覚えて、返す。2 項目を穴埋め: fib(n-1) + fib(___)",
  ["Computed once, never again. Put v into the memo under key n. Which method?"] = "計算は一度きり。キー n で v をメモに入れる。どのメソッド？",
  ["Constant time"] = "定数時間",
  ["Constant. A Python list is an array of pointers; index 3 is base plus 3 times a pointer's size."] = "定数。Python のリストはポインタの配列。インデックス3は基底に3掛けるポインタのサイズを足したもの。",
  ["Constant. A slice is a pointer and a length; index 3 is pointer plus 3 times the element size, after a bounds check."] = "定数。スライスはポインタと長さ。インデックス3は境界チェックの後、ポインタに3掛ける要素サイズを足したもの。",
  ["Constant. The slice knows its base address; index 3 is base plus 3 times the element size."] = "定数。スライスは基底アドレスを知っている。インデックス3は基底に3掛ける要素サイズを足したもの。",
  ["Context and tests"] = "Context とテスト",
  ["Context managers"] = "コンテキストマネージャ",
  ["Conversion is T(x). int and float64 never mix without it."] = "変換は T(x)。int と float64 はこれなしでは混ぜられません。",
  ["Convert the rune back to a string. The index i is a byte offset."] = "rune を string に戻します。インデックス i はバイトオフセットです。",
  ["Copies are the tax of multiprocessing: a global changed in a child stays in the child. multiprocessing.shared_memory.SharedMemory gives every process the same block of bytes, found by name and read through .buf, which NumPy can wrap without copying. You close() your view and unlink() the block exactly once, or it outlives the program."] = "コピーは multiprocessing の税だ：子で変えたグローバルは子に残る。multiprocessing.shared_memory.SharedMemory はどのプロセスにも同じバイト列を渡す。名前で見つけ、.buf 越しに読み、NumPy はそれをコピーせずに包める。自分のビューは close() し、そのブロックはちょうど一度 unlink() すること。さもないとプログラムより長生きする。",
  ["Count characters, not bytes. Which iterator do you count?"] = "バイトではなく文字を数える。どのイテレータを count する？",
  ["Count characters, not bytes. Which unicode/utf8 function?"] = "バイトではなく文字を数えます。unicode/utf8 のどの関数？",
  ["Count each letter of a word in one call. Which collections class?"] = "単語の各文字を1回の呼び出しで数える。collections のどのクラス？",
  ["Count islands: every land cell still standing starts a new one. Fill the call that sinks the whole island."] = "島を数える: まだ残る陸のセルごとに新しい島が始まる。島を丸ごと沈める呼び出しを埋めよ。",
  ["Count letters of a, uncount letters of b; all zero means anagram. Fill: count[c-'a']___"] = "a の文字を数え、b の文字を引く。全部 0 ならアナグラム。穴埋め: count[c-'a']___",
  ["Count muffins per table: insert 0 if the key is new, then add 1. Which HashMap method starts that?"] = "テーブルごとにマフィンを数える: キーが新しければ 0 を入れ、そして 1 を足す。それを始める HashMap のメソッドは？",
  ["Count the arrows. 2 to this power is 1024."] = "矢印を数えよ。2 のこの乗が 1024。",
  ["Count the nodes without taking ownership: cur is a &Link. Step to the following node: cur = &node.___"] = "所有権を取らずにノードを数える: cur は &Link。次のノードへ進む: cur = &node.___",
  ["Count the values. The length is part of the type, so [i32; 4] would be a different type."] = "値を数えて。長さは型の一部なので、[i32; 4] は別の型になる。",
  ["Counter(word).most_common(1) gives the top letter. Go's count[c-'a']++ in one line. Round six to Bo."] = "Counter(word).most_common(1) が最多の文字を与える。Go の count[c-'a']++ を一行で。第6ラウンドはボーに。",
  ["Counting the queue takes one look per person. Twice the queue, twice the looking."] = "行列を数えるのは一人一見。列が2倍なら見るのも2倍。",
  ["Crate name, two colons, the function it sits on."] = "クレート名、コロン2つ、それが乗っている関数の名前。",
  ["Create a fresh binary project called delivery. Which cargo subcommand?"] = "delivery という新しいバイナリプロジェクトを作る。cargo のどのサブコマンド？",
  ["Custom errors and ?"] = "独自エラーと ?",
  ["Cut a slice into two slices at mid, no copying. Which slice method returns the pair?"] = "スライスを mid で 2 つのスライスに切る。コピーはしない。その組を返すスライスのメソッドは？",
  ["DELIVERY  -  the app"] = "DELIVERY  -  アプリ",
  ["DFS dives down one line before backing up. Same O(V + E) as BFS. Mind the 1000-deep recursion limit. Round three to Bo."] = "DFS は一本の線を潜ってから戻る。BFS と同じ O(V + E)。1000段の再帰制限に注意。第3ラウンドはボーに。",
  ["DFS is recursion plus a visited set. Maps are reference-like: no pointer needed."] = "DFS は再帰 + 訪問済み set。map は参照的なのでポインタ不要。",
  ["DP fills a table from small answers up. Stairs: dp[i] = dp[i-1] + dp[i-2]. Coin change: dp[a] = min over coins of dp[a-c] + 1, with amount+1 as 'impossible'."] = "DP は小さい答えから表を埋めていく。階段: dp[i] = dp[i-1] + dp[i-2]。両替: dp[a] = 各コイン c についての dp[a-c] + 1 の min、amount+1 を「不可能」の印に。",
  ["DP: a table of answers to smaller problems, filled from the base cases up. Stairs: dp[i] = dp[i-1] + dp[i-2]. Coin change: dp[a] = min over coins of dp[a-c] + 1, with a sentinel for 'impossible'."] = "DP: 小さい問題の答えの表を、基底ケースから上へ埋める。階段: dp[i] = dp[i-1] + dp[i-2]。コイン両替: dp[a] = 各コイン c の dp[a-c] + 1 の最小、「不可能」には番兵。",
  ["DP: solve the small cases once, build the bigger ones from them. Stairs: ways(i) = ways(i-1) + ways(i-2). Coins: dp[a] = min over coins of dp[a-c] + 1, with inf for unreachable."] = "DP: 小さいケースを一度だけ解き、そこから大きいケースを組み立てる。階段: ways(i) = ways(i-1) + ways(i-2)。コイン: dp[a] = 各コインの dp[a-c] + 1 の min、届かないなら inf。",
  ["Declare a function. Which keyword starts the line?"] = "関数を宣言する。行頭のキーワードは？",
  ["Declare with an explicit type, outside any function. Which keyword?"] = "関数の外で、型を明示して宣言する。キーワードは？",
  ["Decorators"] = "デコレータ",
  ["Define your own error type for the kitchen. What must it inherit from?"] = "キッチン用に自前のエラー型を定義する。何を継承しなければならない？",
  ["Depth first, recursive: visit, then call yourself on each unseen neighbour. Fill the call."] = "深さ優先、再帰: 訪れ、それから未訪問の隣駅ごとに自分を呼ぶ。呼び出しを埋めよ。",
  ["Depth first: same loop, but the newest station goes next. Which Vec method takes from the end?"] = "深さ優先: ループは同じで、次に出るのは最新の駅。末尾から取り出す Vec のメソッドは？",
  ["Depth-first: visit, then recurse into each unseen neighbour. Fill the call."] = "深さ優先: 訪問し、未訪問の隣ごとに再帰。呼び出しを穴埋め。",
  ["Dicts and sets"] = "dict と set",
  ["Did any of those futures leak? Which runtime call counts the live goroutines?"] = "いまの future はどれか漏れた？ 生きている goroutine を数える runtime 呼び出しは？",
  ["Did the child succeed? Which attribute holds its exit status after join?"] = "子は成功した？ join のあと終了状態を持つ属性は？",
  ["Different indexes are different memory, so no lock is needed. Since Go 1.22 each iteration gets its own i, so the closure captures the right one."] = "添字が違えばメモリも違うので、ロックは要らない。Go 1.22 以降は各周回が自分の i を持つので、クロージャは正しいほうを捕まえる。",
  ["Display does not care which lifetime Receipt has. Which placeholder says so?"] = "Display は Receipt のライフタイムがどれかを気にしない。それを表すプレースホルダーは？",
  ["Divide and conquer: split the slice in the middle. Fill: let mid = v.len() / ___"] = "分割統治: スライスを真ん中で割る。埋めて: let mid = v.len() / ___",
  ["Divide, recurse, merge: O(n log n) always. Base case is a slice of length 0 or 1."] = "分割、再帰、マージ: 常に O(n log n)。ベースケースは長さ 0 か 1 の slice。",
  ["Do not block if nothing is ready. Which case label?"] = "何も準備できていなければブロックしない。case のラベルは？",
  ["Do not recurse. Fill a table from the bottom step up."] = "再帰するな。一番下の段から表を埋めろ。",
  ["Do not start a Process per photo. Forty thousand interpreters is not parallelism, it is a fire."] = "写真ごとに Process を立てないで。四万のインタプリタは並列じゃなくて火事だ。",
  ["Does the order contain egg? Which keyword tests membership?"] = "注文に egg は含まれる？ メンバーシップを調べるキーワードは？",
  ["Does this shift start before the last merged block ends? Fill the overlap test."] = "このシフトは最後にマージしたブロックが終わる前に始まるか？ 重なりの判定を埋めろ。",
  ["Don't share memory. Pass the hash brown on a channel."] = "メモリを共有するな。ハッシュブラウンは channel で渡せ。",
  ["Double every price into a new list, in one line. Which keyword sits in the middle of the comprehension?"] = "すべての値段を2倍にした新しいリストを一行で。内包表記の真ん中に座るキーワードは？",
  ["Double every quantity. How does a closure name its one parameter?"] = "数量を全部2倍にする。クロージャは唯一の引数をどう書く？",
  ["Dunder around the text type's name. Its sibling __repr__ is for the debugger."] = "テキスト型の名前を dunder で囲んだもの。その兄弟 __repr__ はデバッガ向け。",
  ["Dunder around the verb for going in. Its return value is what as binds."] = "「入る」の動詞を dunder で囲む。その戻り値が as の束縛するもの。",
  ["Dunder around the verb for going out. It receives three values about any exception."] = "「出る」の動詞を dunder で囲む。例外についての3つの値を受け取る。",
  ["Dynamic programming"] = "動的計画法",
  ["Dynamic programming: stairs and coins"] = "動的計画法: 階段とコイン",
  ["EARLY BIRD"] = "早起き鳥",
  ["ENTER  pick a street"] = "ENTER  通りを選ぶ",
  ["ENTER  street map      ESC  title"] = "ENTER  通りの地図      ESC  タイトル",
  ["ESC back"] = "ESC 戻る",
  ["ESC title"] = "ESC タイトル",
  ["EXPORT  to ~/Downloads"] = "エクスポート  ~/Downloads へ",
  ["Each Fibonacci number is the sum of the two before it."] = "フィボナッチ数は直前 2 つの和です。",
  ["Each call handles one step and delegates the rest: n * (n-1)!"] = "各呼び出しは 1 段だけ処理し、残りを委ねます: n * (n-1)!",
  ["Each call handles one step and delegates the rest: n * (n-1)!. Python ints never overflow, so fact(100) just works."] = "各呼び出しは一歩だけ処理し、残りを委ねる: n * (n-1)!。Python の int はオーバーフローしないので fact(100) もそのまま動く。",
  ["Each call is one step closer to 1. fact(20) is the biggest that fits in u64. The crowd claps."] = "呼び出しごとに 1 へ一歩近づく。u64 に収まる最大は fact(20)。観客が拍手する。",
  ["Each cell is visited a constant number of times: O(rows*cols). A BFS with a queue avoids deep recursion. OFFER."] = "各セルの訪問回数は定数: O(rows*cols)。キューを使う BFS なら深い再帰を避けられる。OFFER。",
  ["Each closer maps to its opener. Fill the value stored for ')'."] = "各閉じカッコは開きカッコに対応する。')' に格納される値を埋めよ。",
  ["Each interval is compared with the last merged one, which may need to grow. Which method borrows the last element mutably as Option?"] = "各区間は最後にマージしたものと比べられ、そちらは伸びるかもしれない。最後の要素を Option として可変借用するメソッドは？",
  ["Each n is computed once: O(n) calls, O(n) memory. Round one, no misses. Combo x1."] = "各 n は一度だけ計算: 呼び出し O(n)、メモリ O(n)。第 1 ラウンド、ミスなし。コンボ x1。",
  ["Each node links to the next one. Fill the field type: Next ___"] = "各ノードは次のノードへリンク。フィールドの型を穴埋め: Next ___",
  ["Each thread needs its own handle to the same counter. Which call makes one from &sold?"] = "各スレッドに同じカウンタへの自分のハンドルが要る。&sold から 1 つ作る呼び出しは？",
  ["Eight cooks, one order book. That I understand."] = "料理人八人、注文帳一冊。それなら分かる。",
  ["Eight cores, one busy"] = "コア八つ、忙しいのは一つ",
  ["Eight letters, what a house or an object has. Then o.total works, no parentheses."] = "8文字、家やオブジェクトが持つもの。そうすれば o.total が括弧なしで動く。",
  ["Eight letters: every goroutine waits on every other. The send never returns."] = "8文字：全 goroutine が互いを待つ状態。送信は永遠に戻りません。",
  ["Eight letters: like find, but it gives you where, not what. Option<usize>."] = "8文字: find に似ているが、何かではなくどこかを返す。Option<usize>。",
  ["Eight shared doubles with a lock and no NumPy. Which multiprocessing class?"] = "ロック付きの共有 double 八つ、NumPy なしで。どの multiprocessing クラス？",
  ["Eight workers, one label printer. The labels came out with two orders on one sticker."] = "ワーカー八人にラベルプリンタ一台。シール一枚に注文が二件重なって出てきた。",
  ["Eight workers, started once, reused all night. Which class?"] = "ワーカー八人、一度だけ立てて一晩使い回す。どのクラス？",
  ["Elision: one input reference (here &self) means the output borrows from it. Most signatures need no 'a at all. The receipt prints."] = "省略規則: 入力参照が 1 つ (ここでは &self) なら、出力はそこから借りる。ほとんどのシグネチャに 'a は要らない。レシートが印字される。",
  ["Empty brackets then the element type. [3]int would be an array."] = "空の角括弧のあとに要素の型。[3]int だと配列になります。",
  ["Empty parentheses. go needs a call, not just a function value."] = "空の括弧。go には関数値でなく呼び出しが必要です。",
  ["Empty the whole map in one call (Go 1.21). Which built-in?"] = "map 全体を1回の呼び出しで空にする(Go 1.21)。組み込み関数は？",
  ["Errors and defer"] = "エラーと defer",
  ["Errors are exceptions: try runs the risky part, except catches a type, finally always runs, raise throws. Your own errors subclass Exception."] = "エラーは例外: try が危ない部分を走らせ、except が型を捕まえ、finally は常に走り、raise が投げる。自前のエラーは Exception を継承する。",
  ["Errors: New, wrap, Is, As"] = "error: New、wrap、Is、As",
  ["Even with separate memory, processes still share the machine: one printer, one log file, one counter in shared memory. multiprocessing.Lock is the mutex across processes, used as a with block. Value and Array put a number in shared memory and hand you get_lock() for it, and a Manager serves ordinary dicts and lists over a proxy."] = "メモリが別々でも、プロセスはこの機械を共有している：プリンタ一台、ログファイル一つ、共有メモリのカウンタ一つ。multiprocessing.Lock はプロセスをまたぐ mutex で、with ブロックで使う。Value と Array は数を共有メモリに置き、その get_lock() まで渡してくれる。Manager はふつうの dict や list をプロキシ越しに提供する。",
  ["Evening edition of CODE RUSH! Rust round. Mei, you're up. Factorial, then fib. Buzzer's live!"] = "CODE RUSH 夜の部！Rust ラウンド。メイ、出番だ。階乗、次は fib。ブザー、オン！",
  ["Every Go file starts with package. import brings other packages in."] = "Goファイルは必ず package で始まります。import で他のpackageを取り込みます。",
  ["Every Rust program starts in which function?"] = "Rust のプログラムはどの関数から始まる？",
  ["Every cell is visited once by the loop and at most once by a DFS: O(rows * cols). The screen says OFFER."] = "どのセルもループで一度、DFS で高々一度訪ねられる: O(rows * cols)。画面は OFFER と言っている。",
  ["Every closer knows its opener. Fill the opener that } maps to."] = "閉じ括弧はみんな自分の開き括弧を知っている。} が対応する開き括弧を埋めろ。",
  ["Every dish gets a stamp: time it, log it. I do not want to write that in fifty functions."] = "どの料理にもスタンプを: 時間を計り、記録する。それを50個の関数に書きたくはない。",
  ["Every dish is a function. fry(egg), brew(tea). Someone deleted the word that starts them."] = "どの料理も関数だ。fry(egg)、brew(tea)。誰かが先頭の単語を消した。",
  ["Every get must be paired with a task_done, or join waits forever. Go's wg.Done()."] = "すべての get には task_done を対にしなければならない。さもないと join は永遠に待つ。Go の wg.Done()。",
  ["Every get needs one task_done, or q.join() waits for ever. It is the WaitGroup of the queue world."] = "get 一つにつき task_done が一つ要る。さもないと q.join() は永遠に待つ。キューの世界の WaitGroup だ。",
  ["Every island is counted exactly once because its cells are water by the time the loop reaches them again. OFFER."] = "どの島もちょうど1回だけ数えられる。ループが再びそのセルに着く頃には水になっているから。OFFER。",
  ["Every item is moved exactly once per level, however many pieces there are."] = "断片がいくつあろうと、各項目は段ごとにちょうど1回動く。",
  ["Every item sent to a worker is pickled and shipped down a pipe. Below a few microseconds of work per item, the shipping is the program."] = "ワーカーへ送る一件ごとに pickle してパイプで運ぶ。一件が数マイクロ秒を切ると、運搬こそがプログラムになる。",
  ["Every key of the price map, as an iterator (Go 1.23). Fill: maps.___(prices)"] = "price map の全キーをイテレータとして (Go 1.23)。埋めてください: maps.___(prices)",
  ["Every one of these is 'use a map' or 'use two pointers'. Pick the right one."] = "どれも「map を使う」か「2 ポインタを使う」か。正しい方を選んで。",
  ["Every opener must have been closed. What does the function return at the end?"] = "すべての開きカッコが閉じられていなければならない。関数は最後に何を返す？",
  ["Every opener must have found its closer. What does valid return after the loop?"] = "すべての開き括弧が閉じ括弧を見つけたはず。ループの後、valid は何を返す？",
  ["Every price but the first must lose a comparison to be ruled out. One less than the count."] = "最初のもの以外のすべての値段が、除外されるには比較で負けなければならない。個数より1少ない。",
  ["Every process closes its view. Which call, made once, frees the block itself?"] = "各プロセスは自分のビューを閉じる。一度だけ呼んで塊そのものを解放するのは？",
  ["Every real answer grows out of dp[0]. The marker amount + 1 lets min work without an Option."] = "本当の答えはすべて dp[0] から育つ。印の amount + 1 のおかげで min が Option なしで動く。",
  ["Every receipt goes onto a min-heap. Which heapq function adds x and keeps the heap order?"] = "レシートは全部 min-heap へ。x を加えてヒープの順序を保つ heapq の関数は？",
  ["Every recursion stops somewhere. fact(0) and fact(1) evaluate to what?"] = "どんな再帰もどこかで止まる。fact(0) と fact(1) の値は？",
  ["Every recursion stops somewhere. fact(0) and fact(1) return what?"] = "再帰はどこかで止まります。fact(0) と fact(1) は何を返しますか？",
  ["Every runnable Go program lives in which package?"] = "実行できるGoプログラムはどのpackageに属しますか？",
  ["Every topping can be on or off. Ten toppings, a thousand combos. Twenty, a million. That is 2^n."] = "どのトッピングも有りか無し。10種で1000通り。20種で100万。それが 2^n。",
  ["Every topping on or off, n toppings. How many combinations, as a power?"] = "各トッピングが有りか無し、n 種。組み合わせはいくつ、べきで？",
  ["Every worker allocates a receipt buffer. Which sync.Pool method hands one back?"] = "ワーカーごとにレシート用バッファを確保する。sync.Pool のどのメソッドが一つ渡す？",
  ["Every worker must report in before Wait returns. Which method, deferred?"] = "Wait が返る前にワーカー全員が報告しなければならない。defer で呼ぶメソッドは？",
  ["Everyone's shifts overlap. Six to ten, nine to two, one to four. When is the kitchen actually staffed?"] = "みんなのシフトが重なってる。6時から10時、9時から2時、1時から4時。厨房に実際に人がいるのはいつだ？",
  ["Everything bigger than the node. Five letters."] = "ノードより大きいものが全部いる側。5 文字。",
  ["Everything from index 1 to the end. A slice expression, no copy."] = "インデックス 1 から末尾まで。slice 式なのでコピーなし。",
  ["Everything from the second block on. zip stops at the shorter list, so no index error."] = "2番目のブロック以降すべて。zip は短い方で止まるので、インデックスエラーは出ない。",
  ["Everything is immutable until you say mut. The tram sign forgot that."] = "mut と言うまで、すべては不変。トラムの看板はそれを忘れてた。",
  ["Everything written before the close happens before <-ready returns, so reading menu after it is not a race. That rule is the Go memory model."] = "閉じる前に書いたものはすべて <-ready が返るより前に起きるので、そのあと menu を読むのはレースではない。この規則が Go のメモリモデルだ。",
  ["Exponential time"] = "指数時間",
  ["Exponential: two to the power of n. Each level of the call tree is twice as wide as the one above."] = "指数: 2 の n 乗。呼び出し木の各段は上の段の2倍の幅。",
  ["F for a file or writer, then printf. The writer is the first argument."] = "file や writer の F、そして printf。writer が第1引数です。",
  ["FAILED  %s"] = "失敗  %s",
  ["FAST!"] = "速い！",
  ["FINAL  -  the islands"] = "決勝  -  島",
  ["FINAL  -  the kitchen"] = "決勝  -  厨房",
  ["FIRST CLEAR"] = "初クリア",
  ["FIRST STAMP"] = "初スタンプ",
  ["FIVE PERFECTS"] = "パーフェクト5回",
  ["FULL"] = "全画面",
  ["Fan-in: workers send, one closer closes. Closing from a worker would panic the others, so the closer is the goroutine that waits."] = "ファンイン：ワーカーは送り、閉じるのは一人。ワーカーが閉じると他が panic するので、閉じるのは待っている goroutine だ。",
  ["Feed nine orders into the queue. Which method adds one?"] = "注文9件をキューに供給する。1つ追加するメソッドは？",
  ["Fewest coins wins, so keep the smaller of the old value and the new candidate."] = "最少枚数が勝つので、旧値と新候補の小さい方を残す。",
  ["Fibonacci in disguise: the sum of the two entries just before it."] = "変装したフィボナッチ: 直前 2 つの項の和。",
  ["Final question. A map of the harbour, ones for land, zeros for water. How many islands? Get this and the offer is yours."] = "最終問題。港の地図、1 が陸、0 が水。島はいくつ？これを解けばオファーは君のものだ。",
  ["Final round, Mei! Get the drop and the join in the right order and you're HIRED!"] = "最終ラウンドだ、メイ！drop と join を正しい順で決めれば HIRED！",
  ["Final round. The delivery map as a grid of 1s and 0s. How many separate islands of buildings?"] = "最終ラウンド。配達地図を 1 と 0 のグリッドとして。建物の島は別々にいくつある？",
  ["Final round: a worker pool. Three cooks, one queue, nine orders. Nothing lost, nothing done twice."] = "最終ラウンド: ワーカープール。コック3人、キュー1つ、注文9件。何も失わず、何も二度やらない。",
  ["Finally, types. Even if the interpreter ignores them."] = "ついに型だ。インタプリタが無視するとしても。",
  ["Find land, sink the whole island, count one. Repeat until the map is all water."] = "陸を見つけ、島を丸ごと沈め、1 つ数える。地図が全部水になるまで繰り返す。",
  ["Find suspicious code the compiler allows: wrong Printf verbs, copied locks. Fill: go ___ ./..."] = "コンパイラが通す怪しいコードを見つけます: 誤った Printf verb、コピーされたロック。埋めてください: go ___ ./...",
  ["Find the middle: slow moves one, fast moves two. Fill the fast step: fast = fast.next.___"] = "中央を見つける: slow は1つ、fast は2つ進む。fast の一歩を埋めよ: fast = fast.next.___",
  ["Find where 38 belongs in the sorted amounts in O(log n). Which bisect function?"] = "ソート済みの金額の中で 38 の位置を O(log n) で見つける。どの bisect 関数？",
  ["Finding the largest of n unsorted prices needs at least how many comparisons?"] = "n 個の未ソートの値段から最大を見つけるには、少なくとも何回の比較が要る？",
  ["Finish Go's proverb: do not communicate by sharing memory; share memory by ___."] = "Go の格言を完成させよう：メモリを共有して通信するな。___ してメモリを共有せよ。",
  ["Five letters, Go's only way to loop over a slice's elements. slices.Contains does exactly this inside."] = "5文字、Go でスライスの要素をループする唯一の方法。slices.Contains は中でまさにこれをする。",
  ["Five letters, a builtin that takes a channel. It never blocks and every receiver wakes."] = "五文字、channel を取る組み込み。決してブロックせず、すべての受信者が起きる。",
  ["Five letters, a stash of things already fetched. Its older sibling takes a maxsize."] = "5文字、すでに取ってきたものの隠し場所。年上の兄弟は maxsize を取る。",
  ["Five letters, a verb in the third person: what the wrapper does to fn."] = "5文字、三人称の動詞: ラッパーが fn に対してすること。",
  ["Five letters, a verb: wait for it. Rust puts the same word after a dot."] = "5文字、動詞: それを待つ。Rust は同じ単語をドットの後に置く。",
  ["Five letters, capitalised: what Value is, but with a length."] = "五文字、大文字始まり：Value と同じものに長さが付いたもの。",
  ["Five letters, goes before fn. The opposite of sync."] = "5文字、fn の前に置く。sync の反対。",
  ["Five letters, lower case: the box has one, and this is how you open it."] = "五文字、小文字：箱の中に一つ入っていて、これがその開け方だ。",
  ["Five letters, lowercase, no package in front of it. Go needs fmt for this; Python does not."] = "5文字、小文字、前にパッケージ名なし。Go には fmt が要るが、Python には要らない。",
  ["Five letters, meaning 'give way'. Like return, but the function resumes on the next pull."] = "5文字、「譲る」という意味。return に似ているが、次に引かれると関数が再開する。",
  ["Five letters, plural. for k in menu alone gives only the keys."] = "5文字、複数形。for k in menu だけではキーしか出ない。",
  ["Five letters, same as Go, but Rust insists on the : u8 part."] = "5 文字、Go と同じ。でも Rust は : u8 の部分を省かせない。",
  ["Five letters, short for asynchronous. Rust spells it the same way in front of fn."] = "5文字、asynchronous の略。Rust も fn の前に同じ綴り。",
  ["Five letters, short for mutual exclusion."] = "5 文字、mutual exclusion (相互排除) の略。",
  ["Five letters, since Python 3.9: the unbounded memo. Its older cousin takes a maxsize."] = "5文字、Python 3.9 から: 上限なしのメモ。年上のいとこは maxsize を取る。",
  ["Five letters, the opposite of open. Forgetting it is why the morning count was wrong."] = "5文字、open の反対。これを忘れたのが朝の数が合わなかった理由。",
  ["Five letters, the opposite of stop. Not run(): that would call fry in the current thread."] = "5文字、stop の反対。run() ではない: それは現在のスレッドで fry を呼んでしまう。",
  ["Five letters, the shape of a line at a counter. Go spells it chan."] = "五文字、カウンタの前の列の形。Go では chan と書く。",
  ["Five letters, the trait every Vec<T: Clone> implements. to_vec() from a slice is the other spelling."] = "5文字、すべての Vec<T: Clone> が実装するトレイト。スライスからの to_vec() がもう1つの綴り。",
  ["Five letters, the word for 'above'. It returns a proxy to the parent class."] = "5文字、「上」を意味する単語。親クラスへのプロキシを返す。",
  ["Five letters, the word for a stash of things you already fetched. Its older sibling takes a maxsize."] = "5文字、すでに取ってきたものの隠し場所を指す単語。年上の兄弟は maxsize を取る。",
  ["Five letters, what a fish does with eggs. The alternatives are fork and forkserver."] = "五文字、魚が卵にすること。ほかの選択肢は fork と forkserver。",
  ["Five letters, what a fish does with eggs. The closure must be 'static, hence move."] = "5 文字、魚が卵に対してすること (産卵)。クロージャは 'static でなければならないので move。",
  ["Five letters. A region with a clear start and end."] = "5 文字。始まりと終わりがはっきりした範囲。",
  ["Five letters. A slot for one key, whether it exists yet or not."] = "5 文字。キー 1 つ分のスロット、まだ存在していてもいなくても。",
  ["Five letters. Also asks for a location."] = "5 文字。場所をたずねる単語でもある。",
  ["Five letters. Also ends a switch or select case early."] = "5文字。switch や select の case を途中で抜けるのにも使います。",
  ["Five letters. Explicit, so you always see where the copying cost is."] = "5 文字。明示的なので、コピーのコストがどこにあるか常に見える。",
  ["Five letters. Go 1.22 borrowed the idea as for i := range 3."] = "5文字。Go 1.22 はこの発想を for i := range 3 として借りた。",
  ["Five letters. Go called it an interface."] = "5 文字。Go では interface と呼んだ。",
  ["Five letters. Go has struct plus methods; Python puts both under one word. Names are CapWords."] = "5文字。Go は struct とメソッド、Python は両方を1つの単語の下に置く。名前は CapWords。",
  ["Five letters. Go's switch, but exhaustive and it returns a value."] = "5 文字。Go の switch だが、網羅的で値を返す。",
  ['Five letters. It returns a Result because "1x8" is not a number.'] = '5文字。"1x8" は数字ではないので Result を返す。',
  ["Five letters. On a slice it zeroes every element instead."] = "5文字。slice に使うと全要素をゼロ値にします。",
  ["Five letters. Return an error for expected failure; this is for the impossible."] = "5文字。想定内の失敗は error を返す。これはありえない事態用です。",
  ["Five letters. Same verb as std::thread uses to start a new thread."] = "5文字。std::thread が新しいスレッドを起こすのに使う動詞と同じ。",
  ["Five letters. Sender has it; Receiver does not."] = "5 文字。Sender は持っていて、Receiver は持っていない。",
  ["Five letters. The same word as in C and Python; Go spells it for."] = "5 文字。C や Python と同じ単語。Go では for と書く。",
  ["Five letters. What a key maps to. The json! macro builds one."] = "5文字。キーが対応づける先。json! マクロがひとつ組み立てる。",
  ["Five letters. What fish and goroutines do."] = "5 文字。魚と goroutine がすること。",
  ["Five letters. What the kettle does between orders."] = "5 文字。注文の合間にやかんがすること。",
  ["Five letters. go run compiles and runs; this one only compiles."] = "5文字。go run はコンパイルして実行、こちらはコンパイルだけ。",
  ["Five letters: the Entry API. One lookup for both the check and the insert."] = "5文字: Entry API。確認と挿入を1回の検索で。",
  ["Five letters; Java and JavaScript say throw. Rust's panic!, but meant to be caught."] = "5文字。Java と JavaScript は throw と言う。Rust の panic! だが、捕まえられる前提。",
  ["Fix the Go bugs. Get the morning set."] = "Goのバグを直して、モーニングセットをゲット。",
  ["Fix the Python scripts. Close the night shift."] = "Python スクリプトを直そう。夜勤を締めよう。",
  ["Fix the Rust bugs. Get the afternoon tea set."] = "Rust のバグを直して、アフタヌーンティーセットをもらおう。",
  ["Flip it to > for a max-heap. sort.Interface plus Push and Pop is the whole contract."] = "> にひっくり返せば max-heap。sort.Interface に Push と Pop を足したものが契約のすべて。",
  ["Flood fill on a grid: return when out of bounds or not land, sink the cell to mark it, recurse into the four neighbours. Count islands by starting a fill from every land cell still standing."] = "グリッドの flood fill: 範囲外か陸でなければ return、セルを沈めて印を付け、4 方向の隣へ再帰。まだ残っている陸のセルすべてから fill を始めて島を数える。",
  ["Flood the four neighbours. r + 1 is fine, but r - 1 on a usize at row 0 panics in debug. Which method subtracts and wraps to usize::MAX instead?"] = "4つの隣を流す。r + 1 はいいが、行 0 で usize の r - 1 は debug で panic する。代わりに引いて usize::MAX へラップするメソッドは？",
  ["Flood the four neighbours: down, up, right and one more. Fill the missing one."] = "4 方向の隣を flood: 下、上、右、あと 1 つ。欠けているものを埋めよ。",
  ["Floor 8. Type the floor. Don't hard-code magic."] = "8階。階を入力して。マジックナンバーはハードコードしないで。",
  ["Floor is a named type over int. Convert the int 3 into a Floor. Fill: f := ___(3)"] = "Floor は int を基にした名前付き型。int の 3 を Floor に変換。埋めてください: f := ___(3)",
  ["Floors 1 to 5, and 5 must be included. Which range operator?"] = "1階から5階まで、5 も含める。どの範囲演算子？",
  ["Floyd's check: if the fast rider ever lands on the slow one, the route loops. Which operator compares identity?"] = "フロイドの検査: 速いライダーが遅いライダーの上に来たら経路はループしている。同一性を比べる演算子は？",
  ["Floyd: fast moves two steps per turn. Fill: fast = fast.Next.___"] = "Floyd: fast は 1 回に 2 歩進む。穴埋め: fast = fast.Next.___",
  ["Followed by the value, then case labels. No break needed."] = "値のあとに case ラベルが続きます。break は不要です。",
  ["For a pure function, the standard library has the whole cache as a decorator. Which keyword caps its size?"] = "純粋関数なら、標準ライブラリにキャッシュ丸ごとがデコレータとしてある。サイズの上限を決めるキーワードは？",
  ["For each amount a and coin c that fits: one coin c on top of the best for a - c. Keep the smaller. Which method?"] = "各金額 a と収まるコイン c について: a - c の最善にコイン c を1枚乗せる。小さい方を残す。メソッドは？",
  ["For each coin c that fits into a: one coin, plus the best for what is left. Fill the index."] = "a に収まる各コイン c について: コイン 1 枚、プラス残りの最良。添字を埋めよ。",
  ["For one number, an atomic beats a mutex: atomic.Int64 has Add, Load, Store and CompareAndSwap, all lock free. atomic.Pointer[T] swaps a whole value in one step. sync.Once runs setup exactly once; sync.OnceValue caches what it returned."] = "数字が一つなら、アトミックは mutex に勝つ：atomic.Int64 は Add、Load、Store、CompareAndSwap を持ち、どれもロックフリー。atomic.Pointer[T] は値ごと一歩で入れ替える。sync.Once は初期化をちょうど一度だけ走らせ、sync.OnceValue はその戻り値をキャッシュする。",
  ["Forty riders, eight bikes"] = "配達員四十人、自転車八台",
  ["Forty thousand photos"] = "写真四万枚",
  ["Forty thousand photos before the morning van, and threads made it no faster. Fill every core with processes."] = "朝のバンまでに写真四万枚、しかもスレッドでは速くならなかった。プロセスで全コアを埋めよう。",
  ["Forty thousand results will not fit in memory. Which method yields them one by one?"] = "結果四万件はメモリに入らない。一件ずつ返すメソッドは？",
  ["Found and removed from its old spot: now k goes to the fresh end. Which VecDeque method appends at the back?"] = "見つけて古い場所から取り除いた: k は新しい端へ。後ろに追加する VecDeque のメソッドは？",
  ["Four directions, no diagonals. Deep grids hit the recursion limit near 1000: an explicit stack of (r, c) fixes that."] = "4方向、斜めなし。深いグリッドは 1000 付近で再帰制限に当たる: (r, c) の明示的なスタックで直る。",
  ["Four hundred HTTP calls, and four hundred image resizes. Same code, different executor."] = "HTTP 呼び出し四百件と、画像の縮小四百枚。同じコード、違う executor。",
  ["Four hundred image resizes, eight cores. Which executor class?"] = "画像の縮小四百枚、コア八つ。どの executor クラス？",
  ["Four letters, a Greek one. Resets to 0 in every const block, +1 per line."] = "4文字、ギリシャ文字の名前。const ブロックごとに 0 に戻り、1行ごとに +1。",
  ["Four letters, a preposition. It replaces try/finally: f.close() for the common case."] = "4文字、前置詞。よくある場合の try/finally: f.close() を置き換える。",
  ["Four letters, capital K. slices.Sorted(maps.Keys(m)) gives a sorted slice."] = "4文字、大文字の K。slices.Sorted(maps.Keys(m)) でソート済み slice が得られます。",
  ["Four letters, capital O. Its only method is Do."] = "4文字、大文字の O。唯一のメソッドは Do です。",
  ["Four letters, capital S. SortFunc takes a compare function."] = "4文字、大文字の S。SortFunc は比較関数を受け取ります。",
  ["Four letters, capitalised. The same name threading uses, and Go calls it sync.Mutex."] = "四文字、大文字始まり。threading と同じ名前で、Go は sync.Mutex と呼ぶ。",
  ["Four letters, capitalized; Go calls it a Mutex. with acquires and releases it."] = "4文字、大文字始まり。Go はこれを Mutex と呼ぶ。with が獲得と解放をする。",
  ["Four letters, plural of what you look a value up by."] = "4文字、値を調べるときに使うものの複数形。",
  ["Four letters, short for implementation. Go attaches methods one by one; Rust groups them."] = "4 文字、implementation の略。Go はメソッドを 1 つずつ付けるが、Rust はまとめる。",
  ["Four letters, short for receive. Returns Result<Job, RecvError>. try_recv would not wait."] = "4 文字、receive の略。Result<Job, RecvError> を返す。try_recv なら待たない。",
  ["Four letters, the append of every Vec."] = "4文字、どの Vec にもある末尾追加。",
  ["Four letters, the opposite of Store."] = "四文字、Store の反対。",
  ["Four letters, the opposite of first. The length is stored, so no counting."] = "4文字、first の反対。長さは保存されているので、数えない。",
  ["Four letters, the opposite of send, cut short."] = "4 文字、send の反対を短く切ったもの。",
  ["Four letters, the same word Go uses for a set of workers reading one channel."] = "四文字、Go が同じ channel を読むワーカーの集まりを呼ぶのと同じ語。",
  ["Four letters, the same word Rust's JoinHandle uses. Go spells it wg.Wait()."] = "4文字、Rust の JoinHandle が使うのと同じ単語。Go は wg.Wait() と綴る。",
  ["Four letters, the same word as Thread.join, but on the queue: wait until the count of unfinished tasks is zero."] = "4文字、Thread.join と同じ単語だが、キューに対して: 未完了タスクの数がゼロになるまで待つ。",
  ["Four letters, the same word threading uses. Go spells it wg.Wait()."] = "四文字、threading が使うのと同じ語。Go では wg.Wait() と書く。",
  ["Four letters, the start of iterator. A for loop calls it for you."] = "4文字、iterator の頭。for ループが代わりに呼んでくれる。",
  ["Four letters, the type of true. map[T]struct{} saves a byte per entry and is the other idiom."] = "4文字、true の型。map[T]struct{} は項目ごとに1バイト節約し、もう1つの慣用句。",
  ["Four letters, the type {} makes. A list of pairs would need a scan, O(n)."] = "4文字、{} が作る型。組のリストなら走査が必要で O(n)。",
  ["Four letters, the word in the warning itself. It also works on go run and go build."] = "四文字、警告の中にそのままある語。go run や go build にも効く。",
  ["Four letters, what a shell puts between two commands. It returns two ends."] = "四文字、シェルが二つのコマンドの間に置くもの。両端を返す。",
  ["Four letters. An alias of int32. byte is the alias of uint8."] = "4文字。int32 の別名です。byte は uint8 の別名。",
  ["Four letters. Consumes the handle and returns Result<T, Box<dyn Any + Send>>."] = "4 文字。ハンドルを消費して Result<T, Box<dyn Any + Send>> を返す。",
  ["Four letters. Every file may have one; the runtime calls it for you."] = "4文字。各ファイルに置けます。ランタイムが代わりに呼びます。",
  ["Four letters. Go fakes it with const and iota; Rust has the real thing."] = "4 文字。Go は const と iota でまねをする。Rust には本物がある。",
  ["Four letters. Go writes for { } with no condition; Rust has a word for it."] = "4 文字。Go は条件なしの for { } と書く。Rust には専用の単語がある。",
  ["Four letters. Go's append, but it changes the Vec in place, so it needs mut."] = "4 文字。Go の append だが、Vec をその場で変えるので mut が要る。",
  ["Four letters. Go's receiver (o *Order), Rust's &self, but here it is an ordinary parameter by convention."] = "4文字。Go のレシーバ (o *Order)、Rust の &self。でもここでは慣例による普通の引数。",
  ["Four letters. It also builds maps and channels."] = "4文字。map や channel も作れます。",
  ["Four letters. It answers the question 'what type is this'. isinstance(x, float) is the check you use in code."] = "4文字。「これは何の型か」に答える。コードで使うチェックは isinstance(x, float)。",
  ["Four letters. It counts the group down; Add counted it up."] = "四文字。グループを一つ減らす。増やしたのは Add。",
  ["Four letters. Let go of it now instead of at the end of scope."] = "4 文字。スコープの終わりではなく、今手放す。",
  ["Four letters. Like std::mem::take: gives you the value, puts the default (None) back."] = "4 文字。std::mem::take のように、値を渡してデフォルト (None) を戻す。",
  ["Four letters. Not copied: the heap buffer changed hands."] = "4 文字。コピーではない: ヒープのバッファが持ち主を変えた。",
  ["Four letters. Take it, do not borrow it."] = "4 文字。借りるのではなく、持っていく。",
  ["Four letters. The From trait gives it to you. to_string() does the same job."] = "4文字。From トレイトが与えてくれる。to_string() も同じ仕事をする。",
  ["Four letters. The block gets one from the operating system, like a file in /dev/shm."] = "四文字。この塊は OS から一つもらう。/dev/shm の中のファイル名のようなものだ。",
  ["Four letters. The borrowing one. into_ in front of it would consume the Vec."] = "4文字。借用するほう。前に into_ を付けると Vec を消費してしまう。",
  ["Four letters. The channel is closed when the context is finished, so every watcher wakes at once."] = "四文字。context が終わるとその channel は閉じられ、見張っている全員が同時に起きる。",
  ["Four letters. The opposite of None."] = "4 文字。None の反対。",
  ["Four letters. The same keyword that opens a block of methods, used as a type."] = "4文字。メソッドのブロックを開くのと同じキーワードを、型として使う。",
  ["Four letters. The same word that starts an implementation block."] = "4 文字。実装ブロックを始めるのと同じ単語。",
  ["Four letters. The same word you put in the attribute over the function."] = "4文字。関数の上の属性に書くのと同じ単語。",
  ["Four letters. The word that follows if. The block must diverge: return, break, panic."] = "4文字。if の後に続く単語。ブロックは発散しなければならない: return、break、panic。",
  ["Four letters. Threads use the same word to wait for each other."] = "4文字。スレッドがお互いを待つのにも同じ単語を使う。",
  ["Four letters. What Rust does for you at the end of every scope, called by hand."] = "4 文字。Rust がスコープの終わりごとにやってくれることを、手で呼ぶ。",
  ["Four letters. What you do to a menu."] = "4 文字。メニューにすること。",
  ["Four letters. What you do to a paper napkin, over and over, into one small square."] = "4文字。紙ナプキンに何度も何度もやって、小さな四角ひとつにすること。",
  ["Four letters. What you do to the drawer at closing time."] = "4 文字。閉店時に引き出しにすること。",
  ["Four letters. What you do with a parcel."] = "4 文字。小包にすること。",
  ["Four letters. Where two roads meet again."] = "4 文字。2 本の道がまた合流するところ。",
  ["Four letters. fork gives one lazily, spawn makes one from the pickle. Either way it is not yours."] = "四文字。fork は遅延して一つくれ、spawn は pickle から作る。どちらにせよ、あなたのものではない。",
  ["Four letters: a look at the top. Returns Option<&T>, hence the * and the unwrap."] = "4文字: 一番上をのぞく。Option<&T> を返すので * と unwrap が付く。",
  ["Four letters: else and if squeezed into one word."] = "4文字: else と if を1語に押し込んだもの。",
  ["Four letters: make it neat. Run it before every commit."] = "4文字: 片付ける。コミット前に毎回実行しましょう。",
  ["Four letters: my, and the language's first two. pyright is the other common one."] = "4文字: my、そしてこの言語の頭2文字。pyright がもう1つのよくあるほう。",
  ["Four letters: the one after this one. Rust's iterator method has the same name."] = "4文字: これの次のもの。Rust のイテレータメソッドも同じ名前。",
  ["Four letters: what the threads finally are, and what the build is called."] = "四文字：スレッドがついにそうなった状態であり、ビルドの名前でもある。",
  ["Four quests: BASIC, ADVANCED, DELIVERY, CODE RUSH. Q switches."] = "4つのクエスト: 基本、上級、デリバリー、コードラッシュ。Q で切替。",
  ["Four recursive calls, each O(1) plus its own flood: every cell is sunk once, so the whole grid is O(rows * cols)."] = "4回の再帰呼び出し、それぞれ O(1) と自分の洪水: 各セルは1回だけ沈むので、グリッド全体で O(rows * cols)。",
  ["Four workers, many eggs, no hand-made threads. Which executor from concurrent.futures?"] = "ワーカー4人、卵たくさん、手作りスレッドなし。concurrent.futures のどの executor？",
  ["Fprintf writes to any io.Writer: files, buffers, network, ResponseWriter."] = "Fprintf は任意の io.Writer に書きます: ファイル、バッファ、ネットワーク、ResponseWriter。",
  ["Free the tray right now, before the end of the block. Which function?"] = "ブロックの終わりを待たず、今すぐトレイを解放する。関数は？",
  ["From a str. Two words with an underscore, like the FromStr trait in lowercase."] = "str から。アンダースコアでつないだ2単語、FromStr トレイトを小文字にしたような形。",
  ["From m to the end. a[:m] and a[m:] cover the slice exactly once."] = "m から末尾まで。a[:m] と a[m:] で slice をちょうど 1 回ずつ覆います。",
  ["Functions and Option"] = "関数と Option",
  ["Functions and returns"] = "関数と戻り値",
  ["Futures need a runtime. Which attribute makes main async on tokio?"] = "Future にはランタイムが必要。main を tokio 上で async にする属性は？",
  ["GO SET  -  the walk"] = "GO SET  -  道のり",
  ["GOMAXPROCS(0) reports without changing it. Thousands of goroutines still exist; only this many are running Go code at any instant."] = "GOMAXPROCS(0) は変えずに報告するだけ。goroutine は何千あってもよく、どの瞬間も Go のコードを走らせているのはこの数だけだ。",
  ["Generators and iterators"] = "ジェネレータとイテレータ",
  ["Generics and trait bounds"] = "ジェネリクスとトレイト境界",
  ["Generics, embedding, closures"] = "Generics、埋め込み、closure",
  ["Generics. Say <T> and tell the compiler what T can do."] = "ジェネリクス。<T> と書いて、T に何ができるかコンパイラに教える。",
  ["Get the guard so you can change the counter. Which method?"] = "カウンタを変えられるようガードを取る。メソッドは？",
  ["Get, Put and evict all O(1): that is the whole point of the LRU question."] = "Get、Put、追い出しがすべて O(1): それが LRU 問題のすべて。",
  ["Get: a hit becomes the most recently used. Which list method moves the node to the front?"] = "Get: ヒットしたら最近使ったものになる。ノードを先頭に移すリストのメソッドは？",
  ["Give me a pipe. Send on one end, I receive on the other."] = "パイプをくれ。片方の端で送って、もう片方でぼくが受け取る。",
  ["Give the ETA call two seconds and no more. Which constructor?"] = "ETA の呼び出しに二秒だけ与える。どのコンストラクタ？",
  ["Give the error a human message for {}. Which fmt trait?"] = "エラーに {} 用の人間向けメッセージを与える。fmt のどのトレイト？",
  ["Give the future room for one result so a lost caller cannot strand the goroutine."] = "誰も取りに来なくても goroutine が取り残されないよう、future に結果一つ分の場所を与える。",
  ["Give the opened file a name inside the block. Which keyword?"] = "ブロック内で開いたファイルに名前を付ける。どのキーワード？",
  ["Give up after one second. Fill: case <-time.___(time.Second)"] = "1秒で諦める。埋めて：case <-time.___(time.Second)",
  ["Gives index and value. The blank _ throws the index away."] = "インデックスと値を返します。_ でインデックスを捨てます。",
  ["Global Interpreter Lock, by its initials."] = "Global Interpreter Lock の頭文字。",
  ["Global Interpreter Lock, said as one word."] = "Global Interpreter Lock を一語で言ったもの。",
  ["Go + routine. Not a full OS thread. The scheduler parks them."] = "Go + routine。本物の OS スレッドではない。スケジューラが待機させます。",
  ["Go 1.21 has a builtin for the smaller of two numbers."] = "Go 1.21 には 2 つの数の小さい方を返す builtin がある。",
  ["Go 1.21 wraps that pattern and caches the result. Which sync helper?"] = "Go 1.21 はそのパターンを包み、結果までキャッシュする。どの sync ヘルパー？",
  ["Go 1.21-1.23: slices, maps, min, iterators"] = "Go 1.21-1.23: slices、maps、min、イテレータ",
  ["Go 1.22 loops over a plain number. Fill: for i := ___ 3"] = "Go 1.22 はただの数値でループできます。埋めてください: for i := ___ 3",
  ["Go had goroutines. Where is the go keyword?"] = "Go には goroutine があった。go キーワードはどこ？",
  ["Go has no async and no await, on purpose. A goroutine plus a buffered channel is a future: go starts it, <-ch awaits it. The runtime parks a goroutine that blocks on I/O and runs another on the same OS thread, so ordinary blocking code is already asynchronous. errgroup runs a batch and returns the first error; runtime.NumGoroutine() shows the ones you forgot to stop."] = "Go には async も await もない。わざとだ。goroutine とバッファ付き channel が future になる：go が始め、<-ch が待つ。ランタイムは I/O で止まった goroutine を退避させ、同じ OS スレッドで別のものを走らせるので、ふつうのブロッキングコードがすでに非同期だ。errgroup は一束を走らせて最初のエラーを返し、runtime.NumGoroutine() は止め忘れたものを映し出す。",
  ["Go has no set type; a map to this type is the idiom. struct{} also works."] = "Go に set 型はなく、この型への map が定石。struct{} でも可。",
  ["Go has no while. Which keyword loops while i < 8?"] = "Goに while はありません。i < 8 の間ループするキーワードは？",
  ["Go has one loop: for. if needs no parentheses. range walks a slice."] = "Goのループは for だけ。if に括弧は不要。range で slice をたどります。",
  ["Go has structs and methods. Here the method gets self by hand?"] = "Go には struct とメソッドがある。ここではメソッドが self を手で受け取るのか？",
  ["Go never converts numbers silently. Type name, then parentheses. 64-bit float."] = "Goは数値を暗黙に変換しません。型名、そのあと括弧。64ビットの浮動小数点。",
  ["Go never leaves a variable uninitialized. Numbers start here."] = "Goは変数を未初期化のままにしません。数値はここから始まります。",
  ["Go returns errors. Python throws them. Catch the one you expect, let the rest fly."] = "Go はエラーを返す。Python は投げる。予期したものを捕まえ、残りは飛ばせておけ。",
  ["Go spells every loop for; Python has this second word for the condition-only loop."] = "Go はすべてのループを for と綴る。Python には条件だけを見るループのための2つ目の単語がある。",
  ["Go, Chef! Same seven rounds as this afternoon. The memo one is a one-liner in Python."] = "頑張って、シェフ！ 午後と同じ7ラウンド。memo の問題は Python なら一行よ。",
  ["Go, Mei! I did this show at lunch. The memo one gets everybody."] = "メイ、いけ！昼にこの番組に出たんだ。メモの問題はみんなやられる。",
  ["Goroutines"] = "Goroutine",
  ["Goroutines, then. What is the Python word?"] = "つまり goroutine か。Python では何と言う？",
  ["Graphs: BFS and DFS"] = "グラフ: BFS と DFS",
  ["Greater than or equal. With > alone, g[g.len()] would panic."] = "以上。> だけだと g[g.len()] が panic する。",
  ["Greedy fails on coins {1,3,4} for 6 (4+1+1). DP tries every last coin and finds 3+3."] = "貪欲法はコイン {1,3,4} で 6 に失敗する (4+1+1)。DP は最後のコインを全部試して 3+3 を見つける。",
  ["Grill and Wok are different sizes. What element type lets one Vec hold both?"] = "Grill と Wok はサイズが違う。1 つの Vec に両方を入れられる要素型は？",
  ["Grill promises to be a Cook. Complete the header."] = "Grill は Cook であることを約束する。ヘッダーを完成させて。",
  ["Grill, wok, steamer. Every station must answer name() and greet()."] = "グリル、中華鍋、蒸し器。どのステーションも name() と greet() に答えなければならない。",
  ["Group an item name and a quantity under one named type. Which keyword?"] = "品名と数量を 1 つの名前付き型にまとめる。キーワードは？",
  ["Group name and price in one type. Which keyword?"] = "名前と価格を1つの型にまとめる。キーワードは？",
  ["Grow a slice by one hash brown. Which built-in?"] = "slice にハッシュブラウンを1つ追加する。組み込み関数は？",
  ["HERE"] = "ここ",
  ["HIDE"] = "隠す",
  ["HINT"] = "ヒント",
  ["Half-open [lo, hi): loop while lo < hi, no off-by-one."] = "半開区間 [lo, hi): lo < hi の間ループ、off-by-one なし。",
  ["Halve the gap. (lo+hi)/2 can overflow in other languages; this form never does."] = "差を半分に。(lo+hi)/2 は他言語でオーバーフローしうるが、この形なら決してしません。",
  ["Halve, halve, halve, then zip the halves back together. Ties go left."] = "半分、半分、半分、それから半分どうしを噛み合わせて戻す。同点なら左が先。",
  ["Halving gives log n levels. Integer division: 5 / 2 is 2, and that is fine."] = "半分にすれば段数は log n。整数の除算: 5 / 2 は 2 で、それでいい。",
  ["Hand both values back to the caller. Which keyword?"] = "両方の値を呼び出し元に返す。キーワードは？",
  ["Hand out one bowl at a time and pause. Which keyword makes a function a generator?"] = "丼を一杯ずつ渡して一時停止する。関数をジェネレータにするキーワードは？",
  ["Hand the total back to the caller. Which keyword?"] = "合計を呼び出し元に返す。どのキーワード？",
  ["Hand the value to one owner over a channel and there is nothing to lock. The order belongs to whoever received it."] = "channel で値を一人の持ち主に渡せば、ロックするものは何もない。注文は受け取った側のものだ。",
  ["Handle + Func. Plain Handle takes an http.Handler value instead."] = "Handle + Func。ただの Handle は代わりに http.Handler 値を受け取ります。",
  ["HandleFunc maps a path to func(w, r). Fprintf(w) replies. ListenAndServe runs."] = "HandleFunc はパスを func(w, r) に対応付け。Fprintf(w) で返信。ListenAndServe で起動。",
  ['HandleFunc registers on the default mux. Go 1.22 routes can say "GET /order/{id}".'] = 'HandleFunc はデフォルトの mux に登録します。Go 1.22 のルートは "GET /order/{id}" と書けます。',
  ["Hash brown on one burner. Muffin on another. Both at once."] = "ハッシュブラウンはこのコンロ。マフィンはあっち。同時に。",
  ["Hash maps, chars and counts"] = "ハッシュマップ、文字、そして数え上げ",
  ["HashMap: O(1) average, O(n) worst case when everything collides. BTreeMap is O(log n) but ordered."] = "HashMap: 平均 O(1)、すべてが衝突すれば最悪 O(n)。BTreeMap は O(log n) だが順序付き。",
  ["HashMap<u32, Vec<u32>>: O(1) to find a station, then its neighbours in order. g[&n] panics on a missing key; get returns Option."] = "HashMap<u32, Vec<u32>>: 駅を見つけるのは O(1)、その隣は順番どおり。g[&n] はキーがないと panic する。get なら Option を返す。",
  ["HashSet: one O(1) insert per guest, O(n) total. Fifty million checks become ten thousand."] = "HashSet: 客ごとに O(1) の insert 1回、合計 O(n)。5000万回のチェックが1万回になる。",
  ["Have we seen the partner of x? Fill the lookup: seen[target-x]"] = "x の相方は見た？検索を穴埋め: seen[target-x]",
  ["Height is one plus the taller child. Which built-in picks the taller?"] = "高さは1足す背の高いほうの子。背の高いほうを選ぶ組み込み関数は？",
  ["Height is one plus the taller subtree. Fill: 1 + max(height(n.Left), height(n.___))"] = "高さは 1 + 高い方の部分木。穴埋め: 1 + max(height(n.Left), height(n.___))",
  ["Hello, Python"] = "こんにちは、Python",
  ["Hello, Rust"] = "こんにちは、Rust",
  ["Hints document types without enforcing them: def f(x: int) -> str. list[str], dict[str, float], Optional[str]. mypy checks them before you run."] = "ヒントは型を強制せずに記録する: def f(x: int) -> str。list[str]、dict[str, float]、Optional[str]。mypy が実行前にチェックする。",
  ["How big a batch each worker collects per trip. One word, no underscore."] = "ワーカーが一往復で受け取る束の大きさ。一語、アンダースコアなし。",
  ["How many goroutines may run Go code at the same instant? Which setting?"] = "同じ瞬間に Go のコードを走らせられる goroutine は何個？ どの設定？",
  ["How many items are in prices? Which method returns a usize?"] = "prices の要素はいくつ？usize を返すメソッドは？",
  ["How many items are in the slice right now? Which built-in?"] = "今 slice に要素はいくつ？ 組み込み関数は？",
  ["How many items fit before append must reallocate? Which built-in?"] = "append が再確保するまでに何個入る？ 組み込み関数は？",
  ["How many trays? Which built-in counts a list?"] = "トレイはいくつ？ リストを数える組み込み関数は？",
  ["How many workers? Ask the machine. Which function?"] = "ワーカーは何個？ 機械に訊こう。どの関数？",
  ["How much room does the belt have in total? Which builtin?"] = "このベルトには全部で何台分の場所がある？ どの組み込み？",
  ["I copied the threading code, changed one word, and the script started itself forever."] = "threading のコードを写して一語だけ変えたら、スクリプトが永遠に自分を起動しはじめた。",
  ["I gave the photo job eight threads. The fan spun up and the clock did not move."] = "写真の仕事にスレッドを八本与えた。ファンは回り出したが、時計は動かなかった。",
  ["If dp[amount] never dropped below the marker, no combination works. What does the function return then?"] = "dp[amount] が印より下がらなかったなら、どの組み合わせも無理。そのとき関数は何を返す？",
  ["If no combination reaches the amount, its cell still holds the sentinel. Return what?"] = "どの組み合わせも金額に届かなければ、そのセルはまだ番兵のまま。何を返す？",
  ["If the amount is still infinite, no coins reach it. What does the function return then?"] = "金額がまだ無限大なら、どのコインも届かない。そのとき関数は何を返す？",
  ["If the guest leaves, cancel. The fryer stops."] = "客が帰ったらキャンセル。フライヤーが止まる。",
  ["If there is a loop the fast runner laps the slow one. O(1) memory."] = "ループがあれば fast が slow を周回遅れにします。メモリ O(1)。",
  ["If you miss the word, write it yourself. Fill the body of Await."] = "その単語が恋しいなら自分で書けばいい。Await の中身を埋めよう。",
  ["In Go I would write a json tag. Show me the Rust way."] = "Go なら json タグを書く。Rust のやり方を見せて。",
  ["In Go this was three pointers. In Rust, who owns the next node?"] = "Go ではポインタ 3 本だった。Rust では、次のノードを所有するのは誰？",
  ["In JavaScript I would write await fetchMenu(). Go's editor does not even know the word."] = "JavaScript なら await fetchMenu() と書くのに。Go のエディタはその単語すら知らない。",
  ["In Rust the compiler stops you. In Go nothing stops you, so the race detector is the compiler you run at test time."] = "Rust ではコンパイラが止めてくれる。Go では誰も止めないから、レース検出器がテスト時に走らせるコンパイラなの。",
  ["In Rust, if gives back a value. No ternary needed. The gate forgot its else."] = "Rust では if が値を返す。三項演算子はいらない。ゲートは else を忘れてた。",
  ["In a {start, end} pair, the end is the second element."] = "{start, end} の組で、end は 2 番目の要素。",
  ["In order, smallest to largest. The line above the search does it."] = "順番通り、小さいものから大きいものへ。探索の上の行がそれをする。",
  ["In real code None is more honest. key in self.d is O(1): a hash lookup."] = "実際のコードでは None のほうが正直。key in self.d は O(1): ハッシュ検索。",
  ["In real code: sort a slice of structs by price. Fill: sort.___(orders, func(i, j int) bool {...})"] = "実務では: struct の slice を価格でソート。穴埋め: sort.___(orders, func(i, j int) bool {...})",
  ["In-order on a BST yields sorted output. Pre-order (self first) copies a tree; post-order (self last) frees one."] = "BST の中順巡回はソート済みの出力を生む。前順（自分が先）は木をコピーし、後順（自分が最後）は木を解放する。",
  ["In-order on a BST yields sorted output. Pre-order: node first. Post-order: node last."] = "BST を in-order で巡回するとソート済みに。pre-order: ノードが先。post-order: ノードが最後。",
  ["In-order walk: left subtree, this node, then which subtree? That gives sorted output."] = "中順の走査: 左の部分木、このノード、次はどの部分木？それでソート済みの出力になる。",
  ["Inclusive count from l to r: the difference, plus one."] = "l から r までの両端込みの個数: 差に 1 を足す。",
  ["Increment a counter without a mutex. Which package? ___.AddInt64(&count, 1)"] = "mutex なしでカウンタを増やす。パッケージは？___.AddInt64(&count, 1)",
  ["Indexes start at 0, so the last one is one less than the count. len itself is O(1): Go keeps it in the slice header."] = "インデックスは 0 から始まるので、最後は個数より1小さい。len 自体は O(1): Go はスライスヘッダに保持する。",
  ["Indexes start at 0, so the last one is the length less one. One character."] = "インデックスは 0 から始まるので、最後は長さ引く1。1文字。",
  ["Insert at the recent end and get the new node back."] = "最新側に挿入し、新しいノードを受け取る。",
  ["Inside Lucky Mac Express the kitchen runs on Rust threads. Earn the tea set."] = "ラッキーマック Express のキッチンは Rust のスレッドで動く。ティーセットを手に入れよう。",
  ["Inside Lucky Mac the kitchen runs on goroutines. Earn the morning set."] = "ラッキーマックのキッチンは goroutine で動く。モーニングセットを手に入れよう。",
  ["Is ErrCold anywhere in that chain? Fill: errors.___(err, ErrCold)"] = "チェーンのどこかに ErrCold はある？埋めてください: errors.___(err, ErrCold)",
  ["Is a name in the Vec? Without a set you must look at each one. Which iterator adapter stops at the first match?"] = "名前は Vec にある？ set なしでは各要素を見なければならない。最初の一致で止まるイテレータアダプタは？",
  ["Is a name in the list? Python has a keyword for it, but on a list it scans. Which keyword?"] = "名前はリストにある？ Python にはそのためのキーワードがあるが、リストでは走査する。どのキーワード？",
  ["Is a name in the slice? Without a map you must look at each one. Which keyword walks the slice?"] = "名前はスライスにある？ map なしでは各要素を見なければならない。スライスを歩くキーワードは？",
  ['Is muffin on the list? Fill: slices.___(names, "muffin")'] = 'muffin はリストにある？埋めてください: slices.___(names, "muffin")',
  ["Is the ETA Some and under 10 minutes, in one call, no unwrap? Which Option method?"] = "ETA が Some かつ 10 分未満かを、1回の呼び出しで unwrap なしに。Option のどのメソッド？",
  ["It appended to its own copy. Nothing crosses a process boundary unless you send it."] = "自分のコピーに append したんだよ。送らない限り、プロセスの境界を越えるものは何もない。",
  ["It closes over n. Inner func, outer variable."] = "n を閉じ込めます。内側の func、外側の変数。",
  ["It did not fall over. It just made the kitchen printer thrash. Give me a queue and a few workers."] = "倒れはしなかった。ただ厨房のプリンタが暴れただけだ。行列とワーカー数人をくれ。",
  ["It is an operating-system semaphore under the hood, so it works across processes. Like a Queue, it must be created in the parent and passed down."] = "中身は OS のセマフォなので、プロセスをまたいでも効く。Queue と同じく、親で作って渡さねばならない。",
  ["It returns the *Element the map needs. An existing key is an update plus a touch, not a second node."] = "map に必要な *Element を返す。既存キーは更新プラス触るだけで、2 つ目のノードではない。",
  ["It runs on your laptop. Make it build on the shop's machine."] = "自分のノートPCでは動く。店のマシンでもビルドできるようにして。",
  ["It's DFS, Mei, same as the MTR round, but the neighbours are up, down, left, right. Mind the usize!"] = "DFS だ、メイ、MTR のラウンドと同じ。ただし隣は上下左右。usize に気をつけろ！",
  ["It's fib in a hat, Chef. Then the coin one: fewest coins for the exact change."] = "帽子をかぶった fib よ、シェフ。次はコインの問題: ぴったりの釣り銭を最少枚数で。",
  ["It's fib with a table instead of a memo. Bottom up, Mei. No recursion, no stack overflow."] = "memo の代わりに表を使う fib だ。ボトムアップだ、メイ。再帰なし、スタックオーバーフローなし。",
  ["It's the graph round in disguise, Bo. Sink every island as you find it, and count the finds."] = "変装したグラフのラウンドよ、ボー。見つけた島を全部沈めて、見つけた数を数える。",
  ["Iterator::eq compares two iterators without building a String. chars() walks Unicode scalars, not bytes."] = "Iterator::eq は String を作らずに 2 つのイテレータを比べる。chars() はバイトでなく Unicode スカラ値を歩く。",
  ["Iterators and closures"] = "イテレータとクロージャ",
  ["JoinHandle<T>: T is what the closure returns, here (). Drop the handle and the thread is detached, still running."] = "JoinHandle<T>: T はクロージャの戻り値、ここでは ()。ハンドルを drop するとスレッドは切り離され、走り続ける。",
  ["Jumps to the next iteration. break would leave the loop entirely."] = "次の繰り返しへ飛びます。break だとループを完全に抜けてしまいます。",
  ["Just the size, no coefficient. 2n, 3n and n/2 are all the same order."] = "大きさだけ、係数なし。2n、3n、n/2 はすべて同じオーダー。",
  ["Just the size, no coefficient. 2n, 3n and n/2 are the same order."] = "大きさだけ、係数なし。2n、3n、n/2 は同じオーダー。",
  ["Just the sum. Adding a semicolon would turn it into a statement and return ()."] = "和だけ。セミコロンを足すと文になって () を返してしまう。",
  ["Kadane's algorithm: O(n), one pass, two variables. A negative prefix is never worth keeping."] = "Kadane のアルゴリズム: O(n)、一回通り、変数 2 つ。マイナスの接頭部は持つ価値がない。",
  ["Kadane's algorithm: O(n), one pass, two variables. A negative run never helps, so it is dropped."] = "Kadane のアルゴリズム: O(n)、一回の走査、変数2つ。マイナスの連続は役に立たないので捨てられる。",
  ["Kadane's algorithm: a negative run is worth dropping. O(n) time, O(1) space, no nested loop."] = "Kadane のアルゴリズム: マイナスの連なりは捨てる価値がある。時間 O(n)、空間 O(1)、入れ子ループなし。",
  ["Kadane: at each x, extend the run or restart at x, keep the best. A fixed window adds the newcomer and drops a[i-k]. Two pointers only move right: O(n) for the longest substring without repeats."] = "Kadane: 各 x で走りを伸ばすか x から再開し、最良を保つ。固定幅の窓は新入りを足して a[i-k] を落とす。2 ポインタは右にしか動かない: 重複なしの最長部分文字列が O(n)。",
  ["Kadane: cur = max(x, cur + x), best = max(best, cur). A fixed window adds one and drops one. A growing window moves l forward until the window is clean again."] = "Kadane: cur = max(x, cur + x)、best = max(best, cur)。固定窓は1つ足して1つ落とす。伸びる窓は、窓がきれいになるまで l を前へ進める。",
  ["Kadane: cur = x.max(cur + x). A fixed window adds the new item and drops the old one. A growing window moves its left end while a HashSet says repeat. Two pointers walk in from both ends of a sorted slice."] = "Kadane: cur = x.max(cur + x)。固定窓は新しい要素を足して古いのを落とす。伸びる窓は HashSet が「重複」と言う間、左端を進める。2つのポインタはソート済みスライスの両端から歩み寄る。",
  ["Keep a AND give b its own copy of the text. Which method?"] = "a を残したまま、b にもテキストの独自コピーを渡す。メソッドは？",
  ["Keep a tiny heap of the k biggest. Whatever falls out was never the answer."] = "最大 k 個の小さなヒープを持て。こぼれ落ちたものは最初から答えじゃない。",
  ["Keep only paid orders. Which adapter takes a bool closure?"] = "支払い済みの注文だけ残す。bool を返すクロージャを受け取るアダプタは？",
  ["Keep only three, Chef. The smallest of the three is the answer; throw out anything smaller."] = "3つだけ持つのよ、シェフ。3つの中の最小が答え。それより小さいものは捨てる。",
  ["Keep serving as long as the queue is not empty. Which keyword loops on a condition?"] = "列が空でない限り出し続ける。条件でループするキーワードは？",
  ["Keyword chan, then the element type. make allocates it."] = "キーワード chan、次に要素型。make が確保します。",
  ["Kitchen should gain Grill's methods without wrapping. Put Grill where?"] = "Kitchen にラップなしで Grill のメソッドを持たせたい。Grill をどこに置く？",
  ["Know the algorithm for the whiteboard, use the library in production."] = "ホワイトボードではアルゴリズムを、本番ではライブラリを。",
  ["Kth largest: keep a min-heap of the k largest so far. When it grows past k, which heap call drops the smallest?"] = "k 番目に大きい値: これまでの最大 k 個の min-heap を持つ。k を超えたら、最小を落とすヒープの呼び出しは？",
  ["LAND"] = "横",
  ["LEVEL UP!  LV %d"] = "レベルアップ！  LV %d",
  ["LRU cache"] = "LRU キャッシュ",
  ["LRU: a HashMap for the values and a VecDeque for recency, fresh at the back, stale at the front. get moves the key to the back. put evicts the front when full, then inserts. The O(1) version swaps the VecDeque for a linked list."] = "LRU: 値は HashMap、新しさは VecDeque で、新しいのは後ろ、古いのは前。get はキーを後ろへ動かす。put は満杯なら前を追い出してから挿入。O(1) 版は VecDeque を連結リストに換える。",
  ["LRU: a map from key to *list.Element plus a container/list in recency order. Get moves the node to the front, Put pushes a new one at the front, over capacity evicts l.Back() from both the list and the map. Every operation O(1)."] = "LRU: キーから *list.Element への map と、新しい順の container/list。Get はノードを先頭へ移し、Put は新しいものを先頭に押し込み、容量超過なら l.Back() をリストと map の両方から追い出す。すべての操作が O(1)。",
  ["LRU: least recently used goes first. OrderedDict remembers order: move_to_end on every use, popitem(last=False) evicts the oldest. get and put are O(1). functools.lru_cache is the built-in."] = "LRU: 最も長く使われていないものから出ていく。OrderedDict は順序を覚える: 使うたびに move_to_end、popitem(last=False) が最古を追い出す。get と put は O(1)。functools.lru_cache が組み込み。",
  ["LV %d   XP %d / %d"] = "LV %d   XP %d / %d",
  ["LV %d  ·  %d XP  ·  %d badges"] = "LV %d  ·  %d XP  ·  バッジ %d 個",
  ["Last board of the night, Python column. Same question: input doubles, then what?"] = "今夜最後のボード、Python の列。同じ問い: 入力が倍になったら、それで？",
  ["Last customers before the shutter. The queue script decides who gets a bowl."] = "シャッターの前の最後のお客さん。行列スクリプトが誰に丼を出すか決めるの。",
  ["Last one. A map of Victoria Harbour as ones and zeros. How many islands?"] = "最後の 1 問。ビクトリアハーバーの地図を 1 と 0 で。島はいくつ？",
  ["Last ticket. Code review. Every match with one arm and an early return gets a modern spelling."] = "最後のチケット。コードレビュー。アームひとつと早期 return の match は全部、今どきの書き方に。",
  ["Least recently used. A map for the values and a queue for the order; every get is a touch."] = "最も長く使われていないもの。値はマップ、順序はキュー。get のたびにタッチだ。",
  ["Leave note out of the JSON when it is empty. Fill the tag option."] = "note が空なら JSON から外します。タグのオプションを埋めてください。",
  ["Leave the function early when n is 0. Which keyword?"] = "n が 0 なら関数を早めに抜ける。キーワードは？",
  ["Leave the note out of the JSON when it is None. Which attribute?"] = "note が None のときは JSON から外す。どの属性？",
  ["Left, node, right: a BST walked in order comes out sorted. if let on &Link needs no unwrap."] = "左、ノード、右: BST を中順で歩けばソート済みで出てくる。&Link への if let に unwrap は要らない。",
  ["Left, self, then which side, to print the values in sorted order?"] = "左、自分、それからどちら側で、値をソート順に印字できる？",
  ["Left: the same row, one column back."] = "左: 同じ行、1 列戻る。",
  ["Len, Less, Swap take a value; Push and Pop take a pointer because they resize the slice."] = "Len、Less、Swap は値を取り、Push と Pop は slice をサイズ変更するのでポインタを取る。",
  ["Less than or equal. With a strict < equal items would swap order and the sort would not be stable."] = "以下。厳密な < だと等しい項目が順序を入れ替え、ソートは安定でなくなる。",
  ["Less than or equal: the equal case is the touching pair."] = "以下。等しい場合が接する組。",
  ["Less than, or equal. A strict < would take the right one on a tie and break stability."] = "より小さい、または等しい。厳密な < だと同点で右を取ってしまい、安定性が壊れる。",
  ["Let ? turn a ParseIntError into OrderError by itself. Which trait do you implement?"] = "? が ParseIntError を勝手に OrderError に変えるようにする。実装するトレイトは？",
  ["Let count() read the String without taking it. Which symbol goes before the type?"] = "count() が String を奪わずに読めるようにする。型の前に置く記号は？",
  ["Let println! print the whole struct with {:?}. Which attribute word generates Debug?"] = "println! が {:?} で struct 全体を出力できるようにする。Debug を生成する属性の単語は？",
  ["Let serde write the JSON code for the struct. Which trait goes with Deserialize?"] = "構造体の JSON コードを serde に書かせる。Deserialize と対になるトレイトは？",
  ["Level by level with a deque: take from the front. Which method?"] = "deque で階層ごとに: 前から取る。どのメソッド？",
  ["Lifetimes"] = "ライフタイム",
  ["Like %v, but with w for wrap. errors.Unwrap gets the inner error back."] = "%v に似ていますが、wrap の w。errors.Unwrap で内側の error を取り出せます。",
  ["Like fmt.Errorf but on t. Fatalf would stop this test at once."] = "fmt.Errorf に似た t のメソッド。Fatalf ならこのテストは即停止です。",
  ["Like last(), with the suffix every mutable borrow in std carries."] = "last() に、std の可変借用がみな持つ接尾辞を付けて。",
  ["Like unwrap, but with your own panic message. Which method?"] = "unwrap と同じだが、panic メッセージを自分で書く。メソッドは？",
  ["Linear time"] = "線形時間",
  ["Linear: the work grows in step with the input. A one-word built-in is still a loop underneath."] = "線形: 仕事は入力と歩調を合わせて増える。一語の組み込みも、下ではやはりループ。",
  ["Linear: the work grows in step with the input. Iterator chains hide the loop but not the cost."] = "線形: 仕事は入力と歩調を合わせて増える。イテレータチェーンはループを隠すがコストは隠さない。",
  ["Linear: the work grows in step with the input. Write it with a capital O and the size in brackets."] = "線形: 仕事は入力と歩調を合わせて増える。大文字の O と括弧の中の大きさで書く。",
  ["Linked list without pointers"] = "ポインタなしの連結リスト",
  ["Linked list: reverse, cycle"] = "連結リスト: 反転と循環",
  ["Linked lists"] = "連結リスト",
  ["Listen, And, Serve. Returns only on error, hence log.Fatal."] = "Listen、And、Serve。error のときだけ返るので log.Fatal。",
  ["ListenAndServe blocks forever. Every request runs in its own goroutine."] = "ListenAndServe は永遠にブロックします。各リクエストは自分の goroutine で動きます。",
  ["Lists and slices"] = "リストとスライス",
  ["Load and Store are the read and write. Reading the field directly is a data race even for one int."] = "Load と Store が読みと書き。フィールドを直接読むのは、int 一つでもデータレースだ。",
  ["Lock a shared counter. Fill the type: var mu sync.___"] = "共有カウンタをロック。型を埋めて：var mu sync.___",
  ["Lock then defer Unlock, on the next line, always. A lock released only on the happy path is a deadlock waiting for the first error."] = "Lock の次の行に必ず defer Unlock。うまくいった経路でしか解放しないロックは、最初のエラーを待つデッドロックだ。",
  ["Lock; defer Unlock is the pattern. A forgotten Unlock deadlocks the next caller."] = "Lock; defer Unlock が定番。Unlock を忘れると次の呼び出し側がデッドロックします。",
  ["Locks, Value and Manager"] = "ロック、Value、Manager",
  ["Log each total the moment it lands, in any order. Which helper?"] = "合計が届いた瞬間に順不同で記録する。どのヘルパー？",
  ["Logarithmic time"] = "対数時間",
  ["Logarithmic: O of the logarithm of n. The base does not matter in Big O."] = "対数: n の対数の O。Big O では底は関係ない。",
  ["Long bounds go under the signature. Which keyword starts that clause?"] = "長い境界はシグネチャの下に書く。その節を始めるキーワードは？",
  ["Longest run of distinct bytes: a window [l, r] and a HashSet of what is inside. When b[r] is already in, drop from the left until it is not. Which HashSet method removes?"] = "相異なるバイトの最長の連なり: 窓 [l, r] と中身の HashSet。b[r] がすでに中にあれば、なくなるまで左から落とす。取り除く HashSet のメソッドは？",
  ["Longest run with no repeated dish. When c is already in the window, drop from the left until it is not. Which set method?"] = "料理が重ならない最長の連続。c がすでに窓の中なら、なくなるまで左から落とす。どの set メソッド？",
  ["Longest substring without a repeat: remember where each char was last seen. What is stored under last[c]?"] = "重複なしの最長部分文字列: 各文字を最後に見た場所を覚える。last[c] に入れるのは？",
  ["Look at the load: one core at 100, seven asleep. That is not a threading bug, that is the design."] = "負荷を見て：一つのコアが 100、七つは寝ている。これはスレッドのバグじゃない、設計だよ。",
  ["Look the answer up before computing. Fill the comma-ok test: if v, ok := memo[n]; ___"] = "計算する前に答えを調べる。comma-ok テストを埋めよ: if v, ok := memo[n]; ___",
  ["Look the answer up before computing. Which HashMap method?"] = "計算する前に答えを調べる。HashMap のどのメソッド？",
  ["Looks like switch, but every case is a channel send or receive."] = "switch に似ていますが、各 case は channel の送信か受信です。",
  ["Lowercase, three letters, and a bang because it is a macro."] = "小文字 3 文字、マクロなので感嘆符付き。",
  ["Lucky Mac  ·  Causeway Bay"] = "Lucky Mac  ·  銅鑼湾",
  ["Lucky Mac  ·  delivery app"] = "Lucky Mac  ·  デリバリーアプリ",
  ["Lucky Mac  ·  the back office"] = "ラッキーマック  ·  バックオフィス",
  ["Lucky Mac  ·  the morning set"] = "Lucky Mac  ·  モーニングセット",
  ["Lucky Mac  ·  the night shift"] = "ラッキーマック  ·  夜勤",
  ["Lucky Mac Express  ·  Rust backend"] = "ラッキーマック Express  ·  Rust バックエンド",
  ["Lucky Mac Express  ·  Times Square"] = "ラッキーマック Express  ·  タイムズスクエア",
  ["Lucky Mac Express  ·  the tea set"] = "ラッキーマック Express  ·  ティーセット",
  ["Lucky Mac is found. Leave the loop right now. Which keyword?"] = "Lucky Macが見つかった。今すぐループを抜ける。キーワードは？",
  ["Lucky Mac queue"] = "Lucky Macの行列",
  ["Lucky Mac, table 4"] = "Lucky Mac、4 番テーブル",
  ["MAP"] = "地図",
  ["MTR exit A, the underpass"] = "MTR A 出口、地下道",
  ["Main waits until all nine orders are marked done, then prints the receipt. Which queue method?"] = "メインは9件の注文すべてに終了の印が付くまで待ち、それからレシートを印字する。どの queue メソッド？",
  ["Make a context you can stop by hand. Which constructor?"] = "手で止められる context を作る。どのコンストラクタ？",
  ["Make a pipe with a sending end and a receiving end. Which function?"] = "送信側の端と受信側の端を持つパイプを作る。関数は？",
  ["Make an enum, impl Display and Error, impl From so ? converts. Box<dyn Error> catches the rest."] = "enum を作り、Display と Error を impl し、? が変換できるよう From を impl。残りは Box<dyn Error> が受け止める。",
  ["Make an owned String out of a string literal. Which constructor?"] = "文字列リテラルから所有権を持つ String を作る。どのコンストラクタ？",
  ["Make that copy without sorting: a new list with the same items. Which built-in, called on a?"] = "ソートせずにそのコピーを作る: 同じ項目を持つ新しいリスト。a に対して呼ぶ組み込み関数は？",
  ["Make that copy: a new owned Vec with the same contents. Which method?"] = "そのコピーを作る: 同じ内容を持つ新しい所有された Vec。どのメソッド？",
  ["Make the Safe class usable with 'with'. Which method runs on the way in?"] = "Safe クラスを 'with' で使えるようにする。入るときに走るメソッドは？",
  ["Make the menu rangeable. Fill the return type: iter.___[string]"] = "menu を range できるように。戻り値の型を埋めてください: iter.___[string]",
  ["Make the write visible to the other goroutine. Which builtin call ends the wait?"] = "その書き込みを別の goroutine に見せる。待ちを終わらせる組み込み呼び出しは？",
  ["Many of the thing an operating system schedules. Fifteen letters, one word."] = "OS がスケジュールするあれの複数形。一語。",
  ["Many readers at once, one writer. Fill the read lock: mu.___()"] = "読み手は多数同時、書き手は1人。読み取りロックを埋めて：mu.___()",
  ["Map keys must support ==. Fill the constraint: func Has[K ___](m map[K]bool, k K)"] = "map のキーは == をサポートする必要あり。制約を埋めて：func Has[K ___](m map[K]bool, k K)",
  ["Maps"] = "map",
  ["Mark a function so calling it returns a Future instead of running. Which keyword?"] = "呼ぶと実行せずに Future を返すよう関数に印を付ける。どのキーワード？",
  ["Mark on enqueue, not on dequeue, or a station can be queued twice from two neighbours."] = "キューに入れるときに印を付ける、取り出すときではない。さもないと1つの駅が2つの隣駅から2回キューに入る。",
  ["Mark the cell visited by sinking it. What is written into the grid?"] = "沈めてセルを訪問済みにする。グリッドに書き込むのは？",
  ["Mark the cell visited by turning it into water. Fill the value."] = "セルを水に変えて訪問済みにする。値を埋めろ。",
  ["Marking in place is the visited set: O(1) extra space. Interviewers may ask you not to mutate; then use a HashSet<(usize, usize)>."] = "その場の印が訪問済み集合: 追加空間 O(1)。面接官は変更するなと言うかもしれない。そのときは HashSet<(usize, usize)> を使え。",
  ["Marshal returns []byte and an error. Never ignore the error."] = "Marshal は []byte と error を返します。error は決して無視しないこと。",
  ["Max subarray sum: at each x, either extend the current run or start fresh. Fill the fresh start."] = "最大部分配列和: 各 x で、今の走りを伸ばすか新しく始めるか。新しい始まりを埋めよ。",
  ["Max subarray: extend the current run with x, or restart at x alone. Fill the second choice."] = "最大部分配列: 今の連続に x を足すか、x 単独でやり直すか。2つ目の選択肢を埋めろ。",
  ["Maybe a String, maybe nothing. Which return type?"] = "String かもしれないし、何もないかもしれない。戻り値の型は？",
  ["Meeting rooms: sort starts and ends separately. A start reuses a room when the earliest end is already over. Fill the test."] = "会議室: start と end を別々にソートする。最も早い end がもう終わっていれば、start は部屋を再利用する。判定を埋めよ。",
  ["Mei"] = "メイ",
  ["Memoization: check the map before computing. fib(90) becomes instant."] = "メモ化: 計算の前に map を確認。fib(90) が一瞬で終わります。",
  ["Memoized recursion is DP from the top. Same O(n), but the call stack is n deep: RecursionError near 1000."] = "メモ化再帰は上からの DP。同じ O(n) だが、コールスタックが n 段: 1000 付近で RecursionError。",
  ["Merge intervals"] = "区間のマージ",
  ["Merge intervals, meeting rooms"] = "区間のマージ、会議室",
  ["Merge sort and binary search"] = "マージソートと二分探索",
  ["Merge sort has log n levels of splitting. Merging all the pieces on one level costs how much?"] = "マージソートは分割の段が log n ある。一段のすべての断片をマージするコストは？",
  ["Merge sort recurses on both halves. Fill: merge(mergeSort(a[:m]), mergeSort(a[___]))"] = "マージソートは両方の半分へ再帰。穴埋め: merge(mergeSort(a[:m]), mergeSort(a[___]))",
  ["Merge sort splits in the middle. Which operator gives a whole-number midpoint?"] = "マージソートは真ん中で分ける。整数の中点を与える演算子は？",
  ["Merge sort: split at len // 2, sort both halves, merge with <=. sorted and list.sort take key=. bisect finds a slot in a sorted list in O(log n)."] = "マージソート: len // 2 で分割し、両半分をソートし、<= でマージ。sorted と list.sort は key= を取る。bisect はソート済みリストの位置を O(log n) で見つける。",
  ["Merge sort: split_at(len / 2), sort both, merge with <= for stability. In practice: sort_by_key, sort_unstable, binary_search."] = "マージソート: split_at(len / 2) で分け、両方をソートし、安定性のため <= でマージ。実際には sort_by_key、sort_unstable、binary_search。",
  ["Merge two sorted halves: take from the left while its item is no bigger. Which comparison keeps the sort stable?"] = "ソート済みの2つの半分をマージ: 左の項目が大きくない間は左から取る。ソートを安定に保つ比較は？",
  ["Merge two sorted halves: take the smaller head and advance that side. Fill: ___++"] = "ソート済みの 2 つの半分をマージ: 小さい先頭を取り、その側を進める。穴埋め: ___++",
  ["Merging two sorted halves. On a tie take from the left, so equal items keep their order. Which comparison?"] = "ソート済みの半分どうしをマージする。同点なら左から取り、等しい要素は順序を保つ。どの比較？",
  ["Method calls bind tighter than +, so it is 1 + (left.max(right)). Round two clean. Combo x2."] = "メソッド呼び出しは + より強く結びつくので、1 + (left.max(right)) になる。第 2 ラウンドもきれい。コンボ x2。",
  ["Methods are written in a separate block. Which keyword opens it?"] = "メソッドは別のブロックに書く。それを開くキーワードは？",
  ["Midnight edition of CODE RUSH! Python round. Chef Bo at the keyboard. Factorial, then fib. Buzzer's live!"] = "CODE RUSH 深夜版！ Python ラウンド。キーボードはボーシェフ。階乗、それから fib。ブザーは生きてる！",
  ["Min of the k largest is the kth largest. Top-k frequent is the same loop over a count map."] = "最大 k 個の最小が k 番目に大きい値。上位 k 頻出も、カウント map に対する同じループ。",
  ["Modern Rust idioms"] = "モダン Rust のイディオム",
  ["Module error, trait of the same name with a capital. Every method has a default."] = "モジュール error、同じ名前で頭が大文字のトレイト。メソッドはすべてデフォルト実装つき。",
  ["Modules and the go tool"] = "module と go ツール",
  ["More than k inside: the smallest cannot be the kth largest. Which function removes the root?"] = "中身が k より多い: 最小は k 番目に大きいではあり得ない。根を取り除く関数は？",
  ["More than k inside: the smallest, on top, has to go. Which method removes the top?"] = "中身が k 個より多い: 一番上の最小は出ていくしかない。一番上を取り除くメソッドは？",
  ["Morning set. Don't show him your laptop bugs."] = "モーニングセット。ノートPCのバグは彼に見せないで。",
  ["Morning set. Lucky Mac. The kiosk on the door is stuck on a Go bug."] = "モーニングセット。Lucky Mac。ドアのキオスクがGoのバグで止まってる。",
  ["Most tree questions are this shape: nil returns a base value, else combine both sides."] = "木の問題はだいたいこの形: nil なら基本値を返し、それ以外は両側を合成。",
  ["Move it to the recent end of the list, which is the front. One method, three words."] = "リストの最新側、つまり先頭へ移す。メソッド 1 つ、単語 3 つ。",
  ["Move next out, flip the arrow, push node onto prev. No take() needed: while let moved cur into node. prev is the new head."] = "next を取り出し、矢印を裏返し、node を prev の上に載せる。take() は不要: while let が cur を node にムーブ済み。prev が新しい先頭。",
  ["Muffin ready, or hash brown, or timeout. Pick one."] = "マフィンか、ハッシュブラウンか、タイムアウトか。1つ選べ。",
  ["Multiply 100 by 99, then halve it."] = "100 に 99 を掛け、半分にする。",
  ["Must start with Test and take *testing.T. File name ends with _test.go."] = "Test で始まり *testing.T を受け取ること。ファイル名は _test.go で終わります。",
  ["Mutating the grid is the O(1) extra-space visited set. Copy it first if the caller needs it back."] = "グリッドの書き換えが O(1) 追加空間の訪問済み集合。呼び出し元が後で必要ならまずコピー。",
  ["Mutating the input saves a visited set. If the caller needs the grid back, copy it first."] = "入力を書き換えれば visited set が要らない。呼び出し側がグリッドを返してほしいなら、先にコピーしろ。",
  ["Mutex and WaitGroup"] = "Mutex と WaitGroup",
  ["Mutex locks shared memory. WaitGroup waits for a set of goroutines to finish."] = "Mutex は共有メモリをロック。WaitGroup は goroutine 群の終了を待ちます。",
  ["Mutual exclusion, shortened to five letters. lock() gives a guard; the guard unlocks on drop."] = "相互排除 (mutual exclusion) を 5 文字に縮めたもの。lock() がガードをくれる。ガードは drop で鍵を開ける。",
  ["Mutual exclusion. Capital M. In package sync."] = "相互排他。大文字の M。sync パッケージにあります。",
  ["My first version started one goroutine per order. Forty thousand orders, forty thousand goroutines."] = "最初の版は注文ごとに goroutine を一つ立てた。四万件の注文、四万の goroutine。",
  ["NEXT"] = "次へ",
  ["NEXT >"] = "次へ >",
  ["NIGHT OWL"] = "夜ふかし",
  ["NIGHT SHIFT  -  the kitchen"] = "NIGHT SHIFT  -  キッチン",
  ["Named after a paperclip assistant from old office software. Six letters, double p."] = "昔のオフィスソフトのクリップ型アシスタントが名前の由来。6文字、p が2つ。",
  ["Named types, assertions, type switch"] = "名前付き型、アサーション、type switch",
  ["Negative indexes count from the end. Go would panic on this."] = "負のインデックスは末尾から数える。Go ならこれで panic する。",
  ["Negative indexing counts from the end; the last item is one back."] = "負のインデックスは末尾から数える。最後の要素は1つ戻ったところ。",
  ["Nested loops multiply their sizes. Two different letters, a star between them."] = "入れ子のループは大きさを掛け合わせる。異なる2文字、間に星。",
  ["Newer Go has helpers for that. Lunch is on the house."] = "新しい Go にはそのためのヘルパーがある。ランチは店のおごり。",
  ["Next of Next. The loop condition already checked fast.Next is not nil."] = "Next の Next。fast.Next が nil でないことはループ条件で確認済み。",
  ["Night shift. Every station runs a Python script I wrote. Tonight none of them start."] = "夜勤だ。全部の持ち場で私が書いた Python スクリプトが動く。今夜はどれも起動しない。",
  ["Nine letters, 'to count off'. Go gives you the index for free in range; Python asks you to wrap the list."] = "9文字、「数え上げる」。Go は range でインデックスをただでくれる。Python はリストを包むよう求める。",
  ["Nine letters, a railway signal. Go builds the same thing from a buffered channel."] = "九文字、鉄道の信号機。Go は同じものをバッファ付き channel で作る。",
  ["Nine letters. To number things one by one. zip() pairs two iterators instead."] = "9文字。ひとつずつ番号を振ること。zip() は代わりに2つのイテレータを組にする。",
  ["Nine letters. go test -bench=. runs them."] = "9文字。go test -bench=. で実行します。",
  ["No allocation, O(1): the node is relinked in place. Value is an any, so the type assertion unpacks the entry."] = "割り当てなし、O(1): ノードはその場でつなぎ直される。Value は any なので、型アサーションで entry を取り出す。",
  ["No eggs left: stop the order with an error. Which keyword throws?"] = "卵切れ: エラーで注文を止める。投げるキーワードは？",
  ["No garbage collector, and it still knows when to free the tray?"] = "ガベージコレクタなしで、トレイをいつ解放するか分かるの？",
  ["No input reference to borrow from. Which lifetime does a literal string have?"] = "借りる元になる入力参照がない。文字列リテラルが持つライフタイムは？",
  ["No nested loops. A window slides; the answer updates as it goes."] = "入れ子ループなし。窓が滑り、答えは進みながら更新される。",
  ["No nil in Rust. If a value may be missing, the type says Option."] = "Rust に nil はない。値が欠けるかもしれないなら、型が Option と言う。",
  ["No nil. Every failure is a value you must look at."] = "nil はない。失敗はすべて、目を向けなければならない値。",
  ["No note on the order yet. Which value means 'nothing here'?"] = "注文にまだメモがない。「ここには何もない」を意味する値は？",
  ["No overlap, or out is still empty: the current interval starts a new block. Which Vec method appends it?"] = "重なりなし、または out がまだ空: 今の区間が新しいブロックを始める。追加する Vec のメソッドは？",
  ["No overlap: cur starts a new merged interval. Fill the builtin."] = "重なりなし: cur が新しいマージ区間を始める。builtin を埋めよ。",
  ["No partner yet: remember this value and where it was. What is stored under seen[x]?"] = "まだ相方がない: この値とその場所を覚える。seen[x] には何が保存される？",
  ["Nobody told it to stop. Nothing in Go kills a goroutine from outside."] = "誰も止まれと言わなかったからね。Go には外から goroutine を殺すものが何もない。",
  ["Node contains Node. The compiler needs a fixed size, so the child lives on the heap behind which pointer?"] = "Node が Node を含む。コンパイラは固定サイズを求めるので、子はどのポインタの向こう、ヒープ上に置く？",
  ["None is a value, not a null pointer. Read it with match or if let Some(s) = seat(t). The board lights up."] = "None は値であり、null ポインタではない。match か if let Some(s) = seat(t) で読む。ボードが点灯する。",
  ["None is the base case: put a fresh leaf there. The Some arms recurse. Match ergonomics let n be &mut Box<Node>."] = "None が基底ケース: そこに新しい葉を置く。Some の腕は再帰する。マッチエルゴノミクスのおかげで n は &mut Box<Node> になる。",
  ["None is the one value of NoneType. A function with no return gives None too."] = "None は NoneType の唯一の値。return のない関数も None を返す。",
  ["None marks an empty subtree. Every tree function starts with: if node is None."] = "None は空の部分木を示す。すべての木の関数は if node is None から始まる。",
  ["None on an empty out falls to the _ arm and pushes. The borrow ends with the match, so out.push is allowed there."] = "out が空なら None で _ のアームに落ちて push。借用は match と共に終わるので、そこで out.push が許される。",
  ["None terminates the list. Walk with while node: and stop when it is falsy."] = "None がリストを終端する。while node: で歩き、偽になったら止まる。",
  ["Not TODO (that is a placeholder). The empty, never-cancelled root."] = "TODO ではない（あれは仮置き）。空で決してキャンセルされない根です。",
  ["Not equal. The statement before ; runs first, and err lives only inside the if."] = "不等号。; の前の文が先に実行され、err は if の中だけで生きます。",
  ["Not null, not None. Three letters. The only zero for interfaces with no type."] = "null でも None でもありません。3文字。型のない interface の唯一のゼロ値です。",
  ["Not quite. Read the hint and try again. HINT again shows the answer."] = "惜しい。ヒントを読んでもう一度。ヒントをもう一度押すと答えが出ます。",
  ["Not struct. Variants, one of which carries the ParseIntError inside."] = "struct ではない。バリアントがあり、そのひとつが ParseIntError を中に持つ。",
  ["Not the stack. The other one, the one the garbage collector sweeps."] = "スタックではない。もう一方、ガベージコレクタが掃くほうだ。",
  ["Nothing runs yet. Which method actually starts the thread?"] = "まだ何も走っていない。実際にスレッドを始めるメソッドは？",
  ["Nothing tells parse which type to build. Say i32 with the turbofish."] = "parse にどの型を作るか教えるものがない。ターボフィッシュで i32 と言って。",
  ["Now collect the number. Which method of the Future?"] = "では数を受け取ろう。Future のどのメソッド？",
  ["Now the worker takes two arguments. Which method unpacks each tuple?"] = "こんどはワーカーが引数を二つ取る。タプルを開くメソッドは？",
  ["Now wait for the answer. Write Go's await."] = "では答えを待とう。Go の await を書く。",
  ["Num, then the thing Go is famous for, singular."] = "Num に、Go で一番有名なあれを単数で。",
  ["Num, then the three letters on the chip."] = "Num、そしてチップの三文字。",
  ["Number in the brackets, then the element type. It cannot grow."] = "角括弧の中に数、そのあと要素の型。伸ばせません。",
  ["Number of islands"] = "島の数",
  ["Number of islands: DFS on a grid"] = "島の数: グリッド上の DFS",
  ["Number the constants 0, 1, 2 automatically. Which identifier?"] = "定数に 0, 1, 2 と自動で番号を振る。識別子は？",
  ["Number the trays from 1 while looping. Which built-in pairs an index with each item?"] = "ループしながらトレイに 1 から番号を付ける。各項目にインデックスを組にする組み込み関数は？",
  ["Numbers, strings, None"] = "数、文字列、None",
  ["O(1) extra, near enough: the list is rearranged where it lives and sort() returns None to say so."] = "追加 O(1)、ほぼそう: リストは住んでいる場所で並べ替えられ、sort() はそう言うために None を返す。",
  ["O(1) extra: pdqsort swaps within the slice. The input itself is never counted as extra space."] = "追加 O(1): pdqsort はスライスの中で入れ替える。入力自体は決して追加空間に数えない。",
  ["O(1) extra: pdqsort swaps within the slice. Vec::sort, the stable one, allocates an O(n) buffer instead."] = "追加 O(1): pdqsort はスライスの中で入れ替える。安定なほうの Vec::sort は代わりに O(n) のバッファを確保する。",
  ["O(1) lookups need a map from key to its node in the list. Fill the value type."] = "O(1) の検索には、キーからリスト内のノードへの map が要る。値の型を埋めよ。",
  ["O(1): a million items or ten, one multiply and one load. Written O(1), read 'order one'."] = "O(1): 100万個でも10個でも、掛け算1回とロード1回。O(1) と書き、「オーダーワン」と読む。",
  ["O(1): the OrderedDict is a doubly linked list plus a dict. The newest lives at the end, the oldest at the front."] = "O(1): OrderedDict は双方向連結リストと dict。最新は末尾、最古は先頭に住む。",
  ["O(1): the bounds check is one compare, the read one load, whatever n is. Read 'order one'."] = "O(1): 境界チェックは比較1回、読みはロード1回、n が何であれ。「オーダーワン」と読む。",
  ["O(1): the same number of steps however big the input. Indexing a Vec, a HashMap lookup, .last(). Doubling n changes nothing."] = "O(1): 入力がどれだけ大きくても同じステップ数。Vec のインデックス、HashMap の検索、.last()。n を倍にしても何も変わらない。",
  ["O(1): the same number of steps however big the input. Indexing a list, a dict lookup, items[-1]. Doubling n changes nothing."] = "O(1): 入力がどれだけ大きくても同じステップ数。リストのインデックス、dict の検索、items[-1]。n を倍にしても何も変わらない。",
  ["O(1): the same number of steps however big the input. Indexing a slice, a map lookup, the last element. Doubling n changes nothing."] = "O(1): 入力がどれだけ大きくても同じステップ数。スライスのインデックス、map の検索、最後の要素。n を倍にしても何も変わらない。",
  ["O(2^n). fib(35) already takes seconds in Python; fib(50) would take days. The worst curve on the board."] = "O(2^n)。Python では fib(35) ですでに数秒かかる。fib(50) は数日。ボード上で最悪の曲線。",
  ["O(2^n). fib(40) is about a billion calls even in Rust; fib(50) would take a day. The worst curve on the board."] = "O(2^n)。Rust でも fib(40) は約10億回の呼び出し。fib(50) は1日かかる。ボード上で最悪の曲線。",
  ["O(2^n). fib(40) is about a billion calls; fib(50) would take a day. The worst curve on the board."] = "O(2^n)。fib(40) は約10億回の呼び出し。fib(50) は1日かかる。ボード上で最悪の曲線。",
  ["O(2^n): the work doubles when n grows by one. Naive fib makes two calls per call. @functools.cache brings it to O(n). Listing every subset of n items is 2^n and cannot be helped."] = "O(2^n): n が1増えると仕事が倍になる。素朴な fib は呼び出しごとに2回呼ぶ。@functools.cache で O(n) になる。n 項目のすべての部分集合を列挙するのは 2^n で、どうにもならない。",
  ["O(2^n): the work doubles when n grows by one. Naive fib makes two calls per call. A HashMap memo brings it to O(n). Listing every subset of n items is 2^n and cannot be helped."] = "O(2^n): n が1増えると仕事が倍になる。素朴な fib は呼び出しごとに2回呼ぶ。HashMap の memo で O(n) になる。n 項目のすべての部分集合を列挙するのは 2^n で、どうにもならない。",
  ["O(2^n): the work doubles when n grows by one. Naive fib makes two calls per call. A memo brings it to O(n). Listing every subset of n items is 2^n and cannot be helped."] = "O(2^n): n が1増えると仕事が倍になる。素朴な fib は呼び出しごとに2回呼ぶ。memo で O(n) になる。n 項目のすべての部分集合を列挙するのは 2^n で、どうにもならない。",
  ["O(amount * coins). Each cell asks: which last coin gives the fewest in total?"] = "O(amount * coins)。各セルが問う: 最後のコインをどれにすれば合計が最少か？",
  ["O(amount * coins). Greedy fails here: coins [1, 3, 4] for 6 is two coins, not 4 + 1 + 1."] = "O(amount * coins)。貪欲法はここで失敗する: コイン [1, 3, 4] で 6 は2枚、4 + 1 + 1 ではない。",
  ["O(amount * coins). The greedy 'biggest coin first' fails for coins like 1, 3, 4 and amount 6; the table does not."] = "O(amount * coins)。「大きいコインから」の貪欲法はコイン 1、3、4 で金額 6 のとき失敗する。表は失敗しない。",
  ["O(log k) per push. Python's heapq is a min-heap only; for a max-heap push -x."] = "push ごとに O(log k)。Python の heapq は min-heap のみ。max-heap なら -x を push。",
  ["O(log n) per search. Sorting first pays off after the first few lookups. The sorting hat is done."] = "探索ごとに O(log n)。先にソートすれば最初の数回の検索で元が取れる。組分け帽子は完了。",
  ["O(log n) stack frames on average. Every axis on the board has a name now. Alex takes the O(1) stamp."] = "平均 O(log n) のスタックフレーム。ボード上のすべての軸に今や名前がある。アレックスが O(1) スタンプを手にする。",
  ["O(log n) stack frames on average. Every axis on the board has a name. Mei takes the O(1) stamp for the Rust round."] = "平均 O(log n) のスタックフレーム。ボード上のすべての軸に名前がある。メイが Rust ラウンドの O(1) スタンプを手にする。",
  ["O(log n) stack frames on average. Every axis on the last board has a name. The Python round takes the O(1) stamp; the night is over."] = "平均 O(log n) のスタックフレーム。最後のボードのすべての軸に名前がある。Python ラウンドが O(1) スタンプを手にする。夜は終わった。",
  ["O(log n). Balanced trees, heaps and skip lists live here too. It is the second-best cost after O(1)."] = "O(log n)。平衡木、ヒープ、スキップリストもここに住む。O(1) の次に良いコスト。",
  ["O(log n). Err(i) even tells you where to insert. BTreeMap and BinaryHeap live at the same cost."] = "O(log n)。Err(i) はどこに挿入すべきかまで教える。BTreeMap と BinaryHeap も同じコストに住む。",
  ["O(log n). heapq lives at the same cost per push and pop. The second-best cost after O(1)."] = "O(log n)。heapq も push と pop ごとに同じコストに住む。O(1) の次に良いコスト。",
  ["O(log n): each step halves what is left. Binary search on a sorted slice: 1024 items in 10 steps, a million in 20. Needs sorted input."] = "O(log n): 各ステップで残りが半分になる。ソート済みスライスの二分探索: 1024 個を10ステップ、100万個を20ステップ。ソート済みの入力が必要。",
  ["O(log n): each step halves what is left. bisect on a sorted list: 1024 items in 10 steps, a million in 20. Needs sorted input."] = "O(log n): 各ステップで残りが半分になる。ソート済みリストへの bisect: 1024 個を10ステップ、100万個を20ステップ。ソート済みの入力が必要。",
  ["O(log n): each step halves what is left. slice::binary_search on a sorted Vec: 1024 items in 10 steps, a million in 20. Needs sorted input."] = "O(log n): 各ステップで残りが半分になる。ソート済み Vec への slice::binary_search: 1024 個を10ステップ、100万個を20ステップ。ソート済みの入力が必要。",
  ["O(n log k) time, O(k) space: better than sorting all n when k is small."] = "時間 O(n log k)、空間 O(k): k が小さければ n 個全部ソートするより良い。",
  ["O(n log n) for the sort; everything after is O(n). Lists sort by first element anyway, so shifts.sort() works here too."] = "ソートに O(n log n)。その後はすべて O(n)。リストはどのみち最初の要素でソートされるので、shifts.sort() でもここでは動く。",
  ["O(n log n), and after it every overlap sits next to its neighbour. slices.SortFunc does the same in Go 1.21."] = "O(n log n)、その後はどの重なりも隣り合っている。Go 1.21 の slices.SortFunc も同じことをする。",
  ["O(n log n), and it dominates: the merge walk after it is O(n). mut iv lets the function sort in place."] = "O(n log n)、これが支配的: 後のマージの歩きは O(n)。mut iv で関数はその場でソートできる。",
  ["O(n log n). A million items: about 20 million comparisons, not a trillion. The proven lower bound for comparison sorts."] = "O(n log n)。100万個: 約2000万回の比較、1兆ではない。比較ソートの証明された下界。",
  ["O(n log n). A million items: about 20 million comparisons. The proven lower bound for comparison sorts."] = "O(n log n)。100万個: 約2000万回の比較。比較ソートの証明された下界。",
  ["O(n log n). A million items: about 20 million comparisons. Timsort is O(n) on already-sorted input, a bonus."] = "O(n log n)。100万個: 約2000万回の比較。Timsort はすでにソート済みの入力に O(n)、おまけ。",
  ["O(n log n): the cost of a good sort. Merge sort has log n levels, each doing O(n) work. sort, sort_unstable and sort_by_key all live here. Sort once, search many times."] = "O(n log n): 良いソートのコスト。マージソートは log n 段あり、各段が O(n) の仕事をする。sort、sort_unstable、sort_by_key はすべてここに住む。一度ソートし、何度も探索する。",
  ["O(n log n): the cost of a good sort. Merge sort has log n levels, each doing O(n) work. sort.Ints, sort.Strings and slices.Sort all live here. Sort once, search many times."] = "O(n log n): 良いソートのコスト。マージソートは log n 段あり、各段が O(n) の仕事をする。sort.Ints、sort.Strings、slices.Sort はすべてここに住む。一度ソートし、何度も探索する。",
  ["O(n log n): the cost of a good sort. Merge sort has log n levels, each doing O(n) work. sorted and list.sort are Timsort and live here. Sort once, search many times."] = "O(n log n): 良いソートのコスト。マージソートは log n 段あり、各段が O(n) の仕事をする。sorted と list.sort は Timsort で、ここに住む。一度ソートし、何度も探索する。",
  ["O(n) instead of O(n * k): the sum is updated, never recomputed. Fixed windows are always this trick."] = "O(n * k) でなく O(n): 合計は更新され、再計算されない。固定窓はいつもこのトリック。",
  ["O(n) per level times log n levels. That product is the whole reason n log n exists."] = "段ごとに O(n) 掛ける log n 段。その積が n log n が存在する理由のすべて。",
  ["O(n) time, O(n) table. Keep only the last two entries and it is O(1) space."] = "時間 O(n)、表 O(n)。最後の 2 項だけ持てば空間 O(1)。",
  ["O(n) with a dict instead of O(n^2) with two loops. Check before storing so x does not pair with itself."] = "dict で O(n)、ループ2つの O(n^2) ではなく。保存する前に調べれば x が自分自身と組にならない。",
  ["O(n). Big O keeps only the fastest-growing term and drops its coefficient. Sequential loops add; nested loops multiply."] = "O(n)。Big O は最も速く増える項だけを残し、その係数を落とす。逐次のループは足し、入れ子のループは掛ける。",
  ["O(n). Every element is touched once. The most common cost in everyday code, and often the best possible."] = "O(n)。すべての要素に一度触れる。日常のコードで最もよくあるコストで、しばしば可能な最良。",
  ["O(n). Memoization trades O(n) memory for the exponential time. The biggest win in this whole quest."] = "O(n)。メモ化は O(n) のメモリで指数時間を買う。このクエスト全体で最大の勝利。",
  ["O(n). Memoization trades O(n) memory for the exponential time. The single biggest win in this whole quest."] = "O(n)。メモ化は O(n) のメモリで指数時間を買う。このクエスト全体で最大の勝利。",
  ["O(n). Merge sort needs the same: an O(n) scratch buffer for merging. Python's sorted() copies too."] = "O(n)。マージソートも同じものを必要とする: マージ用の O(n) の作業バッファ。Python の sorted() もコピーする。",
  ["O(n). Rust makes the cost visible: clone() is a word you have to type. Python's sorted() copies silently."] = "O(n)。Rust はコストを見えるようにする: clone() は自分で打たなければならない単語。Python の sorted() は黙ってコピーする。",
  ["O(n). Sequential passes add and the constant drops. Nested passes multiply: that is the next street but one."] = "O(n)。逐次の走査は足され、定数は落ちる。入れ子の走査は掛ける: それは次の次の街。",
  ["O(n). Sequential passes add and the constant drops. Nested passes multiply: that is two streets on."] = "O(n)。逐次の走査は足され、定数は落ちる。入れ子の走査は掛ける: それは2つ先の街。",
  ["O(n). sorted() always copies; a.sort() never does. Choose by whether you still need the original order."] = "O(n)。sorted() は常にコピーする。a.sort() は決してしない。元の順序がまだ要るかで選ぶ。",
  ["O(n). sum, map, filter, count: every adapter is one pass. Zero-cost abstractions are still O(n) abstractions."] = "O(n)。sum、map、filter、count: すべてのアダプタは一巡。ゼロコスト抽象化でもやはり O(n) の抽象化。",
  ["O(n). sum, max, min, any, all, list.count: every one is a pass. Faster in C, same order."] = "O(n)。sum、max、min、any、all、list.count: どれも一巡。C の中で速いが、オーダーは同じ。",
  ["O(n): one pass over the input; double n, double the work. A range loop, a sum, a scan for a value. O(n) + O(n) is still O(n): constants drop."] = "O(n): 入力を一巡する。n を倍にすれば仕事も倍。range ループ、合計、値の走査。O(n) + O(n) はやはり O(n): 定数は落ちる。",
  ["O(n): one pass over the input; double n, double the work. iter().sum(), any(), Vec::contains. O(n) + O(n) is still O(n): constants drop."] = "O(n): 入力を一巡する。n を倍にすれば仕事も倍。iter().sum()、any()、Vec::contains。O(n) + O(n) はやはり O(n): 定数は落ちる。",
  ["O(n): one pass over the input; double n, double the work. sum, max, x in list. O(n) + O(n) is still O(n): constants drop."] = "O(n): 入力を一巡する。n を倍にすれば仕事も倍。sum、max、x in list。O(n) + O(n) はやはり O(n): 定数は落ちる。",
  ["O(n*m). Only when both loops run over the same n does it collapse to n^2. The seating chart is fixed."] = "O(n*m)。両方のループが同じ n を回るときだけ n^2 に潰れる。座席表は直った。",
  ["O(n^2). Double the guests, four times the checks. Bubble sort and selection sort live here too."] = "O(n^2)。客が倍ならチェックは4倍。バブルソートと選択ソートもここに住む。",
  ["O(n^2): a loop inside a loop over the same n. Comparing every pair. 100 items is 4950 pairs; 10,000 is fifty million. A HashSet turns most of these into O(n)."] = "O(n^2): 同じ n に対するループの中のループ。すべての組を比較する。100 個は 4950 組。10,000 個は5000万。HashSet で大半が O(n) になる。",
  ["O(n^2): a loop inside a loop over the same n. Comparing every pair. 100 items is 4950 pairs; 10,000 is fifty million. A map turns most of these into O(n)."] = "O(n^2): 同じ n に対するループの中のループ。すべての組を比較する。100 個は 4950 組。10,000 個は5000万。map で大半が O(n) になる。",
  ["O(n^2): a loop inside a loop over the same n. Comparing every pair. 100 items is 4950 pairs; 10,000 is fifty million. A set turns most of these into O(n)."] = "O(n^2): 同じ n に対するループの中のループ。すべての組を比較する。100 個は 4950 組。10,000 個は5000万。set で大半が O(n) になる。",
  ["OK"] = "OK",
  ["Octopus tap. The gate function returns ok, err."] = "オクトパスをタッチ。改札関数は ok, err を返す。",
  ["Off the map on any side: stop. Fill the width the column index is checked against."] = "どの側でも地図の外なら: 止まる。列インデックスと比べる幅を埋めろ。",
  ["Ok(2). On an unsorted slice the result is meaningless, so sort first. Err(i) is where to insert to stay sorted."] = "Ok(2)。ソートされていないスライスでは結果に意味がないので、先にソートする。Err(i) はソート順を保つために挿入する位置。",
  ["Once, plus the word for what a function gives back. There is a two-result twin for (T, error)."] = "Once に、関数が返すものを表す語を足す。(T, error) 用の双子もある。",
  ["One CPython process runs bytecode under a global interpreter lock, so eight threads doing arithmetic still use one core. The GIL is released around I/O and inside C extensions, which is why threads help downloads and not sums. multiprocessing sidesteps it: every process has its own interpreter and its own lock."] = "一つの CPython プロセスはグローバルインタプリタロックの下でバイトコードを走らせる。だから算術をする八つのスレッドでもコアは一つしか使わない。GIL は I/O の前後と C 拡張の中では解放されるので、スレッドはダウンロードには効き、合計には効かない。multiprocessing はそれをよける：プロセスごとに自分のインタプリタと自分のロックがある。",
  ["One HashSet method adds m and tells you whether it was new. Which one?"] = "m を追加して、それが新しかったかどうかも教えてくれる HashSet のメソッドが 1 つある。どれ？",
  ["One Unicode character in single quotes. Which type?"] = "シングルクォートで囲んだ Unicode 文字ひとつ。型は？",
  ["One cargo command builds the crate and starts it. Which word?"] = "cargo のコマンド 1 つでクレートをビルドして起動。どの単語？",
  ["One character passes the error straight back to the caller. Which?"] = "1 文字でエラーをそのまま呼び出し側に返す。どれ？",
  ["One character, the ampersand. The call site already uses it."] = "1 文字、アンパサンド。呼び出し側ではすでに使っている。",
  ["One character, the one in an email address. Rust uses it for attributes with #[...] instead."] = "1文字、メールアドレスにあるもの。Rust は代わりに #[...] 属性を使う。",
  ["One character. Go and Rust use two slashes; Python uses the hash sign."] = "1文字。Go と Rust はスラッシュ2本、Python はハッシュ記号。",
  ["One character. The same one that returns Err early in a Result function."] = "1文字。Result を返す関数で Err を早期 return するのと同じ文字。",
  ["One character. The same underscore Go uses to throw a value away."] = "1 文字。Go が値を捨てるときに使うのと同じアンダースコア。",
  ["One cook, one thread. The grill must not wait for the kettle."] = "料理人 1 人、スレッド 1 本。グリルがやかんを待ってはいけない。",
  ["One counter, changed by many threads. Which wrapper allows only one writer at a time?"] = "多くのスレッドが変える 1 つのカウンタ。一度に 1 人の書き手だけを許すラッパーは？",
  ["One decorator remembers every result by argument. Which one, from functools?"] = "1つのデコレータが引数ごとにすべての結果を覚える。functools のどれ？",
  ["One function for muffin or hash brown. Don't copy-paste."] = "マフィンもハッシュブラウンも関数1つ。コピペするな。",
  ["One less than n. fact(n) would never terminate."] = "n より 1 小さい値です。fact(n) では永遠に終わりません。",
  ["One less than n. u64 cannot go below zero, which is why the base case checks <= 1."] = "n より 1 小さく。u64 は 0 を下回れないから、基底ケースは <= 1 を見る。",
  ["One less than zero. Go spells the same thing items[len(items)-1]."] = "ゼロより1小さい。Go は同じことを items[len(items)-1] と綴る。",
  ["One letter in front of Lock. Its partner is RUnlock."] = "Lock の前に一文字。相棒は RUnlock。",
  ["One letter: the loop variable. Each goroutine owns exactly one slot."] = "一文字：ループ変数。goroutine はちょうど一マスだけを持つ。",
  ["One line: 'open' when bowls remain, otherwise 'closed'. Which keyword completes the conditional expression?"] = "一行で: 丼が残っていれば 'open'、そうでなければ 'closed'。この条件式を完成させるキーワードは？",
  ["One loop over n prices, adding each: what is the cost in Big O?"] = "n 個の値段を1つのループで足す: Big O でコストは？",
  ["One megabyte every process can map. Which class from multiprocessing.shared_memory?"] = "どのプロセスもマップできる 1 メガバイト。multiprocessing.shared_memory のどのクラス？",
  ["One more than the amount itself: no real answer uses more coins than the amount."] = "金額そのものより 1 大きい: 本当の答えが金額より多くの枚数を使うことはない。",
  ["One pass, Bo. Keep the run if it's still helping, drop it the moment it isn't."] = "一回の走査よ、ボー。まだ役に立つなら連続を続け、役に立たなくなった瞬間に捨てる。",
  ["One pass, one HashMap: O(n) instead of the O(n^2) double loop. seen[&want] then fetches the partner's index."] = "1 パス、HashMap 1 つ: O(n^2) の二重ループでなく O(n)。あとは seen[&want] で相手のインデックスを取る。",
  ["One pass, one map: O(n). Store after checking so x does not pair with itself."] = "1 パス、1 map: O(n)。x が自分と組にならないよう、確認後に保存。",
  ["One pass. If the running total goes negative, it can only hurt: start again."] = "一回通り。累計がマイナスになったら害しかない: やり直せ。",
  ["One pointer per node: singly linked. Two (Prev) makes it doubly linked."] = "ノードにポインタ 1 つ: 単方向リスト。2 つ（Prev）なら双方向リスト。",
  ["One printer, eight cooks"] = "プリンタ一台、料理人八人",
  ["One put crashes with TypeError. What must everything on the queue be?"] = "ある put が TypeError で落ちた。キューに載るものは何でなければならない？",
  ["One slash. On integers Rust truncates, so no floor operator is needed. lo + (hi-lo)/2 avoids overflow."] = "スラッシュ1本。整数に対して Rust は切り捨てるので、切り捨て演算子は要らない。lo + (hi-lo)/2 はオーバーフローを避ける。",
  ["One slash. On ints Go rounds toward zero, so no floor operator is needed."] = "スラッシュ1本。int に対して Go はゼロ方向に丸めるので、切り捨て演算子は要らない。",
  ["One ticket rail: the front sends boxed jobs, the cooks receive them. Which mpsc function makes the (tx, rx) pair?"] = "伝票レールは 1 本: 表がボックス化したジョブを送り、料理人が受け取る。(tx, rx) の組を作る mpsc の関数は？",
  ["One tray, one owner. Hand it over and it is gone. Lend it with & and you keep it."] = "トレイ 1 つに所有者 1 人。渡したら手元からなくなる。& で貸せば手元に残る。",
  ["One type, several ways an order can fail. Which keyword declares it?"] = "ひとつの型に、注文が失敗する複数の形。宣言するキーワードは？",
  ["One word, no underscore: the largest size the cache may reach. None means unbounded."] = "アンダースコアなしの一語: キャッシュが達しうる最大サイズ。None なら上限なし。",
  ["One writer at the printer. Which multiprocessing primitive?"] = "プリンタの前は一度に一人。どの multiprocessing プリミティブ？",
  ["Only four riders out at a time. Complete the release at the end of the trip."] = "一度に外へ出るのは四人まで。配達が終わったあとの返却を埋めよう。",
  ["Only land spreads the flood. Which byte marks land in the grid?"] = "陸だけが flood を広げる。グリッドで陸を表すバイトは？",
  ["Only land spreads. Which cell value means a building?"] = "広がるのは陸だけ。建物を意味するセルの値は？",
  ["Only names that start with a capital letter leave their package. Which fmt function prints a line?"] = "大文字で始まる名前だけがpackageの外に出られます。1行を出力するfmtの関数は？",
  ["Only one move reaches the first step: a single step of one."] = "1段目に着く動きは1つだけ: 1段の一歩。",
  ["Only the sender closes. Sending after this panics."] = "閉じるのは送信側だけ。この後に送ると panic します。",
  ["Only the sender should call it. Never close from the receive side."] = "呼ぶのは送信側だけ。受信側から close しないで。",
  ["Only three workers may hit the payments API at once. Which primitive counts?"] = "決済 API を叩けるのは一度に三人まで。数えられるプリミティブは？",
  ["Only types with this marker trait may move to another thread. Which one?"] = "このマーカートレイトを持つ型だけが別のスレッドへ移れる。どれ？",
  ["Only useful inside defer. Returns nil if we are not panicking."] = "defer の中でだけ有効。panic 中でなければ nil を返します。",
  ["Open the file so it is closed no matter what happens inside. Which keyword?"] = "中で何が起きても閉じられるようにファイルを開く。どのキーワード？",
  ["Open the middle, decide left or right, throw half away. The bisect module did it first."] = "真ん中を開き、左か右か決め、半分を捨てる。bisect モジュールが先にやってくれた。",
  ["Open the middle, decide left or right, throw half away. The std library already wrote it."] = "真ん中を開き、左か右か決め、半分を捨てる。std ライブラリがもう書いてくれている。",
  ["Opposite of var. Compile error if you try to change it."] = "var の反対。変えようとするとコンパイルエラーです。",
  ["Option does the empty case for free: a closer with nothing to pop is a mismatch, no extra if needed."] = "空の場合は Option がただで面倒を見る: pop するものがない閉じ括弧は不一致、追加の if は不要。",
  ["Option<Box<ListNode>>: each node owns the next, the last one holds None. Same size as a raw pointer."] = "Option<Box<ListNode>>: 各ノードが次を所有し、最後は None を持つ。生ポインタと同じサイズ。",
  ["Option<T> is an enum in the standard library, generic like your own types. No null anywhere in Rust."] = "Option<T> は標準ライブラリの enum で、自作の型と同じくジェネリック。Rust のどこにも null はない。",
  ["Option<u32> is an enum: Some(12) or None. The caller must handle both, so no nil crash."] = "Option<u32> は enum: Some(12) か None。呼び出し側は両方を扱わねばならず、nil でクラッシュしない。",
  ["Option<usize> would be more Rust; the interview version returns -1. Either way: check the marker before trusting the cell."] = "Option<usize> の方が Rust らしいが、面接版は -1 を返す。どちらにせよ: セルを信じる前に印を確かめろ。",
  ["Optional[str] is str | None. Rust's Option<String>, made visible to the checker."] = "Optional[str] は str | None。Rust の Option<String> を、チェッカーに見えるようにしたもの。",
  ["Order 18. Morning set. Don't forget to cancel the context."] = "18番。モーニングセット。context のキャンセルを忘れずに。",
  ["Order is a struct. Point at it. The till talks through an interface."] = "Order は struct。それを指す。レジは interface 越しに話す。",
  ["Orders come through the web now. Put a handler on /order."] = "注文は今やウェブ経由。/order に handler を置いて。",
  ["Over capacity: the least recently used sits at the far end of the list. Which method finds it?"] = "容量超過: 一番使われていないものはリストの遠い端にいる。それを見つけるメソッドは？",
  ["Overlap: the current interval starts no later than the last one ends. (1,3) and (3,5) touch and should merge. Which comparison?"] = "重なり: 今の区間が最後の区間の終わりより遅くなく始まる。(1,3) と (3,5) は接していてマージすべき。比較は？",
  ["Overlaps are only neighbours once the intervals are ordered by start. Which Vec method sorts by a key closure?"] = "重なりが隣同士になるのは、区間を start で並べてから。キーのクロージャでソートする Vec のメソッドは？",
  ["Owner says: ship before 18:00 and the dinner set is on the house."] = "店主いわく: 18:00 前に出荷したらディナーセットはお店のおごり。",
  ["Ownership and borrowing"] = "所有権と借用",
  ["PARALLEL  -  the night batch"] = "PARALLEL  -  夜のバッチ",
  ["PARALLEL  ·  the night batch"] = "PARALLEL  ·  夜のバッチ",
  ["PERFECT STREET"] = "パーフェクトな街",
  ["PERFECT!"] = "パーフェクト！",
  ["POLYGLOT"] = "ポリグロット",
  ["PORT"] = "縦",
  ["Packages and imports"] = "packageとimport",
  ["Palindrome with two pointers: i at the start, j at the end. Fill: j = len(s) ___ 1"] = "2つのポインタで回文: i は先頭、j は末尾。埋めよ: j = len(s) ___ 1",
  ["Palindrome: the chars read the same backwards. Which iterator method walks from the end?"] = "回文: 文字は後ろから読んでも同じ。末尾から歩くイテレータのメソッドは？",
  ["Partial, then the word for ordering. Ord alone is too strict for f64."] = "Partial、続けて順序を表す単語。Ord だけでは f64 に厳しすぎる。",
  ["Pause here until fetch has its answer, letting other tasks run. Which keyword?"] = "fetch の答えが出るまでここで止まり、他のタスクを走らせる。どのキーワード？",
  ["Pause this thread for 300 ms. Which function?"] = "このスレッドを 300 ms 止める。関数は？",
  ["Pay() can fail. Check the error. Close the drawer with defer."] = "Pay() は失敗しうる。エラーを確認。引き出しは defer で閉じる。",
  ["Peek at the most recent opener without removing it. Which index?"] = "直近の開き括弧を取り除かずに覗く。どのインデックス？",
  ["Percival Street"] = "波斯富街",
  ["Percival Street at dawn. Walk if the crossing is clear, else wait. Go has no while: a for with a condition is the while."] = "夜明けの波斯富街。横断歩道が空いていれば渡り、でなければ待つ。Goに while はなく、条件付きの for が while です。",
  ["Percival Street tram stop"] = "パーシバル通りのトラム停留所",
  ["Pick a branch by value without a chain of ifs. Which keyword?"] = "if を連ねずに値で分岐する。キーワードは？",
  ["Pick the bigger of a and b in one line. Which keyword starts the expression?"] = "a と b の大きい方を 1 行で選ぶ。式を始めるキーワードは？",
  ["Pipe() gives two Connection objects with send and recv. It is faster than a Queue and safe for exactly two processes."] = "Pipe() は send と recv を持つ Connection を二つくれる。Queue より速く、ちょうど二つのプロセスに対して安全だ。",
  ["Plain dicts keep insertion order since 3.7, but only this one has move_to_end and popitem(last=False)."] = "素の dict も 3.7 から挿入順を保つが、move_to_end と popitem(last=False) があるのはこれだけ。",
  ["Plain integers: equal values are indistinguishable, so stability is wasted. The faster in-place sort with no allocation?"] = "ただの整数: 等しい値は見分けられないので、安定性は無駄になる。確保なしでその場を並べ替える、より速いソートは？",
  ["Plural of the type a single Unicode scalar has in Rust."] = "Rust で Unicode スカラー値ひとつが持つ型の複数形。",
  ["Point the current node backwards. Fill: cur.Next = ___"] = "現在のノードを後ろへ向ける。穴埋め: cur.Next = ___",
  ["Pointer receiver to mutate or for big structs; value receiver for small read-only types."] = "変更する場合や大きな struct には pointer レシーバ。小さな読み取り専用の型には値レシーバ。",
  ["Pointer to the same struct type, like the tree node."] = "木のノードと同じく、同じ struct 型へのポインタ。",
  ["Pool: map, imap, starmap, chunks"] = "Pool：map、imap、starmap、チャンク",
  ["Price list is a map. Hash brown: 8 dollars."] = "価格表は map。ハッシュブラウン: 8ドル。",
  ["Print every dish with its price. Which method walks the key-value pairs?"] = "すべての料理を値段と一緒に印字する。キーと値のペアを歩くメソッドは？",
  ["Print the missing key from the error object. Which keyword binds the exception to a name?"] = "エラーオブジェクトから欠けていたキーを印字する。例外を名前に束縛するキーワードは？",
  ["Print the struct with its field names. Which verb?"] = "struct をフィールド名つきで表示。どの verb？",
  ["Print the values sorted: left subtree, node, right subtree. Fill the first call."] = "値をソート順に表示: 左部分木、ノード、右部分木。最初の呼び出しを穴埋め。",
  ["Print then ln. fmt.println with a small p does not exist outside fmt."] = "Print のあとに ln。小文字pの fmt.println はfmtの外には存在しません。",
  ["Problem five: search and sort. Binary search on a sorted slice with half-open bounds, then merge sort, the recursion every interviewer loves. And the one-liner from the library."] = "第 5 問: 探索とソート。半開区間でソート済み slice を二分探索、次に面接官が大好きな再帰、マージソート。そしてライブラリの 1 行版。",
  ["Problem four: the order queue as a singly linked list. Reverse it in place with three pointers, then detect a cycle with two runners of different speed."] = "第 4 問: 注文キューを単方向リストで。ポインタ 3 つでその場で反転し、速さの違う 2 つのランナーで循環を検出。",
  ["Problem seven, the one they always ask: N workers pull jobs from a channel and push results. Get the close and the wait in the right order and the job is yours."] = "第 7 問、必ず聞かれるやつ: N 個の worker が channel から jobs を取り、results を送る。close と wait の順番を正しくすれば内定はきみのもの。",
  ["Problem six: the classics. Two numbers that add up to the set price, a palindrome check that handles CJK, and whether two dish names are anagrams."] = "第 6 問: 定番問題。セット価格になる 2 つの数、CJK 対応の回文判定、そして 2 つの料理名がアナグラムかどうか。",
  ["Problem three: walk the MTR graph. Breadth-first with a queue for shortest hops, depth-first with recursion for reachability. Both need a visited set."] = "第 3 問: MTR のグラフを巡る。最短ホップはキューで幅優先、到達可能性は再帰で深さ優先。どちらも訪問済み set が要ります。",
  ["Problem two: a binary search tree of order numbers. Insert, walk in order, measure the height. In Go a tree is just a struct with two pointers and a nil at every leaf."] = "第 2 問: 注文番号の二分探索木。挿入し、順に巡回し、高さを測る。Go の木はポインタ 2 つを持つ struct と、葉ごとの nil にすぎません。",
  ["Process, start, join, __main__"] = "Process、start、join、__main__",
  ["ProcessPoolExecutor and choosing"] = "ProcessPoolExecutor と選び方",
  ["Processes share nothing, so everything travels: a multiprocessing.Queue is a pipe plus a feeder thread plus pickle at both ends. put and get carry any picklable object; a Pipe is the raw two-ended version. Workers stop on a sentinel, usually None, and a JoinableQueue lets the parent wait with task_done and join."] = "プロセスは何も共有しないので、すべてが運ばれる：multiprocessing.Queue はパイプと供給スレッドと両端の pickle だ。put と get は picklable なオブジェクトなら何でも運び、Pipe は素の両端版。ワーカーは番兵（ふつうは None）で止まり、JoinableQueue は task_done と join で親に待たせてくれる。",
  ["Pull a *RefundError out of the chain to read its fields. Fill: errors.___(err, &re)"] = "チェーンから *RefundError を取り出してフィールドを読みます。埋めてください: errors.___(err, &re)",
  ["Pull a crate in from the terminal without editing the file by hand. Which subcommand?"] = "ファイルを手で編集せず、ターミナルからクレートを取り込む。どのサブコマンド？",
  ["Pull exactly one bowl from the generator by hand. Which built-in?"] = "ジェネレータから手でちょうど一杯引き出す。どの組み込み関数？",
  ["Push appends through the pointer, because it must change the slice itself. Fill the receiver type."] = "Push は slice 自体を変えなければならないので、ポインタ経由で append する。レシーバの型を埋めよ。",
  ["Push, Pop and Min all O(1): low[len(low)-1] is always the smallest thing still on the stack."] = "Push、Pop、Min すべて O(1): low[len(low)-1] は常にスタックに残る最小のもの。",
  ["Put a new key: a new node at the front, and its address in the map. Fill the list method."] = "新しいキーを Put: 先頭に新ノード、そのアドレスを map へ。リストのメソッドを埋めよ。",
  ["Python 3.13 ships an experimental build without the lock. What is it called?"] = "Python 3.13 はそのロックのない実験的ビルドを出している。何と呼ぶ？",
  ["Python has no braces, Alex. The indentation is the block."] = "Python には中括弧がないの、アレックス。インデントがブロックよ。",
  ["Python ignores the rest of a line after which character?"] = "Python はどの文字の後の行の残りを無視する？",
  ["Python's nothing, capital N. Go's nil pointer, Rust's Option::None."] = "Python の「無」、大文字の N。Go の nil ポインタ、Rust の Option::None。",
  ["Python's nothing, capitalised. One per worker, because each one eats exactly one."] = "Python の「何もない」を大文字始まりで。ワーカー一人につき一つ、各自ちょうど一つ食べるから。",
  ["Q other quest"] = "Q 別のクエスト",
  ["Q: "] = "Q: ",
  ["QUEST %d"] = "クエスト %d",
  ["Quadratic time"] = "二次時間",
  ["Quadratic: n squared. Write the power with a caret."] = "二次: n の2乗。べきはキャレットで書く。",
  ["Queue board is stuck at zero. Nobody can order until it counts."] = "行列ボードがゼロで止まってる。数えてくれないと誰も注文できない。",
  ["Queue for wide, stack for deep. Same loop, different end of the Vec."] = "広く行くならキュー、深く行くならスタック。ループは同じ、使う Vec の端が違うだけ。",
  ["Queues, pipes and pickle"] = "Queue、Pipe、そして pickle",
  ["R then Lock. Writers still use Lock and Unlock."] = "R の後に Lock。書き手は今まで通り Lock と Unlock です。",
  ["RLock blocks only while a writer holds the lock. Readers never block each other."] = "RLock は書き手がロックを持っている間だけ止まる。読み手同士は決して邪魔し合わない。",
  ["ROUND 1  -  the brackets"] = "第1ラウンド  -  括弧",
  ["ROUND 1  -  the buzzer"] = "第1ラウンド  -  ブザー",
  ["ROUND 2  -  the stairs"] = "第2ラウンド  -  階段",
  ["ROUND 2  -  the tree"] = "第2ラウンド  -  木",
  ["ROUND 3  -  the map"] = "第3ラウンド  -  路線図",
  ["ROUND 3  -  the window"] = "第3ラウンド  -  窓",
  ["ROUND 4  -  the chain"] = "第4ラウンド  -  鎖",
  ["ROUND 4  -  the top k"] = "第4ラウンド  -  top k",
  ["ROUND 5  -  the shifts"] = "第5ラウンド  -  シフト",
  ["ROUND 5  -  the shuffle"] = "第5ラウンド  -  シャッフル",
  ["ROUND 6  -  the cache"] = "第6ラウンド  -  キャッシュ",
  ["ROUND 6  -  the classics"] = "第6ラウンド  -  定番",
  ["ROUND 7  -  the kitchen"] = "ラウンド 7  -  キッチン",
  ["RUST SET  -  the walk"] = "RUST SET  -  道のり",
  ["RWMutex: RLock for readers, Lock for the one writer. Use it when reads dominate."] = "RWMutex：読み手は RLock、唯一の書き手は Lock。読みが大半の時に使います。",
  ["Race the cooking against the cancel. Which method gives the channel to select on?"] = "調理とキャンセルを競走させる。select する channel をくれるメソッドは？",
  ["Rc counts on one thread only. Which shared pointer may cross threads?"] = "Rc は 1 本のスレッドでしか数えられない。スレッドをまたげる共有ポインタは？",
  ["Reached an empty spot: make the node here. Fill: if n == ___"] = "空いた場所に着いたらここにノードを作る。穴埋め: if n == ___",
  ["Read JSON bytes into the struct. Fill: json.___(b, &order)"] = "JSON のバイト列を struct に読み込みます。埋めてください: json.___(b, &order)",
  ["Read a price that may not exist, with 0 as the fallback, without a crash. Which method?"] = "ないかもしれない値段を、0 を控えにして、落ちずに読む。どのメソッド？",
  ["Read and write, then the word for lock. Readers share it; a writer gets it alone."] = "読みと書き、そしてロックを表す語。読み手は共有でき、書き手は独占する。",
  ["Read the counter without a lock and without a race. Which method?"] = "ロックなしで、レースもなしにカウンタを読む。どのメソッド？",
  ["Read the root value without moving the Box out of the Option. Which Option method borrows the inside?"] = "Box を Option から動かさずに根の値を読む。中身を借用する Option のメソッドは？",
  ["Reading items[3] from a Vec of n items: how many steps, in Big O?"] = "n 個の Vec から items[3] を読む: Big O で何ステップ？",
  ["Reading items[3] from a list of n items: how many steps, in Big O?"] = "n 個のリストから items[3] を読む: Big O で何ステップ？",
  ["Reading items[3] from a slice of n items: how many steps, in Big O?"] = "n 個のスライスから items[3] を読む: Big O で何ステップ？",
  ["Real life: sort orders by price, cheapest first, equal prices keep their order. Which stable slice method takes a key closure?"] = "実際の場面: 注文を値段順に、安い方から並べ、同じ値段なら順序を保つ。キーのクロージャを取る安定なスライスのメソッドは？",
  ["Receipt holds a &'a str. What must the struct declare after its name?"] = "Receipt は &'a str を持つ。struct が名前の後ろに宣言すべきものは？",
  ["Receipt<'_> means some lifetime, I do not need to name it. Clearer than impl<'a> Display for Receipt<'a> when 'a is never used."] = "Receipt<'_> は「何かのライフタイム、名前は要らない」の意味。'a を使わないなら impl<'a> Display for Receipt<'a> より明快。",
  ["Receive until the channel is closed. Fill: for m := ___ ch"] = "channel が閉じるまで受信。埋めて：for m := ___ ch",
  ["Receiver is Send but not Sync: three cooks cannot read the rail at once. Arc shares it; what hands out turns?"] = "Receiver は Send だが Sync ではない: 料理人 3 人が同時にレールを読むことはできない。共有は Arc がやる。順番を配るのは？",
  ["Recurse into the same side you assign to. Mirror of the else branch."] = "代入する側と同じ側へ再帰。else 分岐の鏡写しです。",
  ["Recursion and memoization"] = "再帰とメモ化",
  ["Recursion uses the call stack. Quicksort's average recursion depth, hence stack space, is O(___)"] = "再帰は呼び出しスタックを使う。クイックソートの平均再帰深さ、つまりスタック空間は O(___)",
  ["Recursive types need a pointer. nil children mark the end."] = "再帰的な型にはポインタが必要。子が nil なら終端です。",
  ["Reduce with your own start value and closure. Which method?"] = "自分で決めた初期値とクロージャで reduce する。どのメソッド？",
  ["Refill the ice only if nobody is at the machine. Which method returns false instead of waiting?"] = "誰も機械の前にいないときだけ氷を足す。待つ代わりに false を返すメソッドは？",
  ["Reformat every file to the standard style before the commit. Which subcommand?"] = "コミット前に全ファイルを標準スタイルに整形する。どのサブコマンド？",
  ["Release the lock however the function exits. Fill: defer mu.___()"] = "関数がどう終わってもロックを解放。埋めて：defer mu.___()",
  ["Release the lock however the function leaves, error or not. Which keyword?"] = "エラーでもそうでなくても、関数がどう抜けてもロックを離す。どのキーワード？",
  ["Remember which stations were seen, with O(1) lookup. Which built-in?"] = "どの駅を見たか覚える、O(1) の検索で。どの組み込み関数？",
  ["Remove a key from a map. Which built-in?"] = "map からキーを削除する。組み込み関数は？",
  ["Repeat forever until break hands back a value. Which keyword?"] = "break が値を返すまで永遠に繰り返す。キーワードは？",
  ["Repeat while a condition holds. Which keyword?"] = "条件が成り立つ間、繰り返す。キーワードは？",
  ['Report a failed check and keep the test running. Fill: t.___("got %d", n)'] = '失敗を報告しつつテストを続ける。埋めて：t.___("got %d", n)',
  ["Resize every photo and keep the input order. Which method?"] = "全部の写真を縮め、入力の順序を保つ。どのメソッド？",
  ["Response + Writer. An interface, so no star. It is also an io.Writer."] = "Response + Writer。interface なのでアスタリスクなし。io.Writer でもあります。",
  ["ResponseWriter: headers, status, body. Write the status before the body."] = "ResponseWriter: ヘッダ、ステータス、ボディ。ステータスはボディより先に書きます。",
  ["Result and the ? operator"] = "Result と ? 演算子",
  ["Result<T, E> is either Ok(value) or Err(error). The compiler makes you check. The till lights up."] = "Result<T, E> は Ok(値) か Err(エラー) のどちらか。コンパイラが確認を強制する。レジが点灯する。",
  ["Return a plus b without the return keyword. What is the last line of the body?"] = "return キーワードなしで a + b を返す。本体の最後の行は？",
  ["Return an iterator without naming its long type. Which keyword in the return position?"] = "長い型名を書かずにイテレータを返す。戻り値位置のどのキーワード？",
  ["Return the cached answer if it is there. Fill the comma-ok test: if v, ok := memo[n]; ___"] = "キャッシュがあればそれを返します。comma-ok テストを穴埋め: if v, ok := memo[n]; ___",
  ["Returning &o is safe in Go: the compiler sees the reference outlive the frame and moves the value to the heap. Sharing across goroutines does the same."] = "Go では &o を返しても安全だ：コンパイラは参照がフレームより長生きすると見て、値をヒープへ移す。goroutine 間の共有も同じことをする。",
  ["Returns a channel that fires once, later. Capital A."] = "後で一度だけ発火する channel を返します。大文字の A。",
  ["Reverse in place: point the current node back at the one before it. Fill: cur.next = ___"] = "その場で反転: 現在のノードをその前のものに向け直す。埋めよ: cur.next = ___",
  ["Reverse with prev/cur/next pointers. Floyd's cycle check: slow moves one, fast moves two."] = "prev/cur/next のポインタで反転。Floyd の循環検出: slow は 1 歩、fast は 2 歩。",
  ["Reverse(3) < Reverse(2). Wrapping at push time is the whole trick; no custom Ord impl needed."] = "Reverse(3) < Reverse(2)。push のときに包むのが仕掛けのすべて。独自の Ord impl は不要。",
  ["Reverse: point the current node backwards. Fill: node.next = ___"] = "反転: いまのノードを後ろ向きにする。埋めて: node.next = ___",
  ["Right minus left, plus one for the inclusive end."] = "右引く左、両端含みなので 1 を足す。",
  ["Room made: store the value. Which HashMap method writes k to v, replacing an old value if there was one?"] = "場所は空いた: 値を格納する。k に v を書き、古い値があれば置き換える HashMap のメソッドは？",
  ["Round five. A shoebox of receipts on the screen. Bo writes merge sort by hand for the crowd, then admits that sorted() has been Timsort all along, and finds a receipt by amount with bisect."] = "第5ラウンド。スクリーンにレシートの靴箱。ボーは観客のためにマージソートを手で書き、それから sorted() がずっと Timsort だったと認め、bisect で金額からレシートを見つける。",
  ["Round five. Every cook's shift as [start, end]. When is the kitchen staffed at all, as one clean list?"] = "第5ラウンド。各料理人のシフトが [start, end]。厨房に誰かがいるのはいつか、きれいなリスト1つで。",
  ["Round five. Merge the intervals, Mei. Sort first; the interviewer always waits for that word."] = "第5ラウンド。区間をマージしろ、メイ。まずソート。面接官はいつもその言葉を待ってる。",
  ["Round five. Staff shifts as {start, end}. Merge the overlapping ones into one schedule."] = "第 5 ラウンド。スタッフのシフトは {start, end}。重なるものをマージして 1 つのスケジュールに。",
  ["Round five. The night market's noodle stall next door lends its counter as a second whiteboard. Siu Ming lists the cooks' shifts, overlapping every which way, and wants the hours the kitchen is covered as a list of clean blocks. Sort, then one pass: every merged interval is either extended or started."] = "第5ラウンド。隣の夜市の麺屋台が、カウンターを2枚目のホワイトボードとして貸してくれる。シウミンは料理人たちのシフトを並べる。あちこち重なっている。厨房に人がいる時間を、きれいなブロックのリストとして欲しい。ソートして、一回の走査: マージ済みの区間はどれも、伸ばされるか始まるかだ。",
  ["Round five: sort the night's receipts. Write merge sort, then use the built-ins like a grown-up."] = "第5ラウンド: 今夜のレシートをソートしろ。マージソートを書き、それから大人らしく組み込みを使え。",
  ["Round five: the shuffle. Write merge sort by hand, then show me you know the std sorts. O(n log n) or bust!"] = "第 5 ラウンド: シャッフル。マージソートを手で書いて、それから std のソートを知っていると見せてくれ。O(n log n) じゃなきゃダメ！",
  ["Round four. A chain of delivery stops, each pointing to the next. Bo reverses it in place, sends two riders down it at different speeds to find the middle, and checks whether the route loops."] = "第4ラウンド。配達先の連なり、それぞれが次を指す。ボーはそれをその場で反転し、速さの異なる2人のライダーを走らせて中央を見つけ、経路がループしているか確かめる。",
  ["Round four. A million order totals stream past. The third largest, without sorting them all."] = "第 4 ラウンド。100 万件の注文合計が流れていく。全部ソートせずに、3 番目に大きい値を。",
  ["Round four. A million receipts stream past. The third biggest, at any moment, without sorting."] = "第4ラウンド。100万枚のレシートが流れていく。どの瞬間でも3番目に大きいもの、ソートなしで。",
  ["Round four. Receipts by the million, and Siu Ming wants the kth biggest while they are still arriving. Sorting everything is n log n and needs it all in memory; a heap of k keeps just the contenders. Bo draws a small pile with the smallest on top and starts pushing."] = "第4ラウンド。何百万ものレシート、シウミンはまだ届いている最中に k 番目に大きいものが欲しい。全部ソートすれば n log n で、しかも全部メモリに要る。k 個のヒープなら候補だけを持つ。ボーは最小が上に来る小さな山を描き、push を始める。",
  ["Round four. Ten thousand receipts: the third biggest, and the five dishes ordered most. Without sorting all of it."] = "第4ラウンド。レシート1万枚: 3番目に大きいのと、一番注文された料理5つ。全部をソートせずにだ。",
  ["Round four: a linked list. Reverse it, find the middle, catch the loop."] = "第4ラウンド: 連結リスト。反転し、中央を見つけ、ループを捕まえる。",
  ["Round four: reverse the chain, then find its middle. The borrow checker is watching."] = "第 4 ラウンド: 鎖を反転して、その中央を見つける。借用チェッカーが見ているぞ。",
  ["Round six, the one we always ask. A cache of the last 100 menus. Get and Put in O(1). Go."] = "第 6 ラウンド、いつも聞くやつ。直近 100 件のメニューのキャッシュ。Get と Put を O(1) で。始め。",
  ["Round six. A cache that holds n routes. When it is full, the one nobody asked for longest goes."] = "第6ラウンド。n 本の経路を持つキャッシュ。満杯になったら、いちばん長く誰にも聞かれていないものが出ていく。",
  ["Round six. Fast hands, Mei. The crab on the kiosk is keeping time."] = "第 6 ラウンド。手を速く、メイ。キオスクのカニが時間を計ってる。",
  ["Round six. The classics: which two receipts add up to the till's total, are two dish names anagrams, is the shop's slogan a palindrome. A dict, a sort and two pointers. The crowd knows these; Bo has to be fast."] = "第6ラウンド。定番: どの2枚のレシートがレジの合計になるか、2つの料理名はアナグラムか、店のスローガンは回文か。dict、ソート、2つのポインタ。観客も知っている。ボーは速くなければならない。",
  ["Round six. The delivery app looks up the same few routes all night, and the map API charges per call. Siu Ming wants a cache of n routes where the least recently used one leaves first, with get and put in O(1). Bo writes one dict that remembers its order and two methods."] = "第6ラウンド。デリバリーアプリは一晩中同じ数本の経路を引き、地図 API は呼び出しごとに課金する。シウミンは n 本の経路のキャッシュが欲しい。最も長く使われていないものが先に出て、get と put は O(1)。ボーは順序を覚える dict 1つとメソッド2つを書く。",
  ["Round six. The menu API caches the last hundred dishes. Which one goes when the hundred-and-first arrives?"] = "第6ラウンド。メニュー API は直近100品をキャッシュする。101品目が来たらどれが消える？",
  ["Round six: the three questions every interview asks. Two-sum, anagram, palindrome. Go!"] = "第6ラウンド: どの面接でも聞かれる3つの問題。two-sum、アナグラム、回文。行け！",
  ["Round three. A week of profits and losses per hour. Which run of hours made the most?"] = "第3ラウンド。1時間ごとの一週間の損益。いちばん稼いだ連続時間帯は？",
  ["Round three. Daily sales, some negative. Which stretch of days made the most money?"] = "第 3 ラウンド。日ごとの売上、マイナスもある。どの期間が一番稼いだ？",
  ["Round three. Siu Ming writes a row of numbers on the board: the till, hour by hour, some hours negative. The best run of hours, the best three hours in a row, then the longest streak of orders with no dish repeated. Three windows, each slid across the row exactly once."] = "第3ラウンド。シウミンがボードに数の列を書く: レジの1時間ごとの売上、マイナスの時間もある。最良の連続時間帯、最良の連続3時間、そして料理が重ならない最長の注文の連続。3つの窓、それぞれ列を一度だけ滑らせる。",
  ["Round three. The MTR map: stations are nodes, lines are edges. Bo builds the adjacency dict, then finds every station reachable from Causeway Bay, breadth first, then depth first."] = "第3ラウンド。MTR の路線図: 駅はノード、路線は辺。ボーは隣接 dict を組み、銅鑼湾から到達できるすべての駅を見つける。まず幅優先、次に深さ優先。",
  ["Round three: the MTR map as a graph. Breadth first, then depth first. Do not visit a station twice!"] = "第 3 ラウンド: MTR の路線図をグラフとして。まず幅優先、次に深さ優先。同じ駅を 2 度訪ねるな！",
  ["Round three: the MTR map as a graph. Build it, sweep it wide, then sweep it deep."] = "第3ラウンド: MTR の路線図をグラフとして。組み立て、広く掃き、それから深く掃く。",
  ["Round three: the best run of sales in a week, the busiest k hours, the longest streak of different dishes. All one pass."] = "第3ラウンド: 1週間で最高の売上の連なり、一番忙しい k 時間、違う料理の最長の連続。全部1パスだ。",
  ["Round two. Siu Ming draws a staircase and a pile of coins. Bo has climbed the MTR exit ten thousand times and counted the till's change every night; now the question is how many ways and how few coins. A table that fills from the bottom up, and a marker for the impossible."] = "第2ラウンド。シウミンが階段とコインの山を描く。ボーは MTR の出口を一万回登り、毎晩レジの釣り銭を数えてきた。今度の問いは、何通りか、そしてコインは最少何枚か。下から埋まる表と、不可能を示す印。",
  ["Round two. The MTR exit has n steps, you take one or two at a time. How many ways up?"] = "第 2 ラウンド。MTR の出口は n 段、1 段か 2 段ずつ上る。上り方は何通り？",
  ["Round two. The Times Square stairs: one or two steps at a time. How many ways up? Then make change for the till."] = "第2ラウンド。タイムズスクエアの階段: 1段か2段ずつ。上まで何通り？それからレジのお釣りを作れ。",
  ["Round two. The screen shows the whiteboard from the back office: a tree of order numbers. Smaller to the left, larger to the right. Bo has to grow it, walk it in order, measure it and sweep it level by level."] = "第2ラウンド。スクリーンにはバックオフィスのホワイトボード: 注文番号の木。小さいものは左へ、大きいものは右へ。ボーはそれを育て、中順に歩き、測り、階層ごとに掃く。",
  ["Round two: a binary search tree. Insert, walk it in order, measure it, then level by level."] = "第2ラウンド: 二分探索木。挿入し、中順に歩き、測り、それから階層ごとに。",
  ["Rows go 0..len, so len itself is out. The same test on c covers the right edge; the top and left are handled by wrapping."] = "行は 0..len なので、len 自体は外。c への同じ確認が右端をカバーし、上と左はラップで処理される。",
  ["Rows run from 0 to len(g)-1; len(g) itself is already outside."] = "行は 0 から len(g)-1 まで。len(g) 自体はもう外。",
  ["Run close() when this function returns, even on error. Which keyword?"] = "この関数が return する時に close() を実行。エラー時も。キーワードは？",
  ["Run cross(), then test its error in the same if. Fill the operator: err ___ nil"] = "cross() を実行し、同じ if でエラーを調べる。演算子を埋める: err ___ nil",
  ["Run every function marked with the #[...] attribute for checks. Which subcommand?"] = "検査用の #[...] 属性が付いた関数を全部走らせる。どのサブコマンド？",
  ["Run fry beside the main thread. Which class from threading?"] = "メインスレッドの横で fry を走らせる。threading のどのクラス？",
  ["Run grind on its own core. Which multiprocessing class?"] = "grind を自分のコアで走らせる。どの multiprocessing クラス？",
  ["Run the cooks, stop on the first error, wait for all. Fill: g.___()"] = "コックを走らせ、最初のエラーで止め、全員を待つ。埋めて：g.___()",
  ["Rune, Count, In, String: one long name. Or len([]rune(s))."] = "Rune、Count、In、String をつなげた長い名前。または len([]rune(s))。",
  ["Russell Street"] = "ラッセルストリート",
  ["Rust ignores the rest of a line after which two characters?"] = "Rust はどの 2 文字の後ろを行末まで無視する？",
  ["Rust? I only know Go. Is it far?"] = "Rust？ぼくは Go しか知らないよ。遠いの？",
  ["RwLock: many .read() guards at once, or one .write(). Use it when reads far outnumber writes; Mutex is simpler otherwise."] = "RwLock: 同時に多数の .read() ガード、または 1 つの .write()。読みが書きよりずっと多いときに使う。そうでなければ Mutex の方が単純。",
  ["S  THIS STREET"] = "S  この街",
  ["S  WHOLE QUEST"] = "S  クエスト全体",
  ["S  WHOLE TRACK"] = "S  トラック全体",
  ["S for string, then printf. Fprintf writes to a writer, Printf to stdout."] = "string の S、そして printf。Fprintf は writer へ、Printf は stdout へ書きます。",
  ["SAVED  %s"] = "保存しました  %s",
  ["SAVED %d FILES  in %s"] = "%d ファイル保存  %s に",
  ["SHARE"] = "シェア",
  ["SHARE THIS QUIZ"] = "このクイズをシェア",
  ["SHARED IT"] = "シェアした",
  ["SPEED TYPER"] = "スピードタイパー",
  ["STOP"] = "停止",
  ["STREAK x%d"] = "連続 x%d",
  ["Same &mut memo goes into both calls, one after the other. The borrow checker is happy: they do not overlap."] = "同じ &mut memo が順番に両方の呼び出しへ入る。借用チェッカーは満足: 重ならないから。",
  ["Same board, Rust this time. The question never changes: input doubles, then what?"] = "同じボード、今度は Rust。問いは変わらない: 入力が倍になったら、それで？",
  ["Same built-in as for slices. A literal map[string]int{} also works."] = "slice と同じ組み込み関数。リテラル map[string]int{} でもOK。",
  ["Same keyword as for slices. No index; just the value."] = "slice の時と同じキーワード。インデックスなし、値だけです。",
  ["Same lesson as the Go till, one floor up: the resource is shared even when the memory is not."] = "一階上の Go のレジと同じ教訓ね：メモリが共有でなくても、資源は共有なの。",
  ["Same name as Go's entry function, but it needs no package line."] = "Go の入口関数と同じ名前。でも package の行はいらない。",
  ["Same name as on HashMap, but on a set it returns bool. No contains check needed first."] = "HashMap にあるのと同じ名前。ただし集合では bool を返す。先に contains で確かめる必要はない。",
  ["Same name as strings.Contains. Index returns the position or -1."] = "strings.Contains と同じ名前。Index は位置か -1 を返します。",
  ["Same name as the Display helper on any value. to_string_pretty adds newlines."] = "どんな値にもある Display のヘルパーと同じ名前。to_string_pretty は改行を入れる。",
  ["Same name as the blocking one in the time module, but awaited."] = "time モジュールのブロックする版と同じ名前だが、await する。",
  ["Same name as the derived trait, in lowercase."] = "derive したトレイトと同じ名前、小文字で。",
  ["Same row, one column to the left."] = "同じ行、1列左。",
  ["Same six letters as Go. Use it for early exits, not for the last line."] = "Go と同じ 6 文字。早期リターンに使い、最後の行には使わない。",
  ["Same thing from a generator: setup, yield, teardown. Which contextlib decorator?"] = "同じことをジェネレータで: 準備、yield、後片付け。どの contextlib デコレータ？",
  ["Same verb as go run. cargo build only compiles."] = "go run と同じ動詞。cargo build はコンパイルだけ。",
  ["Same word as Go and Rust. Its sibling skips to the next turn instead."] = "Go や Rust と同じ単語。その兄弟は代わりに次の回へ飛ぶ。",
  ["Same word as Go, but a method that changes the list in place and returns None."] = "Go と同じ単語だが、リストをその場で変えて None を返すメソッド。",
  ["Same word as Go, no quotes, no parentheses. from x import y picks one name out."] = "Go と同じ単語、引用符も括弧もなし。from x import y は名前を1つだけ取り出す。",
  ["Same word as Go. Rust can drop it on the last line; Python cannot."] = "Go と同じ単語。Rust は最後の行で省けるが、Python は省けない。",
  ["Same word as WaitGroup's. It returns the first non-nil error."] = "WaitGroup と同じ単語。最初の非 nil エラーを返します。",
  ["Same word as a single import, then parentheses."] = "単独のimportと同じ単語、そのあとに括弧です。",
  ["Same word as in switch. Turns select into a poll."] = "switch と同じ単語。select をポーリングに変えます。",
  ["Same. Big O drops constants: O(2), O(500) are all O(1). The flat line is drawn."] = "同じ。Big O は定数を落とす: O(2)、O(500) はすべて O(1)。平らな線が描かれた。",
  ["Same. Big O drops constants: O(2), O(500) are all written O(1). The flat line is drawn; the counter street is done."] = "同じ。Big O は定数を落とす: O(2)、O(500) はすべて O(1) と書く。平らな線が描かれ、カウンターの街は完了。",
  ["Satisfied implicitly: any type with those methods implements it."] = "暗黙に満たされます。そのメソッドを持つ型はすべて実装しています。",
  ["Save next, flip the link, advance both. prev is the new head when the loop ends."] = "next を保存、リンクを反転、両方を進める。ループ終了時の prev が新しい先頭。",
  ["Save nxt, flip the pointer, step. Three names, one pass, O(1) space. The tuple swap on the last line steps both."] = "nxt を保存し、ポインタを反転し、進む。3つの名前、一回の走査、O(1) の空間。最後の行のタプル交換で両方が進む。",
  ["Schedules a call for later. Last in, first out. After the return happens."] = "呼び出しを後回しに予約。後入れ先出し。return の後に実行されます。",
  ["Second python, second core"] = "二つ目の python、二つ目のコア",
  ["Send a value into the channel. Fill the operator: ch ___ muffin"] = "channel に値を送信。演算子を埋めて：ch ___ muffin",
  ["Send one job now and keep the handle. Which method?"] = "仕事を一件いま送って、ハンドルを持っておく。どのメソッド？",
  ["Send results back to the parent. Which multiprocessing class?"] = "結果を親へ送り返す。どの multiprocessing クラス？",
  ["Send the jobs, then tell the workers there are no more. Which built-in?"] = "jobs を送り、もうないと worker に伝える。どの組み込み関数？",
  ["Send: safe to move to another thread. Sync: safe to share by &T. Rc has neither, Arc<T> has both when T does. The count is right. Milk tea and a pineapple bun: the afternoon tea set is yours."] = "Send: 別スレッドへ安全に移せる。Sync: &T で安全に共有できる。Rc はどちらも持たず、Arc<T> は T が持てば両方持つ。数が合った。ミルクティーとパイナップルパン: アフタヌーンティーセットは君のもの。",
  ["Sender is Clone, Receiver is not: that is the mp and the sc in mpsc. Both tills feed one kitchen."] = "Sender は Clone、Receiver は違う: それが mpsc の mp と sc。両方のレジが 1 つの厨房に流し込む。",
  ["Separate interpreters mean separate memory: nothing is shared by accident, and everything shared on purpose has to be sent."] = "インタプリタが別なら、メモリも別だ：偶然に共有されるものはなく、意図して共有するものはすべて送らねばならない。",
  ['Serve /order with the function serve. Fill: http.___("/order", serve)'] = '/order を関数 serve で処理。埋めてください: http.___("/order", serve)',
  ["Serve three bowls, numbered 0, 1, 2. Which built-in counts for the for loop?"] = "丼を3杯、0、1、2 と番号を付けて出す。for ループのために数える組み込み関数は？",
  ["SetMeal extends Order and must run Order's __init__ first. Which built-in reaches the parent?"] = "SetMeal は Order を継承し、先に Order の __init__ を走らせなければならない。親に届く組み込み関数は？",
  ["Setting a channel to nil disables its case without touching the loop. It is the standard way to drain two inputs that end at different times."] = "channel を nil にすると、ループに触れずにその分岐だけ消える。終わる時刻の違う二つの入力を汲み尽くす定番のやり方だ。",
  ["Seven letters, an adverb: at the end, no matter what. Go's defer."] = "7文字、副詞: 最後に、何があっても。Go の defer。",
  ["Seven letters, the end of almost every iterator chain. The type annotation on the left tells it what to build."] = "7文字、ほぼすべてのイテレータチェーンの終わり。左の型注釈が何を組むかを教える。",
  ["Seven letters, the opposite of acquire. Go writes it defer mu.Unlock()."] = "七文字、acquire の反対。Go では defer mu.Unlock() と書く。",
  ["Seven letters, the unbounded one. sync_channel(n) would take a capacity."] = "7 文字、容量が無制限の方。sync_channel(n) なら容量を取る。",
  ["Seven letters. Does the value ... this pattern? Same verb, plural form."] = "7文字。値はこのパターンに...するか？ 同じ動詞の三単現形。",
  ["Seven letters. For humans; Debug is for {:?}."] = "7 文字。人間向け。Debug は {:?} 向け。",
  ["Seven letters. Gather everything into a container: Vec, String, HashMap, even Result."] = "7文字。全部をコンテナに集める: Vec、String、HashMap、Result まで。",
  ["Seven letters. Go spelled it chan."] = "7 文字。Go では chan と書いた。",
  ["Seven letters. The opposite of a debug build. The binary lands in target/ under that name."] = "7文字。デバッグビルドの反対。バイナリは target/ 配下のその名前のフォルダに出る。",
  ["Seven letters: a whole server process that owns the objects and answers questions about them."] = "七文字：オブジェクトを持ち、それについての問い合わせに答える、まるごと一つのサーバープロセス。",
  ["Seven streets of Big O. Read a loop, name its cost, then write the faster one, in Go."] = "Big O の7つの街。ループを読み、そのコストを言い、より速いものを Go で書く。",
  ["Seven streets of Big O. Read a loop, name its cost, then write the faster one, in Python."] = "Big O の7つの街。ループを読み、そのコストを言い、より速いものを Python で書く。",
  ["Seven streets of Big O. Read a loop, name its cost, then write the faster one, in Rust."] = "Big O の7つの街。ループを読み、そのコストを言い、より速いものを Rust で書く。",
  ["Shared and mutable across threads: wrap it, then lock it."] = "スレッドをまたいで共有かつ可変: 包んで、それからロック。",
  ["Shared references and data races"] = "共有参照とデータレース",
  ["Shipped. One more: the code still sorts by hand."] = "出荷完了。あとひとつ: コードがまだ手でソートしてる。",
  ["Short declaration. Fill the operator: floor ___ 8"] = "短い変数宣言。演算子を埋めてください: floor ___ 8",
  ["Short for format. Println lives there."] = "format の略です。Println はそこにあります。",
  ["Short for function. Then the name, then arguments in parentheses."] = "function の略。そのあと名前、括弧の中に引数。",
  ["Shout the shop name. Which strings function upper-cases?"] = "店名を大声で。大文字にする strings の関数は？",
  ["Shouted in capitals, and also an environment variable. GO, MAX, and short for processors."] = "全部大文字で叫ぶ名前で、環境変数でもある。GO、MAX、そしてプロセッサの略。",
  ["Signed, 32 bits, the default integer type. Write the annotation."] = "符号あり、32 ビット、デフォルトの整数型。型注釈を書いて。",
  ["Since Go 1.19 the type itself is atomic, so no &x is needed. Name and bit width."] = "Go 1.19 から型そのものがアトミックなので &x は要らない。名前とビット幅。",
  ["Since Python 3.8 this is real POSIX shared memory: one block of bytes, mapped into every process that asks for it by name."] = "Python 3.8 からこれは本物の POSIX 共有メモリだ：バイトの塊一つが、名前で求めるすべてのプロセスにマップされる。",
  ["Siu Ming"] = "シウミン",
  ["Siu Ming draws the Causeway Bay MTR exit: n steps. Then the till: coins of 1, 3 and 4, and an amount to make with the fewest coins. Two problems, one trick: write the answer for the small cases, then build every bigger one out of the ones already on the board."] = "シウミンが銅鑼湾の MTR 出口を描く: n 段。次はレジ: 1、3、4 のコインと、最少枚数で作る金額。問題は 2 つ、コツは 1 つ: 小さいケースの答えを書き、大きいものはすべてボード上にあるものから組み立てる。",
  ["Siu Ming pins a strip of numbers to the board: Lucky Mac's daily profit for a month, red on the bad days. Best run of days, best k days in a row, longest run of distinct dishes on the specials board. Three questions, one shape: a window that slides right and never looks back."] = "シウミンが数字の帯をボードに留める: ラッキーマックの 1 か月の日ごとの利益、悪い日は赤。最高の連続日、最高の連続 k 日、スペシャルボードで異なる料理が続く最長の並び。問いは 3 つ、形は 1 つ: 右へ滑って決して振り返らない窓。",
  ["Siu Ming pins the week's roster to the board: thirty shifts, half of them overlapping, the manager wants one clean line per stretch of coverage, and then how many cooks are ever on at once. Mei taps the first column: sort by start and the mess becomes a walk."] = "シウミンが今週のシフト表をボードに留める: 30 のシフト、半分は重なっていて、店長はカバーされる区間ごとに 1 本のきれいな線を欲しがる、そしてコックが同時に最大何人いるか。メイが最初の列を叩く: start でソートすれば、混乱は一本道になる。",
  ["Siu Ming's phone book of suppliers, sorted by name. Nobody reads it from the front. Open the middle, go left or right, and the book is half as thick every time. Mei draws a line that climbs, then almost stops."] = "シウミンの取引先電話帳、名前順。誰も最初から読まない。真ん中を開き、左か右へ行くと、本は毎回半分の厚さになる。メイは登ってからほぼ止まる線を描く。",
  ["Siu Ming's phone book of suppliers, sorted by name. Open the middle, go left or right, and the book is half as thick every time. Mei draws the line that climbs, then almost lies down."] = "シウミンの取引先電話帳、名前順。真ん中を開き、左か右へ行くと、本は毎回半分の厚さになる。メイは登ってからほぼ寝てしまう線を描く。",
  ["Six goroutines write one slice with no lock. Which expression keeps that safe?"] = "六つの goroutine がロックなしで一つの slice に書く。どの式なら安全？",
  ["Six letters, capital O. Rust's answer to nil: the type itself says maybe."] = "6 文字、大文字の O。nil への Rust の答え: 型そのものが「あるかも」と言う。",
  ["Six letters, same word as Go, but there is no type keyword in front."] = "6 文字、Go と同じ単語。でも前に type キーワードはつかない。",
  ["Six letters, takes a reference to the key, returns the old value as Option."] = "6文字、キーの参照を受け取り、古い値を Option で返す。",
  ["Six letters, the noun for what a function gives back. This one blocks until it exists."] = "六文字、関数が返すものを指す名詞。存在するまで止まる。",
  ["Six letters, the same method a HashMap uses to store a key. Takes the value, not a reference."] = "6文字、HashMap がキーを格納するのと同じメソッド。参照ではなく値を受け取る。",
  ["Six letters, the same word the C library uses for deleting a file."] = "六文字、C ライブラリがファイル削除に使うのと同じ語。",
  ["Six letters, the word Unix uses for a background service."] = "六文字、Unix が常駐サービスを呼ぶ語。",
  ["Six letters, the write of every HashMap. Returns the previous value as Option."] = "6文字、どの HashMap にもある書き込み。前の値を Option で返す。",
  ["Six letters, under sync/. Go 1.19 also has atomic.Int64 with .Add(1)."] = "6文字、sync/ の下。Go 1.19 には .Add(1) を持つ atomic.Int64 もあります。",
  ["Six letters, what you do with a form. It returns immediately, with a Future."] = "六文字、書類に対してする行為。すぐに Future を添えて返る。",
  ["Six letters. Every result, in order, comma separated."] = "6文字。すべての結果を順番に、カンマ区切りで。",
  ["Six letters. Generic over T: Some(T) or None."] = "6 文字。T についてジェネリック: Some(T) か None。",
  ["Six letters. Give the field a different name on the wire. rename_all does a whole struct."] = "6文字。フィールドに通信上の別名を与える。rename_all は構造体まるごと。",
  ["Six letters. Like a coffee one: only what passes the test comes through."] = "6文字。コーヒーのやつと同じ: テストに通ったものだけが抜けてくる。",
  ["Six letters. The closure gets &char and returns bool; true keeps the item."] = "6 文字。クロージャは &char を受け取り bool を返す。true なら要素を残す。",
  ["Six letters. The compiler writes the trait implementation for you."] = "6 文字。トレイトの実装はコンパイラが書いてくれる。",
  ["Six letters. The word in fmt spelled out. Variables can go straight inside the braces."] = "6文字。fmt をフルスペルにした単語。変数は波かっこの中に直接書ける。",
  ["Six letters. To obtain from a source."] = "6 文字。元から導き出すこと。",
  ["Six letters. Two arms: Ok(T) and Err(E)."] = "6 文字。アームは 2 つ: Ok(T) と Err(E)。",
  ["Six letters. What you do when you are sure it is there."] = "6 文字。そこにあると確信しているときにすること。",
  ["Six letters: to bring together. tokio::join! does the same for a fixed number."] = "6文字: 集める。tokio::join! は固定数に対して同じことをする。",
  ["Six letters; other languages say catch. Name the type after it, never bare."] = "6文字。他の言語では catch と言う。後ろに型を書くこと、決して裸にしない。",
  ["Six riders wait on the kerb because the backend asks the map API one address at a time."] = "バックエンドが地図 API に住所をひとつずつ聞くせいで、ライダー6人が路肩で待っている。",
  ["Six tickets sent. Now end the cooks' loops: recv must return Err. What do you do with tx?"] = "伝票を 6 枚送った。今度は料理人のループを終わらせる: recv が Err を返さなければならない。tx をどうする？",
  ["Six woks, one tray rack, one map of dish counts. The program died with: concurrent map writes."] = "中華鍋六つ、トレイ棚一つ、皿数の map 一つ。プログラムは concurrent map writes と言って死んだ。",
  ["Six workers, one out channel. Who ends the range over out, and how?"] = "ワーカー六人、out は一本。out の range を誰がどうやって終わらせる？",
  ["Size the pool by the machine. Which runtime call reports the cores?"] = "プールの大きさを機械に合わせる。コア数を報告する runtime 呼び出しは？",
  ["Skip a closed shop and go on to the next one. Which keyword?"] = "閉まっている店を飛ばして次へ進む。キーワードは？",
  ["Skip writing __init__, __repr__ and __eq__ by hand. Which decorator generates them from the fields?"] = "__init__、__repr__、__eq__ を手で書くのを省く。フィールドからそれらを生成するデコレータは？",
  ["Slices alias. Use copy() or append([]int(nil), a...) when you need your own."] = "slice は別名です。自分用が必要なら copy() か append([]int(nil), a...) を。",
  ["Sliding window, two pointers"] = "スライディングウィンドウ、2 ポインタ",
  ["Sliding window: O(n) instead of O(n*k) for summing every window from scratch."] = "スライディングウィンドウ: 各窓を一から足す O(n*k) の代わりに O(n)。",
  ["Sliding windows and two pointers"] = "スライディングウィンドウと2つのポインタ",
  ["Smaller goes left, bigger goes right. Draw it before you type it."] = "小さい方は左、大きい方は右。打つ前に描いてみて。",
  ["Smaller goes left, bigger goes right. In Rust a leaf is None and a child is a Box."] = "小さいものは左、大きいものは右。Rust では葉が None で、子は Box。",
  ["Smaller left, larger right: the BST invariant. Assigning the result back handles the None case."] = "小さいのは左、大きいのは右: BST の不変条件。結果を代入し戻すことで None の場合を処理する。",
  ["Smaller values go down one side. Fill the arm: if v < n.val => insert(&mut n.___, v)"] = "小さい値は片側へ下りる。腕を埋めて: if v < n.val => insert(&mut n.___, v)",
  ["Smaller values go left. Fill: n.Left = insert(n.___, v)"] = "小さい値は左へ。穴埋め: n.Left = insert(n.___, v)",
  ["Smaller wins: the smallest value floats to index 0."] = "小さい方が勝つ: 最小値が添字 0 に浮く。",
  ["So I only have to know which one waits and which one computes."] = "じゃあ、どっちが待ちでどっちが計算かだけ覚えればいいのね。",
  ["So binary search on n sorted items costs how much, in Big O?"] = "では n 個のソート済み項目への二分探索は、Big O でいくら？",
  ["So binary_search on n sorted items costs how much, in Big O?"] = "では n 個のソート済み項目への binary_search は、Big O でいくら？",
  ["So bisect on n sorted items costs how much, in Big O?"] = "では n 個のソート済み項目への bisect は、Big O でいくら？",
  ["So share the bytes and send only the name of the block?"] = "じゃあバイト列を共有して、送るのはその塊の名前だけ？",
  ["Sockets, file handles, locks and lambdas do not travel. Send plain data and let the child open what it needs on its own side."] = "ソケット、ファイルハンドル、ロック、lambda は運べない。素のデータを送り、必要なものは子が自分の側で開けばよい。",
  ["Sogo"] = "そごう",
  ["Sogo's directory is a map from shop name to floor. Missing keys return the zero value, so you must ask comma-ok before you trust the number."] = "そごうの案内板は店名から階への map。無いキーはゼロ値を返すので、数を信じる前に comma-ok で確かめましょう。",
  ["Some or None. Rust has no null, so the possibly-empty next is spelled out in the type."] = "Some か None か。Rust に null はないので、空かもしれない next は型に書き表す。",
  ["Sort by start, then walk once: if the next interval starts before the last merged one ends, extend that end to the larger; otherwise push a new interval. O(n log n) for the sort, O(n) for the walk."] = "start でソートし、1回歩く: 次の区間が最後にマージした区間の終わりより前に始まるなら、その終わりを大きい方へ伸ばす。そうでなければ新しい区間を push。ソートが O(n log n)、歩くのが O(n)。",
  ["Sort by start. Walk once: if the next interval starts before the last merged one ends, extend that end to the larger of the two; otherwise start a new block."] = "開始でソート。一回歩く: 次の区間が最後にマージした区間の終わりより前に始まるなら、その終わりを2つの大きい方まで伸ばす。そうでなければ新しいブロックを始める。",
  ["Sort first, Bo. Once they're in order, overlaps are always neighbours."] = "まずソートよ、ボー。順に並べば、重なりはいつも隣同士。",
  ["Sort first. Sorted, the only interval that can overlap is the one you just kept."] = "まずソート。ソート済みなら、重なりうる区間は今保持したものだけ。",
  ["Sort intervals by start; then every overlap is adjacent. Overlap when cur's start <= last's end: extend last's end with max. Otherwise append. Rooms: sort starts and ends separately, two pointers."] = "区間を start でソートする。すると重なりはすべて隣同士。cur の start <= last の end なら重なり: last の end を max で伸ばす。そうでなければ append。会議室: start と end を別々にソートし、2 ポインタ。",
  ["Sort once for O(n log n), then look items up many times. Each lookup then costs O(___)"] = "一度 O(n log n) でソートし、それから何度も項目を探す。その後の各探索のコストは O(___)",
  ["Sort orders by price with a one-line function. Which keyword makes it?"] = "一行関数で注文を値段順に並べる。それを作るキーワードは？",
  ["Sort the amounts a little faster, when equal items may swap order. Which Vec method?"] = "等しい項目が順序を入れ替えてもよいとき、金額を少し速くソートする。どの Vec メソッド？",
  ["Sort the dish names by length, into a new list. Which built-in?"] = "料理名を長さでソートして新しいリストへ。どの組み込み関数？",
  ["Sort the dish names shortest first, in place. Which built-in is the key?"] = "料理名を短いもの順にその場でソートする。key になる組み込み関数は？",
  ["Sort the intervals by start, earliest first. Fill the comparison."] = "区間を start の早い順にソートせよ。比較を埋めよ。",
  ["Sort the names in place. Fill: slices.___(names)"] = "names をその場でソート。埋めてください: slices.___(names)",
  ["Sort the shifts by start time so overlaps sit side by side. Which element does the key pick?"] = "重なりが隣り合うよう、シフトを開始時刻でソート。key が選ぶ要素は？",
  ["Sort the supplier names. Which function from the sort package?"] = "取引先の名前をソートする。sort パッケージのどの関数？",
  ["Sort, then one pass with a running last: O(n log n) total, O(n) output. The gaps are between the blocks."] = "ソートして、last を持ちながら1パス: 全体で O(n log n)、出力 O(n)。穴はブロックの間にある。",
  ["Sorted input trades the HashMap for two indices: O(n) time and O(1) space after the sort."] = "ソート済み入力なら HashMap を2つの添字に置き換えられる: ソート後は時間 O(n)、空間 O(1)。",
  ["Sorted prices. Find 25 in log n. Then sort the unsorted ones in n log n."] = "ソート済みの価格。log n で 25 を見つけて。次に未ソートを n log n で並べ替え。",
  ["Sorted. Sorting costs O(n log n) once; every search after is O(log n). The phone book street is done."] = "ソート済み。ソートは一度 O(n log n)。その後のすべての探索は O(log n)。電話帳の街は完了。",
  ["Sorting and searching"] = "ソートと探索",
  ["Sorting: n log n"] = "ソート: n log n",
  ["Sounds like request, spelled with a w. Built on hyper and tokio."] = "request と読みが同じで、w で書く。hyper と tokio の上に作られている。",
  ["Space complexity"] = "空間複雑度",
  ["Space counts extra memory, not the input. In-place sort: O(1). A copy of the list: O(n). Recursion uses stack: quicksort O(log n) on average. Memos trade space for time."] = "空間は追加のメモリを数える、入力ではなく。その場ソート: O(1)。リストのコピー: O(n)。再帰はスタックを使う: クイックソートは平均 O(log n)。memo は空間で時間を買う。",
  ["Space counts extra memory, not the input. list.sort in place: O(1). sorted() makes a copy: O(n). Recursion uses stack: quicksort O(log n) on average. Memos trade space for time."] = "空間は追加のメモリを数える、入力ではなく。その場の list.sort: O(1)。sorted() はコピーを作る: O(n)。再帰はスタックを使う: クイックソートは平均 O(log n)。memo は空間で時間を買う。",
  ["Space counts extra memory, not the input. sort_unstable in place: O(1). A clone of the Vec: O(n). Recursion uses stack: quicksort O(log n) on average. Memos trade space for time."] = "空間は追加のメモリを数える、入力ではなく。その場の sort_unstable: O(1)。Vec の clone: O(n)。再帰はスタックを使う: クイックソートは平均 O(log n)。memo は空間で時間を買う。",
  ["Spawn re-imports your file in the child. Anything at top level runs again, including the spawning."] = "spawn は子であなたのファイルを import し直す。トップレベルにあるものは全部もう一度走る。起動の行も含めて。",
  ["Split in half, sort each half, merge. The merge is where the n comes from."] = "半分に分け、それぞれをソートし、マージする。n はマージから来る。",
  ["Spread to all four neighbours: down, up, right, and the last one. Fill it."] = "4つの隣すべてへ広がる: 下、上、右、そして最後の1つ。埋めろ。",
  ["Sprintf returns the text. %s string, %d int, %v anything."] = "Sprintf はテキストを返します。%s は string、%d は int、%v は何でも。",
  ["Stairs, one or two steps at a time. How many ways reach step 2?"] = "階段、1 段か 2 段ずつ。2 段目に着く方法は何通り？",
  ["Star before the type. & takes the address. *p reads through it."] = "型の前にアスタリスク。& でアドレスを取り、*p で中身を読みます。",
  ["Star then the type name. A value receiver (o Order) would change a copy."] = "アスタリスクのあとに型名。値レシーバ (o Order) だとコピーが変わるだけです。",
  ["Start a new module for the project. Fill the subcommand: go ___ init"] = "プロジェクトの新しい module を始めます。サブコマンドを埋めてください: go ___ init",
  ["Start a new thread that runs this closure. Which function?"] = "このクロージャを走らせる新しいスレッドを起こす。関数は？",
  ["Start a task in the background and keep going. Which tokio function?"] = "タスクを裏で走らせて先に進む。tokio のどの関数？",
  ["Start an anonymous function as a goroutine. What closes the line?"] = "無名関数を goroutine として開始。行末に付けるのは？",
  ["Start fetch in the background and keep going without awaiting it yet. Which asyncio function?"] = "fetch をバックグラウンドで始め、まだ await せずに先へ進む。どの asyncio 関数？",
  ["Start fry() in a new goroutine. Which keyword?"] = "fry() を新しい goroutine で開始。キーワードは？",
  ["Start the event loop with main(). Which asyncio function?"] = "main() でイベントループを始める。どの asyncio 関数？",
  ["Start the fetch without waiting for it. Which keyword is Go's async?"] = "待たずに fetch を始める。Go の async はどのキーワード？",
  ['Start the server on port 8080 and block. Fill: http.___(":8080", nil)'] = 'ポート 8080 でサーバを起動してブロック。埋めてください: http.___(":8080", nil)',
  ["Start them all first, then join them all: otherwise the second loop waits for the first wok before lighting the second."] = "まず全部 start し、それから全部 join する: さもないと2つ目のループは1つ目の鍋を待ってから2つ目に火を入れる。",
  ["Start three workers, counting each one first. Fill: wg.___(1)"] = "worker を 3 つ起動、その前にそれぞれ数える。穴埋め: wg.___(1)",
  ["Start with an empty dict. What literal is it?"] = "空の dict から始める。リテラルは？",
  ["Starting at 0 would answer 0 for [-3, -1]; the right answer is -1. Seed from the data."] = "0 から始めると [-3, -1] に 0 と答える。正解は -1。データから種をまけ。",
  ["Starts like is_some(), then one more word joining a condition. Three words, two underscores."] = "is_some() のように始まり、条件をつなぐ単語がもうひとつ。3単語、アンダースコア2つ。",
  ["Station to its neighbours: a dict whose missing keys start as an empty list. Fill the factory."] = "駅からその隣駅へ: 欠けたキーが空リストから始まる dict。ファクトリを埋めよ。",
  ["Steam. Hash brown. We did it."] = "湯気。ハッシュブラウン。やったね。",
  ["Step i is reached from one step below or two steps below. Fill dp[i]."] = "i 段目には 1 段下か 2 段下から着く。dp[i] を埋めよ。",
  ["Stop everything: the till has no paper and that is a bug. Which built-in raises the crash?"] = "全部止めろ：レジの紙切れはバグです。クラッシュを起こす組み込み関数は？",
  ["Stop the child from spawning children. Which dunder goes in the guard?"] = "子が子を産むのを止める。ガードにはどのダンダーを置く？",
  ["Stop when the guest walks out. Fill: case <-ctx.___()"] = "客が帰ったら止める。埋めて：case <-ctx.___()",
  ["StopIteration ends the protocol; return inside a generator raises it. The conveyor serves ten thousand bowls, one at a time."] = "StopIteration がプロトコルを終える。ジェネレータ内の return がこれを投げる。コンベアは一万杯を一杯ずつ出す。",
  ["Store into memo[n] before returning. Same shape works for any overlapping subproblem."] = "返す前に memo[n] に保存。重複する部分問題ならどれも同じ形で解けます。",
  ["String and &str"] = "String と &str",
  ["String owns, &str borrows. len() counts bytes, chars().count() counts characters."] = "String は所有し、&str は借用する。len() はバイト数、chars().count() は文字数を数える。",
  ["String() string satisfies fmt.Stringer. Println and %v call it automatically."] = "String() string で fmt.Stringer を満たします。Println と %v が自動で呼びます。",
  ['String::from("..") or "..".to_string(). &str borrows, String owns and can grow.'] = 'String::from("..") または "..".to_string()。&str は借用、String は所有していて伸ばせる。',
  ['Strings, not ints: "1" != 1 in Python. Read the input type before the first line.'] = 'int でなく文字列: Python では "1" != 1。最初の行の前に入力の型を読め。',
  ["Strings, runes, bytes"] = "string、rune、byte",
  ["Struct tags and encoding/json"] = "struct タグと encoding/json",
  ["Struct tags are strings after the type. json, xml, db... each package reads its own."] = "struct タグは型の後ろの文字列。json、xml、db など、各パッケージが自分のを読みます。",
  ["Structs, pointers, methods, interfaces"] = "struct、pointer、メソッド、interface",
  ["Sum of every window of k items: add the newcomer, subtract the one that just left. Which index left?"] = "k 個ごとの窓の和: 新入りを足し、出ていったものを引く。出ていった添字は？",
  ["Summing n prices with an iterator: what is the cost in Big O?"] = "n 個の値段をイテレータで合計する: Big O でコストは？",
  ["Swap the first word for Thread and the same block does I/O instead. That is the whole API: one word decides which kind of parallelism you get."] = "最初の語を Thread に替えれば、同じブロックが I/O をする。API はそれだけだ：一語がどちらの並列かを決める。",
  ["Swap the whole menu in one step while readers are reading. Which atomic type?"] = "読み手が読んでいる最中に、メニュー全体を一歩で入れ替える。どのアトミック型？",
  ["Switch one select case off for good. What do you set the channel to?"] = "select の分岐を永久に消す。channel に何を入れる？",
  ["T: PartialOrd + Copy. Bounds are checked at compile time, so largest(&[1.5, 2.5]) and largest(&[18, 22]) both work."] = "T: PartialOrd + Copy。境界はコンパイル時に検査されるので、largest(&[1.5, 2.5]) も largest(&[18, 22]) も動く。",
  ["TAB again: answer   ESC map"] = "TAB もう一度: 答え   ESC 地図",
  ["TAB hint   F5 auto   ESC map"] = "TAB ヒント   F5 自動   ESC 地図",
  ["TAB hint   F5 auto   F6 share   ESC map"] = "TAB ヒント   F5 オート   F6 シェア   ESC マップ",
  ["THREADS  -  the lunch rush"] = "THREADS  -  昼のラッシュ",
  ["THREADS  ·  the lunch rush"] = "THREADS  ·  昼のラッシュ",
  ["THREE LANGUAGES"] = "3つの言語",
  ["Table 7 has a seat. Every other table has nothing. What does the last line return?"] = "7 番テーブルには席がある。他のテーブルには何もない。最後の行は何を返す？",
  ["Take any Cook without naming a type parameter. Which keyword goes before the trait?"] = "型パラメータに名前を付けずに任意の Cook を受け取る。トレイトの前に置くキーワードは？",
  ["Take one back out of the buffered channel. Arrow, then the channel's name."] = "バッファ付き channel から一つ取り戻す。矢印、そして channel の名前。",
  ["Take one from stock, but only if nobody moved it since you read it. Which method?"] = "在庫から一つ引く。ただし読んだあと誰も動かしていないときだけ。どのメソッド？",
  ['Take the address of a new Order so p is a *Order. Fill: p := ___Order{Item: "set"}'] = '新しい Order のアドレスを取って p を *Order にする。埋める: p := ___Order{Item: "set"}',
  ["Take the front station off the queue. Fill: queue = queue[___]"] = "先頭の駅をキューから取り出す。穴埋め: queue = queue[___]",
  ["Take the next result, waiting if the queue is empty. Which method?"] = "次の結果を取り、空なら待つ。どのメソッド？",
  ["Take the second and third tray, items 1 and 2. What goes in the brackets?"] = "2番目と3番目のトレイ、つまり項目 1 と 2 を取る。角括弧の中は？",
  ["Take the station that has waited longest. Which VecDeque method returns Option<u32> from the front?"] = "いちばん長く待った駅を取り出す。前から Option<u32> を返す VecDeque のメソッドは？",
  ["Takes the key and the value by value. Returns the old value as an Option, which we ignore here."] = "キーと値を値渡しで受け取る。古い値を Option で返すが、ここでは無視する。",
  ["Tea first, lifetimes second. The set is almost ready."] = "まずお茶、ライフタイムはその次。セットはもうすぐできる。",
  ['Teach println!("{}") to print an Order. Which fmt trait?'] = 'println!("{}") に Order の出力を教える。fmt のどのトレイト？',
  ["Tell an empty order from a shut belt. Name the second variable of the receive."] = "空の注文と止まったベルトを区別する。受信の二つ目の変数名は？",
  ["Tell receivers no more hash browns will come. Which built-in?"] = "もうハッシュブラウンは来ないと受信側に伝える。組み込み関数は？",
  ["Text plus a number fails. Which built-in turns 4 into text first?"] = "テキストに数を足すと失敗する。4 を先にテキストにする組み込み関数は？",
  ["That is BFS: pop front, push unseen neighbours. First arrival is the shortest path."] = "これが BFS: 先頭を pop し、未訪問の隣を push。最初の到着が最短路。",
  ["That is a trait. Go had interfaces; Rust makes you say impl."] = "それがトレイト。Go には interface があった。Rust では impl と言わせる。",
  ["That is the second value of a receive. One line tells you which."] = "それが受信の二つ目の値だよ。一行でどちらか分かる。",
  ["That is why the sender closes: only the side that knows nothing more is coming can say so safely."] = "だから閉じるのは送り手だ：もう何も来ないと知っている側だけが、安全にそう言える。",
  ["The ! marks a macro call. Macros can take any number of arguments; functions cannot."] = "! はマクロ呼び出しの印。マクロは引数をいくつでも取れるが、関数はできない。",
  ["The * you would write in resize(*job), spelled out, then map."] = "resize(*job) と書くときのあの * を英語で綴り、map を足したもの。",
  ["The 1 a.m. callback is the Python round. Seven whiteboard classics. Get the OFFER."] = "午前 1 時のコールバックは Python ラウンド。ホワイトボードの古典 7 つ。OFFER を勝ち取れ。",
  ["The 11:00 price change holds the write side. Which call does a reader make?"] = "11:00 の値段変更が書き側を握っている。読み手はどう呼ぶ？",
  ["The Express counter"] = "Express のカウンター",
  ["The Express kiosks run Rust. Finish your coffee, I will show you main."] = "Express のキオスクは Rust で動いてる。コーヒーを飲み終えたら、main を見せるよ。",
  ["The Express kitchen"] = "Express のキッチン",
  ["The Express set"] = "Express のセット",
  ["The Express till"] = "Express のレジ",
  ["The GIL protects CPython's own memory bookkeeping. It makes single-threaded code fast and multi-threaded arithmetic pointless."] = "GIL は CPython 自身のメモリ管理の帳簿を守る。シングルスレッドのコードを速くし、マルチスレッドの算術を無意味にする。",
  ["The GIL serializes bytecode; C extensions and I/O release it. Python 3.13 can build without it. Three woks fry at once; the shift is over."] = "GIL はバイトコードを直列化する。C 拡張と I/O はそれを解放する。Python 3.13 はそれなしでビルドできる。3つの鍋が同時に焼く。シフトは終わり。",
  ["The Go 1.21 builtin that picks the larger of two ints."] = "2 つの int の大きい方を選ぶ Go 1.21 の builtin。",
  ["The I in the middle of GIL, written out: the thing that runs your bytecode."] = "GIL の真ん中の I を書き下したもの：バイトコードを走らせるあれ。",
  ['The JSON says "dish" but the field is name. Which serde attribute maps them?'] = 'JSON は "dish" と言うがフィールドは name。両者を対応させる serde の属性は？',
  ["The MTR gate is a function: tap(card) (ok bool, err error). Go functions can return more than one value. That is how errors travel."] = "MTRの改札は関数です: tap(card) (ok bool, err error)。Goの関数は複数の値を返せます。エラーはそうやって運ばれます。",
  ["The MTR map is a graph. Level by level is BFS; as deep as you can is DFS."] = "MTR の路線図はグラフ。一段ずつ広げるのが BFS、行けるだけ深く潜るのが DFS。",
  ["The O(n) fix: remember each name as you go. What value type makes the map a set?"] = "O(n) の直し方: 進みながら各名前を覚える。どの値の型が map を集合にする？",
  ["The O(n) fix: remember each name as you go. Which built-in is the set?"] = "O(n) の直し方: 進みながら各名前を覚える。どの組み込み関数が集合？",
  ["The O(n) fix: remember each name as you go. Which std collection is the set?"] = "O(n) の直し方: 進みながら各名前を覚える。どの std コレクションが集合？",
  ["The __name__ guard: the script runs main() when executed, stays quiet when imported. The shift begins."] = "__name__ ガード: スクリプトは実行時に main() を走らせ、インポート時は黙っている。夜勤が始まる。",
  ["The amount still to make after spending this one coin."] = "このコイン 1 枚を使った後、まだ作るべき金額。",
  ["The ampersand, then the same word that made a changeable."] = "アンパサンド、続けて a を変更可能にしたのと同じ単語。",
  ["The argument is evaluated on the defer line. Only the call is delayed."] = "引数は defer の行で評価されます。遅れるのは呼び出しだけです。",
  ["The arrow leans out of the channel this time. Mirror of the chan<- next to it."] = "今度は矢印が channel から出ている。隣の chan<- の鏡像だ。",
  ["The back office robot runs on generators, decorators and asyncio. Earn the midnight bowl."] = "バックオフィスのロボットはジェネレータ、デコレータ、asyncio で動く。深夜の一杯を手に入れよう。",
  ["The base class of every catchable error, capital E. Not BaseException: that one includes Ctrl-C."] = "捕まえられるすべてのエラーの基底クラス、大文字の E。BaseException ではない: あれは Ctrl-C も含む。",
  ["The bell"] = "ベル",
  ["The belt is closed and empty. What comes out of the next receive?"] = "ベルトは閉じて空だ。次の受信で何が出てくる？",
  ["The belt kept handing me empty trays after the kitchen shut. Empty tray, or no more trays?"] = "厨房が閉めたあとも、ベルトは空のトレイを渡し続けた。空のトレイ？ それとももうトレイがない？",
  ["The belt to the counter"] = "カウンタへ続くベルト",
  ["The blank identifier. Compile error if you name a value you never use."] = "ブランク識別子。使わない値に名前を付けるとコンパイルエラーです。",
  ["The board mixes prices, names and a sold-out flag. What is v today?"] = "ボードには価格、名前、売り切れフラグが混在。今日の v は何？",
  ["The bool from the map lookup. True when the key exists."] = "map 検索で得た bool です。キーがあれば true。",
  ["The booth"] = "ブース",
  ["The booth code used to duplicate fry for every item. Generics write it once. A Kitchen that embeds Grill gets Grill's methods for free."] = "ブースのコードは品目ごとに fry を複製していました。generics なら一度で済みます。Grill を埋め込んだ Kitchen は Grill のメソッドをタダで手に入れます。",
  ["The buffer size is the number of tokens. The fourth send waits."] = "バッファサイズがトークン数。4 つ目の送信は待たされます。",
  ["The built-in constraint for types that allow == and !=."] = "== と != が使える型のための組み込み制約です。",
  ["The built-in interface for failure. Last return value by convention."] = "失敗を表す組み込みinterface。慣例で最後の戻り値です。",
  ["The built-in that picks the smaller of two values."] = "2つの値の小さい方を選ぶ組み込み。",
  ["The built-in whole-number type, three letters, after the colon."] = "組み込みの整数型、3文字、コロンの後。",
  ["The builtin that adds an element to the end of a slice."] = "slice の末尾に要素を足す builtin。",
  ["The builtin that adds to the end of a slice and returns the new slice."] = "slice の末尾に足して新しい slice を返す builtin。",
  ["The builtin that ends a range. One goroutine waits for the workers and then calls it once."] = "range を終わらせる組み込み。一つの goroutine がワーカーを待って、一度だけ呼ぶ。",
  ["The builtin that takes a map and a key. Six letters."] = "map とキーを取る builtin。6 文字。",
  ["The busiest k hours: keep one running sum. The window moves right by one: add a[i], and subtract which element?"] = "一番忙しい k 時間: 累計を1つ持つ。窓が右へ1つ動く: a[i] を足して、引くのはどの要素？",
  ["The cheapest of three prices, no loop, no import. Which built-in (Go 1.21)?"] = "3つの価格の最安値を、ループも import もなしで。どの組み込み関数 (Go 1.21)？",
  ["The child adds to a global and the parent still prints 0. What did the child change?"] = "子がグローバルに足しても、親はまだ 0 を出す。子は何を変えた？",
  ["The classic bug is forgetting max: a short interval inside a long one must not cut it. last is &mut, so this writes into out."] = "定番のバグは max を忘れること: 長い区間の中の短い区間がそれを切ってはいけない。last は &mut なので、これは out に書き込む。",
  ["The classics! Two-sum, palindrome, anagram. Everyone has done these. Once."] = "定番だ！two-sum、回文、アナグラム。みんな一度はやったことがある。一度はね。",
  ["The closer-to-opener map from the first blank."] = "最初の空欄の、閉じから開きへの map。",
  ["The cold room"] = "冷蔵室",
  ["The combinatorics counter"] = "組み合わせカウンター",
  ["The combinatorics counter at the noodle stall: pick any toppings. Bo counts the combinations and the number doubles with every topping. He draws the curve that goes vertical almost at once."] = "麺屋台の組み合わせカウンター: トッピングを好きに選ぶ。ボーが組み合わせを数えると、トッピングごとに数が倍になる。彼はほぼ即座に垂直になる曲線を描く。",
  ["The combinatorics counter at the noodle stall: pick any toppings. Bo counts the combinations and the number doubles with every topping. Mei draws the curve that goes vertical almost at once."] = "麺屋台の組み合わせカウンター: トッピングを好きに選ぶ。ボーが組み合わせを数えると、トッピングごとに数が倍になる。メイはほぼ即座に垂直になる曲線を描く。",
  ["The combinatorics counter at the noodle stall: pick any toppings. Bo counts the combinations and the number doubles with every topping. Mei draws the last curve, the one that goes vertical almost at once."] = "麺屋台の組み合わせカウンター: トッピングを好きに選ぶ。ボーが組み合わせを数えると、トッピングごとに数が倍になる。メイは最後の曲線、ほぼ即座に垂直になる曲線を描く。",
  ["The comma-ok idiom. Same word twice on those two lines."] = "comma-ok イディオム。その2行に同じ単語が2回。",
  ["The compound operator that walks j one step toward the smaller values, on the left."] = "j を左の小さい値の方へ1歩進める複合演算子。",
  ["The conveyor"] = "コンベア",
  ["The conveyor carries bowls from the wok to the pass. Its script builds a list of every bowl of the night before serving the first. A generator would hand them out one at a time, and the belt would never wait."] = "コンベアは丼を中華鍋からパスへ運ぶ。そのスクリプトは最初の一杯を出す前に、今夜のすべての丼のリストを作る。ジェネレータなら1つずつ渡し、ベルトは待たずに済む。",
  ["The conveyor script loads every bowl into memory at once. Ten thousand bowls."] = "コンベアのスクリプトは丼を全部いっぺんにメモリに載せる。一万杯だ。",
  ["The counter"] = "カウンター",
  ["The counts drift and nothing crashes. Which flag makes the test print WARNING: DATA RACE?"] = "数が合わないのにクラッシュはしない。テストに WARNING: DATA RACE と出させるフラグは？",
  ["The crash that pairs with recover. Six letters here, in the third person."] = "recover と対になるクラッシュ。ここでは三人称の形で。",
  ["The cube is a slice of ads. append one more."] = "キューブは広告の slice。もう1つ append して。",
  ["The curly opener, as a char literal in single quotes."] = "波括弧の開く方、シングルクォートの char リテラルで。",
  ["The curly opener, as a one-character string like the other two values."] = "波括弧の開き、他の2つの値と同じく1文字の文字列で。",
  ["The current index: the right edge of the window."] = "現在の添字: 窓の右端。",
  ["The current value. Its partner is target minus it."] = "現在の値。相方は target からそれを引いたもの。",
  ["The customer closed the app two minutes ago and your goroutine is still fetching the ETA."] = "客は二分前にアプリを閉じたのに、あなたの goroutine はまだ ETA を取っている。",
  ["The decorator builds an inner function and must hand it back. What does timer return?"] = "デコレータは内側の関数を作り、それを返さなければならない。timer は何を返す？",
  ["The delivery radio"] = "配達無線",
  ["The delivery radio at the door. Three riders report their position; the script asks each in turn and waits a full second for every answer. Asked at once, the three answers would arrive together."] = "ドアの配達無線。3人のライダーが位置を報告する。スクリプトは1人ずつ尋ね、答えごとにまる1秒待つ。同時に尋ねれば3つの答えは一緒に届く。",
  ["The dict defined on the first line, the one written to two lines below the blank."] = "1行目で定義した dict、空欄の2行下で書き込まれるもの。",
  ["The dict from the first line of the body, value to index."] = "本体の1行目の dict、値からインデックスへ。",
  ["The dict method that removes and returns one (key, value) pair; last=False takes it from the front."] = "(key, value) の組を1つ取り除いて返す dict のメソッド。last=False で先頭から取る。",
  ["The digit for land, as a byte literal in single quotes."] = "陸の数字、シングルクォートのバイトリテラルで。",
  ["The digit one as a u8: a b before the single quotes."] = "数字の 1 を u8 で: シングルクォートの前に b。",
  ["The door sensor counts every customer. Only one number, thousands of times a minute."] = "ドアのセンサが客を数えている。数字は一つ、毎分数千回。",
  ["The dumbwaiter"] = "料理用リフト",
  ["The element on its own: a run that begins right here and has nothing before it."] = "その要素単体: ここから始まり、前に何もない走り。",
  ["The element that just fell off the left edge: k places behind i."] = "左端から落ちたばかりの要素: i の k 個後ろ。",
  ["The element that just fell off the left edge: k positions behind i."] = "左端から落ちたばかりの要素: i の k 個後ろ。",
  ["The element type, plural, capitalized, like sort.Ints for ints."] = "要素の型、複数形、大文字始まり。int の sort.Ints のように。",
  ["The empty till. Making nothing takes no coins at all."] = "空のレジ。何も作らないならコインは要らない。",
  ["The end of every Python chain, capital N."] = "すべての Python の連なりの終わり、大文字の N。",
  ["The entry API: one lookup, insert or update. The classics done, no misses. Combo x6. One round left."] = "entry API: 検索 1 回で、挿入か更新。定番は片づいた、ミスなし。コンボ x6。残りは 1 ラウンド。",
  ["The evening CODE RUSH is the Rust round. Seven classic problems. Get HIRED."] = "夕方の CODE RUSH は Rust ラウンド。古典問題が7つ。採用を勝ち取れ。",
  ["The evening callback is the Rust round. Seven whiteboard classics. Get the OFFER."] = "夕方のコールバックは Rust ラウンド。ホワイトボードの古典 7 つ。OFFER を勝ち取れ。",
  ["The evicted key must leave the map too, or the cache leaks. Which HashMap method deletes by key?"] = "追い出したキーはマップからも消さないと、キャッシュが漏れる。キーで削除する HashMap のメソッドは？",
  ["The field from stage one. Borrow it with &, and cur stays a &Link."] = "第 1 ステージで出たフィールド。& で借りれば cur は &Link のまま。",
  ["The field that is not right. Mei said it in her speech bubble."] = "right でない方のフィールド。メイが吹き出しで言っていた。",
  ["The final round. Three cook threads pull orders from one queue and fry them. Bo has to feed the queue, drain it safely, mark every job finished and wait for the last one before the receipt prints. Then the screen says HIRED."] = "最終ラウンド。3つのコックスレッドが1つのキューから注文を引いて焼く。ボーはキューに供給し、安全に空にし、すべてのジョブに終了の印を付け、レシートが印字される前に最後のジョブを待たなければならない。そしてスクリーンに HIRED。",
  ["The final sheet is a grid of bytes: '1' is land, '0' is water, Hong Kong Island and Kowloon and a scatter of rocks. Siu Ming wants the count. Alex writes a recursive dfs that sinks whatever it touches, then a double loop that calls it on every '1' still standing and counts the calls. The marker squeaks. Then: OFFER."] = "最後の紙はバイトのグリッド: '1' が陸、'0' が水、香港島と九龍と点在する岩。シウミンは数が欲しい。アレックスは触れたものを沈める再帰 dfs を書き、次にまだ残る '1' すべてでそれを呼んで呼び出しを数える二重ループ。マーカーがきしむ。そして: OFFER。",
  ["The final. 01:40. Siu Ming draws Causeway Bay as a grid: 1 for a building, 0 for the road. Bo has to count the islands of buildings, each a patch of 1s touching up, down, left or right. One DFS per island, sinking it as it goes; the count of sinkings is the answer, and the answer is the OFFER."] = "最終問題。01:40。シウミンは銅鑼湾をグリッドとして描く: 建物が 1、道路が 0。ボーは建物の島を数えなければならない。それぞれ上下左右で接する 1 の塊。島ごとに DFS 1回、進みながら沈める。沈めた回数が答えで、答えが OFFER だ。",
  ["The first element of each pair is the start."] = "各組の最初の要素が開始。",
  ["The first element. The loop then starts from the second, see the slice."] = "最初の要素。ループは2番目から始まる、スライスを見ろ。",
  ["The first handler argument is where the reply goes. Fill its type: w http.___"] = "handler の第1引数は返信の書き先。型を埋めてください: w http.___",
  ["The first letter of format. Since Python 3.6."] = "format の頭文字。Python 3.6 から。",
  ["The first line of go.mod names the module. Which keyword?"] = "go.mod の1行目が module を名付けます。どのキーワード？",
  ["The flat"] = "アパート",
  ["The flood function from the blanks above."] = "上の空欄の flood 関数。",
  ["The flood stops at the edge of the map. Fill the row check."] = "flood は地図の端で止まる。行の判定を埋めよ。",
  ["The footbridge to Times Square"] = "タイムズスクエアへの歩道橋",
  ["The four-letter function from the prelude that ends a value early. Not close: channels have no close."] = "prelude にある 4 文字の関数で、値を早めに終わらせるもの。close ではない。チャネルに close はない。",
  ["The free slots are the gaps between merged blocks: pair each block with the next. Fill the slice."] = "空き枠はマージしたブロック同士の隙間: 各ブロックを次のブロックと組にする。スライスを埋めろ。",
  ["The free-threaded build removes the GIL and pays for it in single-thread speed and C extension support. Until it is the default, processes are the answer."] = "free-threaded ビルドは GIL を外し、その代金をシングルスレッド速度と C 拡張の対応で払う。既定になるまでは、答えはプロセスだ。",
  ["The full word this time. Then the go version, then require lines."] = "今度は完全な語。次に go のバージョン、そして require 行。",
  ["The function calls itself. Same name as on the last line."] = "関数が自分自身を呼びます。最後の行と同じ名前。",
  ["The function itself. The map is shared, so a plain map argument works."] = "関数自身です。map は共有されるので、そのまま引数で渡せます。",
  ["The function that measures a string, passed by name, no parentheses."] = "文字列を測る関数、名前で渡す、括弧なし。",
  ["The function's own name. The recursion is the stack."] = "関数自身の名前。再帰がスタック。",
  ["The generic one that holds an address, not a number."] = "数字ではなくアドレスを持つジェネリックな型。",
  ["The grid holds bytes, not ints: '1' is 49, 1 is 1. Compare with the character."] = "グリッドは int ではなくバイト: '1' は 49、1 は 1。文字と比べよ。",
  ["The grid holds one-character strings, and the road is the zero."] = "グリッドが持つのは1文字の文字列、道路がゼロ。",
  ["The grill line"] = "グリルのライン",
  ["The growable array. Three letters, capital V. A neighbour can be pushed on."] = "伸びる配列。大文字の V で始まる 3 文字。隣の駅を push できる。",
  ["The heap never grows past k: O(n log k) time, O(k) space. Sorting would be O(n log n) and O(n)."] = "ヒープは k を超えて育たない: 時間 O(n log k)、空間 O(k)。ソートなら O(n log n) と O(n)。",
  ["The heap package does the sifting; your Pop only trims the tail. O(log n) per operation."] = "sift はヒープパッケージがやる。あなたの Pop は末尾を切るだけ。操作ごとに O(log n)。",
  ["The index enumerate hands out, one letter. The return line reads it back."] = "enumerate が渡すインデックス、1文字。return の行がそれを読み戻す。",
  ["The index just checked, plus one: everything up to it is too small."] = "ちょうど調べたインデックスに1を足す: そこまでのすべては小さすぎる。",
  ["The index of the left half, mirroring j++ in the else."] = "左半分のインデックス。else の j++ の鏡写し。",
  ["The inner def's name, without parentheses: the function itself, not a call of it."] = "内側の def の名前、括弧なし: 関数そのもの、その呼び出しではない。",
  ["The int32 code point type. Indexing a string gives bytes."] = "int32 のコードポイント型。string のインデックスはバイトを返します。",
  ["The interview asked me this three times. Let's get it right in Go first."] = "面接で3回聞かれた。まず Go で正しくやろう。",
  ["The interview convention: a negative one, since cached values are non-negative."] = "面接の慣習: マイナス1。キャッシュの値は非負だから。",
  ["The invariant: map.len() == order.len(), always. Break it once and the cap check lies."] = "不変条件: 常に map.len() == order.len()。一度でも崩れれば cap の確認が嘘をつく。",
  ["The jobs are tiny and the pool is slower than one core. Which argument fixes it?"] = "仕事が細かすぎて、プールが一コアより遅い。どの引数が直す？",
  ["The key exactly as the phone spells it, inside the quotes."] = "スマホの綴りそのままのキーを、引用符の中に。",
  ["The keyword type, where a type name would go. Only inside a switch."] = "型名の位置にキーワード type。switch の中だけです。",
  ["The kiosk"] = "キオスク",
  ['The kiosk reads "18" from the keypad. Turn it into an i32. Which method?'] = 'キオスクがキーパッドから "18" を読む。i32 に変える。どのメソッド？',
  ["The kiosk row"] = "キオスクの列",
  ["The kiosk wants one function for prices and for weights. Go had any; what now?"] = "キオスクは値段にも重さにも使える関数を 1 つ欲しがってる。Go には any があった。今度は？",
  ["The kitchen"] = "厨房",
  ["The kitchen at 23:00"] = "23:00 のキッチン",
  ["The kitchen is concurrent. One cook cannot wait for the hash brown before starting the muffin. go fry() starts a function in a new goroutine."] = "厨房は並行です。コックはハッシュブラウンを待ってからマフィンを始めるわけにいきません。go fry() は関数を新しい goroutine で開始します。",
  ["The kitchen sends one more order after closing. What happens?"] = "閉じたあと、厨房がもう一件送った。何が起きる？",
  ["The kitchen waits until an order arrives. Which method blocks and takes one?"] = "厨房は注文が来るまで待つ。ブロックして 1 つ取り出すメソッドは？",
  ["The label maker"] = "ラベルメーカー",
  ["The label maker printed 'None' on forty bowls. Somebody returned nothing."] = "ラベルメーカーが40杯に 'None' と印字した。誰かが何も返していない。",
  ["The label maker prints a name and a price per bowl. Half its functions return None by accident and nobody noticed until forty bowls said so. Type hints would have caught it before the shift."] = "ラベルメーカーは丼ごとに名前と値段を印字する。その関数の半分はうっかり None を返していて、40杯がそう言うまで誰も気づかなかった。型ヒントがあればシフトの前に捕まえていた。",
  ["The larger of the two ends wins; a shift fully inside another must not shrink the block."] = "2つの終わりの大きい方が勝つ。別のシフトに完全に含まれるシフトでブロックが縮んではいけない。",
  ["The last arm must catch every other number. Which pattern matches anything?"] = "最後のアームは残りの数をすべて受け止める。何にでもマッチするパターンは？",
  ["The last expression is the return value. One pass, one stack: O(n) time, O(n) space at worst."] = "最後の式が戻り値。1パス、1スタック: 時間 O(n)、空間は最悪 O(n)。",
  ["The last index of a slice of n items."] = "n 個の slice の最後の添字。",
  ["The last item of a Vec in one step, as an Option. Which method?"] = "Vec の最後の要素を一歩で、Option として。どのメソッド？",
  ["The last item of a list in one step, without len. Which index?"] = "len を使わず、リストの最後の要素を一歩で。どのインデックス？",
  ["The last item of a slice in one step. What is subtracted from the length?"] = "スライスの最後の要素を一歩で。長さから何を引く？",
  ["The last sheet before the break is the classic: an LRU cache. Lucky Mac's menu service is slow, keep the hundred most recently asked-for menus in memory, throw out the one nobody has touched for longest. Alex draws a map on the left and a doubly linked list on the right and joins them with arrows."] = "休憩前の最後の紙は古典: LRU キャッシュ。ラッキーマックのメニューサービスが遅いので、最近要求された 100 件のメニューをメモリに置き、一番長く触られていないものを捨てる。アレックスは左に map、右に双方向連結リストを描き、矢印でつなぐ。",
  ["The last stop points nowhere. What is next set to at creation?"] = "最後の配達先はどこも指さない。生成時 next は何に設定される？",
  ["The last tray, without len. Which index?"] = "len を使わずに最後のトレイ。どのインデックス？",
  ["The left pointer only ever moves right, so the while loop costs O(n) over the whole run, not per r."] = "左ポインタは右にしか動かないので、while ループは r ごとではなく全体で O(n)。",
  ["The length of any collection has which unsigned, pointer-sized type?"] = "コレクションの長さは、どの符号なしポインタサイズの型？",
  ["The lift"] = "エレベーター",
  ["The lift panel is a tiny Go program. Floor, name, and a constant for Lucky Mac's opening hour. Zero values matter: an unset int is not blank."] = "エレベーターのパネルは小さなGoプログラム。階、名前、そしてLucky Macの開店時刻の定数。ゼロ値は大事です。未設定の int は空ではありません。",
  ["The list forgot the node; the map must forget the key too. Which builtin removes a map entry?"] = "リストはノードを忘れた。map もキーを忘れなければならない。map の項目を消す builtin は？",
  ["The list method that grows the end. The end of the list is the top of the stack."] = "末尾を伸ばすリストのメソッド。リストの末尾がスタックの先頭。",
  ["The lock needs no constructor: its zero value is ready. Which type?"] = "このロックにコンストラクタは要らない。ゼロ値がそのまま使える。どの型？",
  ["The log tailer must not keep the batch alive. Which flag makes a child die with its parent?"] = "ログの追尾係がバッチを生かし続けてはいけない。子を親と一緒に死なせるフラグは？",
  ["The loop keyword, inside the brackets, after the expression."] = "ループのキーワード、角括弧の中、式の後に。",
  ["The mall atrium"] = "モールのアトリウム",
  ["The map finds the node in O(1); the list moves it in O(1). Neither alone can do both."] = "map はノードを O(1) で見つけ、リストは O(1) で動かす。どちらか一方では両方できない。",
  ["The menu board"] = "メニューボード",
  ["The menu board at the shutter. Prices live in a dict, dish to dollars. It is Go's map with braces instead of make, and a KeyError instead of a zero value when the dish is missing."] = "シャッター脇のメニューボード。値段は dict に住んでいる、料理からドルへ。make の代わりに中括弧、料理がないときはゼロ値の代わりに KeyError の、Go の map だ。",
  ["The menu board reads prices from a dict. Ask for a dish we do not have and it crashes."] = "メニューボードは dict から値段を読む。ない料理を聞くと落ちるんだ。",
  ["The menu is read by two hundred goroutines and written once an hour. Which lock?"] = "メニューは二百の goroutine が読み、書くのは一時間に一度。どのロック？",
  ["The menu is read often, written rarely. Which method takes a shared read guard?"] = "メニューはよく読まれ、まれに書かれる。共有の読み取りガードを取るメソッドは？",
  ["The menu maps dish names to prices. Which generic takes two types?"] = "メニューは料理名を値段に対応させる。2つの型を取るジェネリックは？",
  ["The merge pass is O(n); the sort before it makes the whole thing O(n log n)."] = "マージの一回通りは O(n)。その前のソートで全体は O(n log n)。",
  ["The method reads its own item. What is the first parameter of every method?"] = "メソッドが自分の item を読む。すべてのメソッドの最初の引数は？",
  ["The middle index without overflow. Fill: mid := lo + (hi-lo)/___"] = "オーバーフローしない中央インデックス。穴埋め: mid := lo + (hi-lo)/___",
  ["The midnight CODE RUSH is the Python round. Seven classic problems. Get HIRED."] = "深夜の CODE RUSH は Python ラウンド。古典問題が7つ。採用を勝ち取れ。",
  ["The mirror of the helper on the next line: n, then the superlative of big."] = "次の行のヘルパーの鏡: n、それから big の最上級。",
  ["The module name, singular, capitalized. Go's go keyword, as an object."] = "モジュール名の単数形、大文字始まり。Go の go キーワードを、オブジェクトとして。",
  ["The module's name, an underscore, and the side an equal item is inserted on: the left one here."] = "モジュール名、アンダースコア、そして等しい項目を挿入する側: ここでは左。",
  ["The module's name, capitalized. Not deque: that one has no locks."] = "モジュール名、大文字始まり。deque ではない: あれにはロックがない。",
  ["The module's name, singular, after the dot. It is a decorator, so it sits on the line above the class."] = "モジュール名の単数形、ドットの後。デコレータなので class の1行上に座る。",
  ["The module's own name in CamelCase, the two words joined."] = "モジュール自身の名前を CamelCase で、二語をつないだもの。",
  ["The module's own name, in double underscores. It is '__main__' only in the script you ran."] = "モジュール自身の名前を、前後にアンダースコア二つで。'__main__' になるのは、あなたが走らせたスクリプトの中だけだ。",
  ["The morning set"] = "モーニングセット",
  ["The multiplicative identity. Returning 0 would zero every factorial."] = "乗法の単位元です。0 を返すと階乗がすべて 0 になってしまいます。",
  ["The name imported on the first line. Since 3.10 you may write the type, a pipe, and None instead."] = "1行目でインポートした名前。3.10 からは型、パイプ、None と書いてもよい。",
  ["The name imported on the first line: a pool of threads that executes."] = "1行目でインポートした名前: 実行するスレッドのプール。",
  ["The name is a short string, so the argument you pickle is tiny no matter how large the block is. That is the whole trick."] = "名前は短い文字列なので、塊がどれだけ大きくても pickle する引数はごく小さい。仕掛けはそれだけだ。",
  ["The name saved on the first line of the loop, before the pointer was flipped. cur.next is no longer it."] = "ループの1行目で、ポインタを反転する前に保存した名前。cur.next はもうそれではない。",
  ["The name x, wrapped in the vertical bar character on both sides."] = "名前 x を、両側から縦棒の文字で包む。",
  ["The new sign says 銅鑼灣. The app counts it as nine letters."] = "新しい看板は 銅鑼灣。アプリは9文字と数えてる。",
  ["The next sheet is a stream: order totals arriving faster than anyone could sort them. Siu Ming wants the kth largest at any moment. Go has no heap type, only container/heap and an interface to satisfy. Alex writes IntHeap on the board, five methods, and a loop that never lets the heap grow past k."] = "次の紙はストリーム: 誰もソートしきれない速さで届く注文合計。シウミンはどの瞬間でも k 番目に大きい値が欲しい。Go にヒープ型はなく、container/heap と満たすべきインターフェースだけ。アレックスはボードに IntHeap、メソッド 5 つ、そしてヒープを k より大きくさせないループを書く。",
  ["The night shift at Lucky Mac runs on Chef Bo's Python scripts. Fix every station before closing."] = "ラッキーマックの夜勤はボーシェフの Python スクリプトで動く。閉店までに全部の持ち場を直せ。",
  ["The node that was before cur, saved on the first line. That is what reversing means."] = "cur の前にあったノード、1行目で保存したもの。それが反転するということ。",
  ["The node we just came from. nil on the first step, which becomes the new tail."] = "直前に通ったノード。最初の一歩では nil で、それが新しい末尾になります。",
  ["The note may be text or None. Which typing name says so?"] = "メモはテキストか None かもしれない。そう言う typing の名前は？",
  ["The number of columns: the length of one row, say the first."] = "列の数: 一行の長さ、たとえば最初の行。",
  ["The number of times you can halve n. Same answer as the phone book, applied to memory."] = "n を半分にできる回数。電話帳と同じ答えを、メモリに当てはめたもの。",
  ["The old position of this char, from the map lookup."] = "この文字の古い位置、map の検索結果から。",
  ["The one everybody gets asked, Chef. In Python the dict already remembers the order for you."] = "みんなが聞かれるやつよ、シェフ。Python では dict がもう順序を覚えてくれてる。",
  ["The opposite end from the front, where the untouched ones drift."] = "先頭の反対側の端、触られないものが流れ着く場所。",
  ["The opposite of Lock. defer it on the very next line."] = "Lock の反対。すぐ次の行で defer しましょう。",
  ["The opposite of held. Past participle, eight letters."] = "「握ったまま」の反対。過去分詞、八文字。",
  ["The opposite of insert, six letters. Takes a reference, returns whether it was there."] = "insert の反対、6文字。参照を受け取り、あったかどうかを返す。",
  ["The opposite of output. It shows the prompt and returns a str, always a str."] = "output の反対。プロンプトを表示し、str を返す。常に str。",
  ["The opposite of the -- below. Go's ++ is a statement, not an expression."] = "下の -- の逆。Go の ++ は文であり、式ではありません。",
  ["The order app"] = "注文アプリ",
  ["The order queue"] = "注文キュー",
  ["The order robot"] = "注文ロボット",
  ["The other child. max is a Go 1.21 built-in."] = "もう一方の子です。max は Go 1.21 の組み込み関数。",
  ["The other direction: struct to bytes. Same word without the De in front."] = "逆方向: 構造体からバイト列へ。頭の De を取った同じ単語。",
  ["The other half of Option. Not nil, not null. Four letters, capital N."] = "Option のもう片方。nil でも null でもない。大文字の N で始まる 4 文字。",
  ["The other variant of Option. Capital N, no parentheses."] = "Option のもう一方のバリアント。大文字の N、かっこなし。",
  ["The p >= l test matters: a repeat before the window's left edge is already outside and must not pull l back."] = "p >= l の判定が肝心: 窓の左端より前の重複はすでに外にあり、l を引き戻してはいけない。",
  ["The package function that removes the root and returns it."] = "根を取り除いて返すパッケージ関数。",
  ["The package that holds WaitGroup and Once, then the six-letter word for a lock."] = "WaitGroup と Once が入っているパッケージ、そしてロックを意味する六文字。",
  ["The package the Go tool looks for when you type go run."] = "go run と打ったときにGoツールが探すpackageです。",
  ["The parameter, the station already in seen on the line above."] = "引数、1行上ですでに seen に入っている駅。",
  ["The parent must not print the total before the child finishes. Which method?"] = "子が終わる前に親が合計を出してはいけない。どのメソッド？",
  ["The parse fails. Which method gives a fallback value instead of a panic?"] = "parse が失敗する。panic の代わりに代替値を返すメソッドは？",
  ["The part already flipped. None on the first lap, which becomes the new tail."] = "すでに反転し終えた側。最初の周では None で、それが新しい末尾になる。",
  ["The pass"] = "受け渡し口",
  ["The pass holds three trays; a fourth send should wait. Which constructor?"] = "パスに置けるトレイは 3 つ。4 つ目の send は待つべき。コンストラクタは？",
  ["The pass window"] = "パスの窓口",
  ["The pass window is a channel. One goroutine fries, another plates. Do not share the same variable; send the value through the pipe."] = "受け渡し口は channel です。1つの goroutine が揚げ、別のが盛り付ける。同じ変数を共有せず、値をパイプで送りましょう。",
  ["The pass window, 22:30. Chef Bo's recipe file is a list of functions: fry, brew, plate. Alex knows func; here it is three letters and a colon, and the body is whatever is indented under it."] = "パスの窓口、22:30。ボーシェフのレシピファイルは関数のリスト: fry、brew、plate。アレックスは func を知っている。ここでは3文字とコロン、本体はその下にインデントされたものすべて。",
  ["The pass, 21:00"] = "パス、21:00",
  ["The phone book"] = "電話帳",
  ["The phone book street's answer, without the O( ). Halving each step."] = "電話帳の街の答え、O( ) なしで。各ステップで半分に。",
  ["The phone calls the field dish, not Item. Fill the tag so json reads that key."] = "スマホはフィールドを Item ではなく dish と呼びます。json がそのキーを読むようタグを埋めてください。",
  ['The phone sends the price as text. Parse "18" into an int. Which strconv function?'] = 'スマホは価格をテキストで送ってきます。"18" を int に変換。strconv のどの関数？',
  ['The phone sends {"dish":"set"}. Our struct says Item. Nothing arrives.'] = 'スマホは {"dish":"set"} を送ってくる。うちの struct は Item。何も届かない。',
  ["The pickup bell is a select. Whichever channel is ready first wins. If none are ready, default fires instead of blocking the till."] = "呼び出しベルは select です。先に準備できた channel が勝ち。どれも準備できていなければ、レジをブロックせず default が動きます。",
  ["The pickup queue"] = "受け取りの行列",
  ["The pointer field, twice in a row. The while condition guards both hops."] = "ポインタのフィールド、2回続けて。while の条件が2回の跳躍を守る。",
  ["The pointer that walks the list. prev is the new head once it is nil."] = "リストを歩くポインタ。それが nil になったら prev が新しい先頭。",
  ["The pot is empty mid-loop. Which keyword leaves the loop at once?"] = "ループの途中で鍋が空になった。ループをすぐ抜けるキーワードは？",
  ["The prices are sorted. Find 45 in O(log n). Which slice method returns Result<usize, usize>?"] = "値段はソート済み。45 を O(log n) で見つける。Result<usize, usize> を返すスライスのメソッドは？",
  ["The queue"] = "行列",
  ["The queue at Lucky Mac Express"] = "ラッキーマック Express の行列",
  ["The queue begins with one station. Which one?"] = "キューは1つの駅から始まる。どれ？",
  ["The queue counter"] = "行列のカウンタ",
  ["The queue is a linked list. Reverse it without allocating, then find the loop."] = "キューは連結リスト。確保なしで反転し、ループを見つけて。",
  ["The queue is a struct of orders. A method with a pointer receiver can change the order. The till only knows the Pay() interface, not the card type."] = "行列は注文の struct。pointer レシーバのメソッドは注文を変えられる。レジは Pay() interface だけを知り、カードの型は知らない。",
  ["The queue outside the shutter. To total everyone's bill you visit each person once. Bo draws the diagonal, and reminds Alex that a built-in like sum hides the loop, not its cost."] = "シャッターの外の行列。全員の勘定を合計するには各人を一度訪ねる。ボーは対角線を描き、sum のような組み込みはループを隠すがコストは隠さないとアレックスに念を押す。",
  ["The queue outside the shutter. To total everyone's bill you visit each person once. Mei draws the diagonal again, and Alex writes it as an iterator chain instead of a loop."] = "シャッターの外の行列。全員の勘定を合計するには各人を一度訪ねる。メイはまた対角線を描き、アレックスはループの代わりにイテレータチェーンで書く。",
  ["The queue outside the shutter. To total the bill of everyone in it you visit each person once. Mei draws the second line on the whiteboard: a straight diagonal. Double the queue, double the work."] = "シャッターの外の行列。中の全員の勘定を合計するには、各人を一度訪ねる。メイはホワイトボードに2本目の線を描く: まっすぐな対角線。行列が倍なら仕事も倍。",
  ["The race detector watches real memory accesses, so it only sees races the run actually hits. Run your tests with it in CI."] = "レース検出器は実際のメモリアクセスを見るので、その実行が本当に踏んだレースしか見えない。CI ではこれを付けてテストを走らせよう。",
  ["The rack script lists trays. It drops the last one every time."] = "棚スクリプトがトレイを一覧にする。毎回最後の1つを落とすんだ。",
  ["The receipt borrows your name. It must not outlive you. That is all a lifetime says."] = "レシートは君の名前を借りてる。君より長生きしてはいけない。ライフタイムが言うのはそれだけ。",
  ["The recursive call must shrink the problem. Fill: n * fact(___)"] = "再帰呼び出しは問題を小さくしなければならない。埋めて: n * fact(___)",
  ["The recursive call must shrink the problem. Fill: return n * fact(___)"] = "再帰呼び出しは問題を小さくする必要があります。穴埋め: return n * fact(___)",
  ["The recursive flood written above, four letters. Takes &mut g and the cell."] = "上で書いた再帰の洪水、4文字。&mut g とセルを受け取る。",
  ["The refund desk"] = "返金カウンター",
  ["The repeat is gone: b[r] joins the window. Which HashSet method adds it?"] = "重複は消えた: b[r] が窓に加わる。追加する HashSet のメソッドは？",
  ["The repeat sits at p, inside the window. The window must restart just after it. Fill."] = "重複は窓の中の p にある。窓はそのすぐ後ろから始め直さねばならない。埋めよ。",
  ["The rest of the chain, or nothing at the end. Which type wraps Box<ListNode> so it can be empty?"] = "鎖の残り、または終端の何もなし。空になれるように Box<ListNode> を包む型は？",
  ['The rider app sends JSON with "dish", our struct says "name". serde can bridge it.'] = 'ライダーアプリは "dish" で JSON を送り、こちらの構造体は "name"。serde が橋渡しできる。',
  ["The rider app sends text. Parse it back into an Order. Which function?"] = "ライダーアプリがテキストを送ってくる。Order に戻す。どの関数？",
  ["The rider who gave up"] = "待つのをやめた配達員",
  ["The road value, as a one-character string. Sinking is the visited set for free."] = "道路の値、1文字の文字列で。沈めるのは無料の visited set。",
  ["The robot is a class. One Order per bowl. It forgot how to make itself."] = "ロボットはクラスだ。丼1杯に Order 1つ。自分の作り方を忘れてしまった。",
  ["The rooftop"] = "屋上",
  ["The root of a heap lives at the first index of the slice."] = "ヒープの根は slice の最初の添字にいる。",
  ["The root of every request tree. Fill: ctx := context.___()"] = "全リクエストツリーの根。埋めて：ctx := context.___()",
  ["The round opener, as a rune literal in single quotes."] = "丸い開きカッコ、シングルクォートの rune リテラルで。",
  ["The run so far with x added. If that is worse than x alone, the old run was dead weight."] = "これまでの連続に x を足したもの。それが x 単独より悪いなら、古い連続は重荷だった。",
  ["The safe"] = "金庫",
  ["The safe behind the till holds the stock file. The script opens it, writes, and forgets to close when a line is bad. Alex knows defer f.Close(); Python puts the whole idea into one keyword."] = "レジの裏の金庫に在庫ファイルがある。スクリプトはそれを開いて書き、行がおかしいと閉じるのを忘れる。アレックスは defer f.Close() を知っている。Python はその発想全体を1つのキーワードに入れた。",
  ["The same customer is in the queue list twice. Which built-in keeps each name once?"] = "同じ客が列のリストに2回いる。各名前を1回だけ残す組み込み関数は？",
  ["The same function the right side of the == already uses. It takes a string and returns a list of characters."] = "== の右側がすでに使っているのと同じ関数。文字列を受け取り、文字のリストを返す。",
  ["The same keyword as for slices, now on an int. No i := 0; i < 3; i++."] = "slice と同じキーワードを、今度は int に。i := 0; i < 3; i++ は不要。",
  ["The same mark that ends a question."] = "質問の終わりに付くのと同じ記号。",
  ["The same method that appends to any Vec. The top of the stack is the end of the Vec."] = "どの Vec にも末尾追加するあのメソッド。スタックの一番上は Vec の末尾。",
  ["The same shape as threading.Thread, one word, capitalised. What the operating system schedules."] = "threading.Thread と同じ形、一語、大文字始まり。OS がスケジュールするあれ。",
  ["The same trait String::from comes from. Capital F, one generic parameter."] = "String::from の出どころと同じトレイト。大文字の F、ジェネリック引数ひとつ。",
  ["The same word as a C-style counted loop."] = "C言語風のカウントループと同じ単語です。",
  ["The same word as in 'the ___ value of a struct is all fields blank'."] = "「struct の ___ 値は全フィールドが空」というときの、その語。",
  ["The same word as the blank import above. Go 1.16."] = "上のブランク import と同じ語。Go 1.16 から。",
  ["The same word as the builtin, capitalised, living in sync."] = "組み込みと同じ語を大文字始まりにして、sync の中に置いたもの。",
  ["The same word the till used to shut the drawer. It fires on the way out."] = "レジが引き出しを閉めるのに使ったのと同じ語。出ていく途中で走る。",
  ["The seating chart"] = "座席表",
  ["The seating chart for a banquet. Siu Ming's script checks every guest against every other for a duplicate. Bo draws the curve that leaves the board. Nested loops over the same list: the shape to avoid."] = "宴会の座席表。シウミンのスクリプトは重複を探して各客を他のすべての客と比べる。ボーはボードから出ていく曲線を描く。同じリストへの入れ子ループ: 避けるべき形。",
  ["The seating chart for a banquet. Siu Ming's script checks every guest against every other for a duplicate. Mei draws a curve that bends upward and leaves the board. Nested loops over the same list: the shape to avoid."] = "宴会の座席表。シウミンのスクリプトは重複を探して各客を他のすべての客と比べる。メイは上に曲がってボードから出ていく曲線を描く。同じリストへの入れ子ループ: 避けるべき形。",
  ["The seating chart for a banquet. Siu Ming's script checks every guest against every other for a duplicate. Mei draws the curve that leaves the board. Nested loops over the same Vec: the shape to avoid."] = "宴会の座席表。シウミンのスクリプトは重複を探して各客を他のすべての客と比べる。メイはボードから出ていく曲線を描く。同じ Vec への入れ子ループ: 避けるべき形。",
  ["The second argument holds the URL, method and body. Fill its type: r *http.___"] = "第2引数は URL、メソッド、ボディを持ちます。型を埋めてください: r *http.___",
  ["The second argument to make is the buffer size."] = "make の第2引数がバッファサイズです。",
  ["The second return value is not optional: not calling cancel leaks the context and whatever the parent holds for it."] = "二つ目の戻り値は省略可能ではない：cancel を呼ばないと context と、親がそのために抱えているものが漏れる。",
  ["The second value of the map lookup, the boolean that says the key was present."] = "map 検索の2つ目の値、キーが存在したと言う真偽値。",
  ["The sentinel is the poison pill. Go closes the channel once and every receiver wakes; Python has to send one pill per worker."] = "番兵は毒薬だ。Go は channel を一度閉じれば受信者全員が起きるが、Python はワーカーごとに一粒送らねばならない。",
  ["The set method that takes one element out; it raises KeyError if the element is missing."] = "要素を1つ取り出す set のメソッド。要素がなければ KeyError を投げる。",
  ["The seven-letter word from the second street of this quest."] = "このクエストの二番目の街に出てきた、七文字のあの語。",
  ["The shared till"] = "共有のレジ",
  ["The shared tray rack"] = "共用のトレイ棚",
  ["The shutter queue"] = "シャッター前の列",
  ["The side smaller values live on. The else branch already shows the other side."] = "小さい値が住む側。else 分岐がすでにもう一方を見せている。",
  ["The side the larger values live on, visited last."] = "大きい値が住む側、最後に訪れる。",
  ["The signboard"] = "看板",
  ["The slice built-in that grows. Mark visited when you enqueue, not when you pop."] = "slice を伸ばす組み込み関数。訪問済みにするのはエンキュー時、pop 時ではなく。",
  ["The smallest buffer that still holds something. One result, one slot."] = "それでも何か入る最小のバッファ。結果一つ、席一つ。",
  ["The sorting hat"] = "組分け帽子",
  ["The sorting hat: a shoebox of receipts. Alex sorts them by splitting the pile in half, again and again, then merging back in order. Bo draws the line between linear and quadratic and labels it n log n."] = "組分け帽子: レシートの靴箱。アレックスは山を半分に、また半分に分け、順番にマージして戻すことでソートする。ボーは線形と二次の間に線を描き、n log n と札を付ける。",
  ["The sorting hat: a shoebox of receipts. Alex sorts them by splitting the pile in half, again and again, then merging back in order. Mei draws the line between linear and quadratic and labels it n log n."] = "組分け帽子: レシートの靴箱。アレックスは山を半分に、また半分に分け、順番にマージして戻すことでソートする。メイは線形と二次の間に線を描き、n log n と札を付ける。",
  ["The sorting hat: a shoebox of the night's receipts. Alex sorts them by splitting the pile in half, again and again, then merging the piles back in order. Mei draws the line between linear and quadratic."] = "組分け帽子: 今夜のレシートの靴箱。アレックスは山を半分に、また半分に分け、山を順番にマージして戻すことでソートする。メイは線形と二次の間に線を描く。",
  ["The stamp desk"] = "スタンプデスク",
  ["The stamp desk. Bo wants every kitchen function timed and logged without touching its body. In Python a function is a value: wrap it in another and put the wrapper's name, with an @, on the line above."] = "スタンプデスク。ボーはすべてのキッチン関数の時間を計り、記録したい。本体には触れずに。Python では関数は値: 別の関数で包み、包む側の名前を @ 付きで1行上に置く。",
  ["The startup calls back. Seven whiteboard classics: stack, DP, window, heap, intervals, LRU, grid. Get the OFFER."] = "スタートアップからコールバック。ホワイトボードの古典 7 つ: スタック、DP、窓、ヒープ、区間、LRU、グリッド。OFFER を勝ち取れ。",
  ["The stock file is left open every night. Then the count is wrong in the morning."] = "在庫ファイルが毎晩開いたまま。それで朝の数が合わない。",
  ["The stock room"] = "倉庫",
  ["The stock room. A script counts eggs, trays and coffee beans, and it has been dividing with the wrong slash all year. Alex has typed := ten thousand times; here a plain = will do, and there is no type to write."] = "倉庫。スクリプトが卵、トレイ、コーヒー豆を数えるのだが、一年中間違ったスラッシュで割っていた。アレックスは := を一万回打ってきた。ここでは素の = でよく、書くべき型もない。",
  ["The stock script counts trays. It says we have 4.1666 trays of eggs. We do not."] = "在庫スクリプトがトレイを数える。卵が 4.1666 トレイあると言う。そんなわけない。",
  ["The storeroom"] = "倉庫",
  ["The storeroom is small. Sort the trays where they stand; do not build a second rack."] = "倉庫は狭い。トレイはその場でソートしろ。2つ目の棚は作るな。",
  ["The storeroom: every algorithm needs somewhere to put things. Sorting the trays where they stand costs no shelf; cloning them onto a new rack costs a rack the size of the input. Mei adds the second axis."] = "倉庫: すべてのアルゴリズムはものを置く場所が要る。トレイをその場でソートするなら棚は要らない。新しい棚に clone するなら入力と同じ大きさの棚が要る。メイは2本目の軸を加える。",
  ["The storeroom: every algorithm needs somewhere to put things. Sorting the trays where they stand costs no shelf; copying them onto a new rack costs a rack the size of the input. Mei adds the second axis to the board."] = "倉庫: すべてのアルゴリズムはものを置く場所が要る。トレイをその場でソートするなら棚は要らない。新しい棚にコピーするなら入力と同じ大きさの棚が要る。メイはボードに2本目の軸を加える。",
  ["The storeroom: every algorithm needs somewhere to put things. Sorting the trays where they stand costs no shelf; copying them onto a new rack costs a rack the size of the input. Mei adds the second axis to the last board of the night."] = "倉庫: すべてのアルゴリズムはものを置く場所が要る。トレイをその場でソートするなら棚は要らない。新しい棚にコピーするなら入力と同じ大きさの棚が要る。メイは今夜最後のボードに2本目の軸を加える。",
  ["The table starts with what is already known. One way to stand at the bottom, and how many ways to reach step 1?"] = "表はすでに分かっていることから始まる。一番下に立つのは1通り、では1段目に着くのは何通り？",
  ["The tea table"] = "ティーテーブル",
  ["The thread may outlive this scope. Which keyword gives the closure ownership of order?"] = "スレッドはこのスコープより長生きするかもしれない。クロージャに order の所有権を渡すキーワードは？",
  ["The three biggest prices, biggest first, in one call. Which heapq helper?"] = "上位3つの値段、大きい順、呼び出し1回で。どの heapq ヘルパー？",
  ["The ticket printer skips dish zero and prints dish five twice. Fix the loop."] = "伝票プリンタが0番の料理を飛ばして5番を2回印字する。ループを直そう。",
  ["The till"] = "レジ",
  ["The till returns (receipt, err). If err is not the zero value of error, stop. defer close() runs even if you return early."] = "レジは (receipt, err) を返します。err が error のゼロ値でなければ停止。defer close() は早期 return でも実行されます。",
  ["The till says Err and then just stops. Mei, does Rust not have nil?"] = "レジが Err って言ってそのまま止まる。メイ、Rust に nil はないの？",
  ['The till sends "12" as text. Which built-in turns it into a whole number?'] = 'レジは "12" をテキストで送ってくる。整数にする組み込み関数は？',
  ["The till thinks every order is a tuple. Give it a struct with names."] = "レジはどの注文もタプルだと思ってる。名前付きの struct をあげよう。",
  ["The trait behind {}. Debug is behind {:?}. You cannot derive this one."] = "{} の裏にいるトレイト。{:?} の裏は Debug。こちらは derive できない。",
  ["The tray is on the table. One last lesson: a request has a context so the kitchen can stop if the guest walks out. And a test so the next morning still compiles."] = "トレイがテーブルに。最後のレッスン：リクエストには context があり、客が帰れば厨房を止められる。そしてテストがあれば、明日の朝もコンパイルが通ります。",
  ["The tray rack"] = "トレイの棚",
  ["The tray rack. Bo's rack script keeps trays in a list and reads the last one with index len minus one, off by one, every night. Python has a shorter way to say 'last'."] = "トレイの棚。ボーの棚スクリプトはトレイをリストに入れ、最後のものを len 引く 1 のインデックスで読む。毎晩1つずれる。Python には「最後」をもっと短く言う方法がある。",
  ["The tray rail"] = "トレイレール",
  ["The tuple assignment does all three moves at once: Go evaluates the right side first."] = "タプル代入で 3 つの移動を一度に: Go は右辺を先に評価します。",
  ["The two seconds ran out. Which context error is that?"] = "二秒が尽きた。どの context エラー？",
  ["The type itself, used as a constructor. a[:] and a.copy() are the other two spellings."] = "型そのもの、コンストラクタとして使う。a[:] と a.copy() が他の2つの綴り。",
  ["The type name works as the conversion. Floor and int never mix silently."] = "型名がそのまま変換になります。Floor と int が暗黙に混ざることはありません。",
  ["The type name, inside the parentheses. The second line shows the safe two-value form."] = "括弧の中に型名。2行目は安全な2値の形です。",
  ["The type of [] itself, with the item type in square brackets. Older code imported a capitalized one from typing."] = "[] 自身の型、角括弧に要素の型。古いコードは typing から大文字版をインポートしていた。",
  ["The type of {} itself, lowercase, key type then value type inside the brackets."] = "{} 自身の型、小文字、角括弧の中はキーの型、それから値の型。",
  ["The type whose empty value the append needs. Passed as a callable, no parentheses."] = "append が必要とする空の値の型。呼び出し可能として渡す、括弧なし。",
  ["The typed-nil trap: return a plain nil error, never a nil *MyError."] = "型付き nil の罠: 素の nil error を返し、nil の *MyError は決して返さない。",
  ["The usual 'no answer' for a count: negative one."] = "個数に対するいつもの「答えなし」: マイナス 1。",
  ["The usual 'not found' number, which is why the return type is i64 and not usize."] = "いつもの「見つからない」の数。だから戻り値の型が usize ではなく i64。",
  ["The usual impossible marker: a negative one, since a real count is never below zero."] = "いつもの不可能マーカー: マイナス1。本当の枚数は 0 を下回らないから。",
  ["The value a function without return gives back, capital letter, used as the type here."] = "return のない関数が返す値、大文字始まり、ここでは型として使う。",
  ["The value of nothing, capital letter. Every function without a return statement gives it back."] = "「無」の値、大文字始まり。return 文のないすべての関数がこれを返す。",
  ["The walk stops when the runner falls off the end. Fill the condition: ___ != nil"] = "走査はランナーが末尾を越えたら止まる。条件を穴埋め: ___ != nil",
  ["The water byte. Same shape as the land literal, other digit."] = "水のバイト。陸のリテラルと同じ形で、もう一方の数字。",
  ["The web counter"] = "ウェブカウンター",
  ["The whiteboard again, the Rust column this time. Mei redraws the axes: n across, work up. First street: the operations whose line stays flat, written the Rust way."] = "またホワイトボード、今度は Rust の列。メイが軸を描き直す: 横に n、縦に仕事量。最初の街: 線が平らな操作を、Rust 流に書く。",
  ["The whiteboard in the back office, wiped clean. Mei draws one axis: n, the size of the input. The other axis is work. First street: operations whose line stays flat however far n goes."] = "バックオフィスのホワイトボード、きれいに消してある。メイが1本の軸を描く: n、入力の大きさ。もう1本の軸は仕事量。最初の街: n がどこまで行っても線が平らな操作。",
  ["The whiteboard one more time, the Python column. Chef Bo takes the marker: n across, work up. First street: the operations whose line stays flat, written the Python way."] = "ホワイトボードをもう一度、Python の列。ボーシェフがマーカーを取る: 横に n、縦に仕事量。最初の街: 線が平らな操作を、Python 流に書く。",
  ["The window is s[l..r], both ends included. Fill its length."] = "窓は s[l..r]、両端を含む。その長さを埋めよ。",
  ["The window is s[l:r+1]. Record its width if it is the widest yet. Fill the width."] = "窓は s[l:r+1]。これまでで最も広ければ幅を記録する。幅を埋めろ。",
  ["The with block closes and joins the pool for you. Without it, a forgotten pool keeps eight interpreters resident."] = "with ブロックが代わりに close と join をしてくれる。これがないと、忘れられたプールが八つのインタプリタを住まわせ続ける。",
  ["The word that follows an if block, here in the middle of one line. Python has no ? : operator."] = "if ブロックの後に来る単語、ここでは一行の真ん中に。Python に ? : 演算子はない。",
  ["The worker appended to my list and my list stayed empty. Every single time."] = "ワーカーが私のリストに append したのに、私のリストは空のまま。毎回そう。",
  ["The worker has to attach to the same block. Which attribute do you send it?"] = "ワーカーは同じ塊に接続しなければならない。どの属性を送る？",
  ["The workers want a real dict everyone can see. Which class serves one over a proxy?"] = "ワーカーたちは全員から見える本物の dict を欲しがっている。プロキシ越しに提供するクラスは？",
  ["The workshop"] = "作業場",
  ["The zero pointer. This is the base case of the tree recursion."] = "ゼロ値のポインタです。木の再帰のベースケース。",
  ["The zero value of a channel. Receiving on it blocks for ever, which select reads as 'never ready'."] = "channel のゼロ値。そこで受信すると永遠に止まり、select は「決して準備できない」と読む。",
  ["The zero value of a pointer, slice, map, chan, func, or error is ___."] = "pointer、slice、map、chan、func、error のゼロ値は ___ です。",
  ["There is exactly one way to stand still, and one way to take a single step."] = "じっとしている方法はちょうど1つ、1段だけ登る方法も1つ。",
  ["They asked me this one too. A stack, Bo. Every closer looks at the top."] = "私もこれを聞かれた。スタックよ、ボー。閉じ括弧はみんな先頭を見る。",
  ["They overlap: stretch the merged interval to whichever end is farther. Fill the builtin."] = "重なっている: マージ済み区間を遠い方の end まで伸ばす。builtin を埋めよ。",
  ["They overlap: the merged block ends at the later of the two ends. Which built-in?"] = "重なっている: マージしたブロックは2つの終わりの遅い方で終わる。どの組み込み？",
  ["They overlap: the merged block ends at the later of the two ends. Which method picks the larger end?"] = "重なっている: マージしたブロックは2つの終わりの遅い方で終わる。大きい方の終わりを選ぶメソッドは？",
  ["This cell is land and part of the island. Sink it before flooding onward, so it is never visited twice. What does the cell become?"] = "このセルは陸で島の一部。先へ流す前に沈めて、二度と訪れないように。セルは何になる？",
  ["This is the trap every threading programmer walks into once. Processes share nothing implicitly: results come back through a Queue, a return value, or shared memory."] = "スレッド育ちのプログラマが一度は落ちる罠だ。プロセスは暗黙には何も共有しない：結果は Queue か戻り値か共有メモリで返ってくる。",
  ["This scan is O(n): the honest cost of a VecDeque order. A doubly linked list with map-held nodes makes it O(1)."] = "この走査は O(n): VecDeque で順序を持つ正直な代償。マップがノードを持つ双方向連結リストなら O(1)。",
  ["Thread(target=fn, args=(...)) wraps a call. It is an OS thread, heavier than a goroutine, fine for I/O."] = "Thread(target=fn, args=(...)) は呼び出しを包む。OS スレッドで、goroutine より重いが、I/O には十分。",
  ["Threads"] = "スレッド",
  ["Threads and the GIL"] = "スレッドと GIL",
  ["Threads do help downloads. What happens to the GIL around a socket read?"] = "ダウンロードにはスレッドが効く。ソケットの読みの前後で GIL はどうなる？",
  ["Threads that borrow menu and are all joined before the block ends. Which function?"] = "menu を借用し、ブロックが終わる前に全部 join されるスレッド。関数は？",
  ["Three bowls left. If it says zero, we close."] = "残り3杯。ゼロと出たら閉店です。",
  ["Three cooks, one ticket rail, one lock on the rail. That is a worker pool."] = "料理人 3 人、伝票レール 1 本、レールにかける鍵 1 つ。それがワーカープール。",
  ["Three cooks, one ticket rail, one pass. That is a worker pool."] = "料理人 3 人、伝票レール 1 本、受け渡し口 1 つ。それが worker pool。",
  ["Three cooks, three OS threads. Which thread function runs a closure and returns a JoinHandle?"] = "料理人 3 人、OS スレッド 3 本。クロージャを走らせて JoinHandle を返す thread の関数は？",
  ["Three dots then the element type. Inside the function fares is a []int."] = "3つのドットのあとに要素の型。関数の中では fares は []int です。",
  ["Three letters for the chip, an underscore, then the verb for counting. os has the same one."] = "チップの三文字、アンダースコア、そして数えるという動詞。os にも同じものがある。",
  ["Three letters from Ord, the twin of the one that picks the smaller."] = "Ord の3文字、小さい方を選ぶやつの双子。",
  ["Three letters from Ord. A plain assignment of cur.1 would shrink a block that already reached further."] = "Ord の3文字。cur.1 をただ代入すると、もっと先まで届いていたブロックが縮む。",
  ["Three letters from Ord: the smaller of the current entry and the new candidate."] = "Ord の3文字: 今の項と新しい候補の小さい方。",
  ["Three letters in front of Lock, Go 1.18 and up. It attempts, it does not queue."] = "Lock の前に三文字、Go 1.18 以降。試すだけで、列には並ばない。",
  ["Three letters, O(1) itself: the slice header stores it."] = "3文字、それ自体は O(1): スライスヘッダが保持する。",
  ["Three letters, a method with parentheses. Go has the same word as a builtin."] = "3 文字、かっこ付きのメソッド。Go では同じ単語がビルトイン。",
  ["Three letters, a statement not a method. Go's delete(m, k), shortened."] = "3文字、メソッドではなく文。Go の delete(m, k) を短くしたもの。",
  ["Three letters, a verb: attempt it. The except below only makes sense after this."] = "3文字、動詞: やってみる。下の except はこれの後でしか意味を持たない。",
  ["Three letters, an underscore, and the four-letter word for a mutex."] = "三文字、アンダースコア、そして mutex を表す四文字。",
  ["Three letters, capital N. Takes the message, returns an error."] = "3文字、大文字の N。メッセージを受け取り、error を返します。",
  ["Three letters, from Ord. Its twin picks the larger one."] = "3文字、Ord のもの。双子の方は大きい方を選ぶ。",
  ["Three letters, from the Ord trait. a.max(b) reads better than std::cmp::max(a, b)."] = "3 文字、Ord トレイト由来。a.max(b) の方が std::cmp::max(a, b) より読みやすい。",
  ["Three letters, like the fastener that joins two sides tooth by tooth."] = "3文字、両側を歯ごとに噛み合わせる留め具のように。",
  ["Three letters, no underscore. The opposite of push. Returns Option<T>."] = "3 文字、アンダースコアなし。push の反対。Option<T> を返す。",
  ["Three letters, same as the module behind println!. Runs rustfmt."] = "3文字、println! の裏にいるモジュールと同じ。rustfmt を実行する。",
  ["Three letters, same name as on a Vec. It counts bytes, never characters."] = "3文字、Vec にあるのと同じ名前。数えるのはバイトで、文字ではない。",
  ["Three letters, short for buffer."] = "三文字、buffer の略。",
  ["Three letters, short for dynamic."] = "3 文字、dynamic の略。",
  ["Three letters, short for module. The same word as in go.mod."] = "3文字、module の略。go.mod と同じ語です。",
  ["Three letters, short for reverse. Only a DoubleEndedIterator has it, and Chars is one."] = "3 文字、reverse の略。DoubleEndedIterator だけが持っていて、Chars はその 1 つ。",
  ["Three letters, short for sequence. Seq2 yields pairs, like index and value."] = "3文字、sequence の略。Seq2 はインデックスと値のようなペアを yield します。",
  ["Three letters, the abbreviation everybody uses. It is a convention, not a rule the compiler knows."] = "三文字、みんなが使う略号。慣習であって、コンパイラが知る規則ではない。",
  ["Three letters, the math word for a collection with no duplicates. Go has no built-in one; map[T]bool stands in."] = "3文字、重複のない集まりを表す数学の単語。Go に組み込みはなく、map[T]bool で代用する。",
  ["Three letters, the name of the type itself. float() is its cousin."] = "3文字、型そのものの名前。float() はそのいとこ。",
  ["Three letters, the opposite of min. Built in; Go only got it in 1.21."] = "3文字、min の反対。組み込み。Go は 1.21 でようやく得た。",
  ["Three letters, the opposite of push. With no argument it takes the last item."] = "3文字、push の反対。引数なしなら最後の要素を取る。",
  ["Three letters, the opposite of put. Go's <-jobs."] = "3文字、put の反対。Go の <-jobs。",
  ["Three letters, the opposite of the last blank. None when the stack is already empty, and None != Some(open)."] = "3文字、前の空欄の反対。スタックがもう空なら None で、None != Some(open)。",
  ["Three letters, the opposite of the method a worker calls. Go's jobs <- order."] = "3文字、ワーカーが呼ぶメソッドの反対。Go の jobs <- order。",
  ["Three letters, the partner of Put."] = "三文字、Put の相棒。",
  ["Three letters, the partner of put. Pass timeout= if you would rather not wait for ever."] = "三文字、put の相棒。永遠に待ちたくなければ timeout= を渡そう。",
  ["Three letters, the plainest verb for starting a program. Once, at the top level."] = "3文字、プログラムを始める最も素朴な動詞。トップレベルで一度だけ。",
  ["Three letters, the same as Go. Not a method: it is a function that takes the list."] = "3文字、Go と同じ。メソッドではなく、リストを受け取る関数。",
  ["Three letters, the same builtin a slice uses for its capacity."] = "三文字、slice が容量に使うのと同じ組み込み。",
  ["Three letters, the same name as on a Vec, but here it returns the top of the heap in O(log k)."] = "3文字、Vec にあるのと同じ名前だが、ここではヒープの一番上を O(log k) で返す。",
  ["Three letters, the same name as the builtin it replaces."] = "三文字、置き換える組み込みと同じ名前。",
  ["Three letters, the start of 'define'. Go's func, Rust's fn."] = "3文字、'define' の頭。Go の func、Rust の fn。",
  ["Three letters, the text type's own name. An f-string would do the same without the call."] = "3文字、テキスト型自身の名前。f 文字列なら呼び出しなしで同じことができる。",
  ["Three letters. A slice of pairs would need a scan, O(n); this hashes the key instead."] = "3文字。組のスライスなら走査が必要で O(n)。これは代わりにキーをハッシュする。",
  ["Three letters. Bigger than any coin count, so the first real answer replaces it."] = "3文字。どんな枚数より大きいので、最初の本当の答えが置き換える。",
  ["Three letters. Capacity, not length."] = "3文字。長さではなく容量。",
  ["Three letters. Go has var and :=; Rust has one word for both."] = "3 文字。Go には var と := がある。Rust は 1 語で両方をまかなう。",
  ["Three letters. Heap pointer. dyn has no known size, so it must live behind one."] = "3文字。ヒープへのポインタ。dyn はサイズ不明なので、その裏に置く必要がある。",
  ["Three letters. Lists append; sets do this."] = "3文字。リストは append、set はこれ。",
  ["Three letters. Plus. Built into cargo since 1.62; remove is its opposite."] = "3文字。プラス。1.62 から cargo に内蔵。remove がその反対。",
  ["Three letters. Rust's word for Go's import, one path at a time."] = "3 文字。Go の import にあたる Rust の言葉、パスを 1 つずつ。",
  ["Three letters. Same word as Vec::new. Add --lib for a library instead."] = "3文字。Vec::new と同じ単語。ライブラリなら --lib を足す。",
  ["Three letters. Short for mutable, the opposite of the default."] = "3 文字。mutable (可変) の略、デフォルトの逆。",
  ["Three letters. Takes a reference to the key, returns Option<&V>."] = "3文字。キーへの参照を取り、Option<&V> を返す。",
  ["Three letters. Takes a reference to the key, returns Option<&V>. The &v pattern copies the u64 out."] = "3 文字。キーへの参照を取り、Option<&V> を返す。&v パターンで u64 を取り出してコピーする。",
  ["Three letters. The maths word for adding up. product() is its cousin."] = "3文字。足し合わせるという数学の単語。product() はその親戚。",
  ["Three letters. The owned heap pointer: one owner, freed when dropped. Not Rc, nobody shares a child."] = "3 文字。所有権を持つヒープのポインタ: 所有者は 1 人、drop されたら解放。Rc ではない。子を共有する者はいない。",
  ["Three letters. The type on the left, : i32, tells it what to produce."] = "3 文字。左側の型 : i32 が、何を作るかを教える。",
  ["Three letters. This is Python's await: the work started at apply_async."] = "三文字。これが Python の await だ：仕事は apply_async の時点でもう始まっている。",
  ["Three letters. Works anywhere; := only works inside a function."] = "3文字。どこでも使えます。:= は関数の中だけです。",
  ["Three letters. impl Trait ___ Type."] = "3 文字。impl Trait ___ Type。",
  ["Three letters. max is its twin. Both take any number of ordered values."] = "3文字。max はその双子。どちらも順序付き値をいくつでも受け取ります。",
  ["Three letters. menu[k] raises when k is missing; this one returns the default instead."] = "3文字。menu[k] は k がないと例外を投げる。これは代わりに既定値を返す。",
  ["Three letters: Atomic Reference Counted."] = "3 文字: Atomic Reference Counted。",
  ["Three letters: is there any element for which the closure is true. Vec::contains does the same for one value."] = "3文字: クロージャが真になる要素が1つでもあるか。Vec::contains は1つの値に対して同じことをする。",
  ["Three letters: to examine. ./... means this package and everything under it."] = "3文字: 検査する。./... はこのパッケージと配下すべてです。",
  ["Three letters; the loop calls .add on it. len(set(guests)) < len(guests) is the one-liner."] = "3文字。ループがそれに .add を呼ぶ。len(set(guests)) < len(guests) が一行版。",
  ["Three letters; the next line calls .add on it. Go's map[string]bool, Rust's HashSet."] = "3文字。次の行がそれに .add を呼ぶ。Go の map[string]bool、Rust の HashSet。",
  ["Three pairs, one match. '\\0' marks an opener; the rest of the loop branches on that."] = "3組で1つの match。'\\0' が開き括弧の印。ループの残りはそれで分岐する。",
  ["Three parts: ampersand, the mutability word, the receiver. o must be let mut to call it."] = "3 つの部品: アンパサンド、可変性の単語、レシーバ。呼ぶには o が let mut でなければならない。",
  ["Three riders, three radios. The script calls them one after another and the noodles go cold."] = "ライダー3人、無線3台。スクリプトが順番に呼ぶから麺が冷めるんです。",
  ["Three threads add to one counter. Which threading object guards it?"] = "3つのスレッドが1つのカウンタに足す。それを守る threading のオブジェクトは？",
  ["Three woks, one cook script. It fries one egg at a time while the other two woks sit cold."] = "中華鍋3つ、調理スクリプト1つ。卵を1つずつ焼き、残りの鍋2つは冷えたまま。",
  ["Three words in one: check the old value, then put the new one. Everyone calls it CAS."] = "三語で一つ：古い値を照合してから新しい値を置く。みんな CAS と呼ぶ。",
  ["Three words joined: what the operating system schedules, a pool of them, and the thing that runs your calls."] = "三語をつないだもの：OS がスケジュールするあれ、そのプール、そしてあなたの呼び出しを走らせるもの。",
  ["Three words with underscores: relocate the key to the back of the order."] = "アンダースコアつきの三語: キーを順序の後ろへ移す。",
  ["Three words with underscores: run, in, and the thing you built at the top of this street."] = "アンダースコアでつないだ三語：run、in、そしてこの街の最初に作ったもの。",
  ["Three words with underscores: sort, by, and the thing the closure returns."] = "アンダースコアでつないだ3語: sort、by、そしてクロージャが返すもの。",
  ["Three words, two underscores: skip, the verb for writing out, if. It names a predicate."] = "3単語、アンダースコア2つ: skip、書き出すという動詞、if。述語関数を指名する。",
  ["Throw away the bool, keep the error. What character discards?"] = "bool を捨てて error を残す。捨てる文字は？",
  ["Ticket five: the app needs a server. net/http is in the standard library: a handler is a function, a route is a string, the server is one call."] = "チケット5: アプリにはサーバが必要。net/http は標準ライブラリ: handler は関数、ルートは文字列、サーバは呼び出しひとつ。",
  ["Ticket four: orders arrive as JSON. The decoder only sees exported fields, and a tag on the field tells it which key to read."] = "チケット4: 注文は JSON で届きます。デコーダはエクスポートされたフィールドしか見ず、フィールドのタグがどのキーを読むか教えます。",
  ["Ticket one. The receipt cuts the shop name in half. Bytes, not characters."] = "チケット1。レシートが店名を真ん中で切っている。文字ではなくバイト。",
  ["Ticket seven, the rooftop. The app is live. Newer Go has generic helpers so the old hand-written loops can go: slices, maps, min, and iterators you can range over."] = "チケット7、屋上。アプリは稼働中。新しい Go にはジェネリックなヘルパーがあり、手書きの古いループは不要に: slices、maps、min、そして range できるイテレータ。",
  ["Ticket six: ship it. A module names the project, go.mod pins the dependencies, and the go tool formats, checks and builds. No Makefile needed."] = "チケット6: 出荷。module がプロジェクトを名付け、go.mod が依存を固定し、go ツールが整形・検査・ビルド。Makefile は不要です。",
  ["Ticket three: the menu board takes any. Before the app can print a price it must ask what is inside. Go asks with an assertion or a type switch."] = "チケット3: メニューボードは any を受け取ります。価格を表示する前に中身が何か確かめないと。Go ではアサーションか type switch で問います。",
  ["Ticket two: refunds. An error must say what went wrong, keep its cause, and let the caller ask which kind it was. All of that is in package errors."] = "チケット2: 返金。error は何が起きたかを伝え、原因を保持し、呼び出し側がどの種類か問えるべき。すべて errors パッケージにあります。",
  ["Tilde. Without it, type Cents int would not satisfy Number."] = "チルダ。これがないと type Cents int は Number を満たしません。",
  ["Time is one axis. Memory is the other. Every cache you loved tonight paid rent here."] = "時間が1本の軸。メモリがもう1本。今夜あなたが気に入った cache はみんな、ここで家賃を払っていたの。",
  ["Time is one axis. Memory is the other. Every memo you loved tonight paid rent here."] = "時間が1本の軸。メモリがもう1本。今夜あなたが気に入った memo はみんな、ここで家賃を払っていたの。",
  ["Time is one axis. Memory is the other. Rust makes you see every allocation; that is the point."] = "時間が1本の軸。メモリがもう1本。Rust はすべての確保を見せる。それが肝心なの。",
  ["Time the grill. Fill the prefix: func ___Grill(b *testing.B)"] = "グリルの時間を計る。接頭辞を埋めて：func ___Grill(b *testing.B)",
  ["Times Square"] = "タイムズスクエア",
  ["Times Square atrium"] = "タイムズスクエアのアトリウム",
  ["Times Square's LED cube is a slice of frames. An array has a fixed size in the type. A slice does not. append returns a (maybe new) slice."] = "タイムズスクエアのLEDキューブはフレームの slice。配列は型にサイズが固定されている。slice は違う。append は(新しいかもしれない) slice を返す。",
  ["Times Square's live coding show. Seven rounds of classic interview problems. Get HIRED."] = "タイムズスクエアのライブコーディングショー。古典的な面接問題を7ラウンド。採用を勝ち取れ。",
  ["To then Upper. Strings are immutable, so it returns a new one."] = "To のあとに Upper。string は不変なので、新しい string を返します。",
  ["Toast is off the menu tonight. Which statement removes the key?"] = "今夜トーストはメニューから外す。キーを消す文は？",
  ["Top k frequent dishes: count first. Which HashMap method gives a slot for w, creating it with 0 if new?"] = "頻出料理 top k: まず数える。w の枠を返し、新規なら 0 で作る HashMap のメソッドは？",
  ["Top k most ordered dishes. Count them, then take the k highest counts. Which Counter method?"] = "最も注文された上位 k の料理。数えて、上位 k の回数を取る。どの Counter メソッド？",
  ["Top-down instead: recurse, but remember every result. Which functools decorator?"] = "代わりにトップダウン: 再帰するが、結果はすべて覚える。どの functools デコレータ？",
  ["Traits"] = "トレイト",
  ["Tram or walk? if the light is green, we go."] = "トラムか徒歩か？ if 青信号なら、行く。",
  ["Tray::default() comes from the Default trait: 0 for numbers, empty String, empty Vec. Also ..Default::default() in struct literals."] = "Tray::default() は Default トレイトから来る: 数は 0、空の String、空の Vec。struct リテラルでは ..Default::default() も使える。",
  ["True only when nothing is left on the stack: compare its length with zero."] = "スタックに何も残っていないときだけ true: 長さをゼロと比べる。",
  ["True when the stack is empty. An empty list is falsy; negate it."] = "スタックが空なら True。空リストは偽。否定しろ。",
  ["TryLock is for work you can skip, not for dodging a design problem. If you reach for it often, the shared state is wrong."] = "TryLock は飛ばしてよい仕事のためのもので、設計上の問題をかわす道具ではない。よく使いたくなるなら、共有状態のほうが間違っている。",
  ["Turn an Option into a Result, with this message as the Err. Which method?"] = "Option を Result に変え、このメッセージを Err にする。メソッドは？",
  ["Turn land into water: the byte for water."] = "陸を水に変える: 水のバイト。",
  ["Turn the Order into JSON bytes. Fill: json.___(order)"] = "Order を JSON のバイト列に。埋めてください: json.___(order)",
  ["Turn the Order into a JSON String. Which serde_json function?"] = "Order を JSON の String にする。serde_json のどの関数？",
  ["Turn the lazy chain back into a Vec. Which method finishes it?"] = "遅延チェーンを Vec に戻す。締めるメソッドは？",
  ["Twelve letters. Things the project depends on. dev-... is the variant for tests only."] = "12文字。プロジェクトが依存するもの。dev-... はテスト専用の変種。",
  ["Twenty goroutines want the menu loaded; load it exactly once. Which method of sync.Once?"] = "二十の goroutine がメニューを読み込みたい。読み込むのはちょうど一度。sync.Once のどのメソッド？",
  ["Two ETAs at the same time, both results in one tuple. Which tokio macro?"] = "2つの ETA を同時に、結果は両方ひとつのタプルに。tokio のどのマクロ？",
  ["Two English words glued together: this and the thing you are deriving. Not anyhow."] = "英単語2つをくっつけたもの: this と、derive しているもの。anyhow ではない。",
  ["Two braces with nothing between. Note: this makes a dict, not a set; set() is spelled out."] = "中に何もない中括弧2つ。注意: これは dict を作る、set ではない。set は set() と書く。",
  ["Two braces with nothing inside. Not %d, not %v."] = "中身のない波かっこ 2 つ。%d でも %v でもない。",
  ["Two characters: the receive operator, in front of the channel."] = "記号二つ：受信演算子を channel の前に。",
  ["Two choices per topping, multiplied n times. Two, a caret, n."] = "トッピングごとに2つの選択、n 回掛ける。2、キャレット、n。",
  ["Two colons, then the type in angle brackets. It looks like a fish."] = "コロン 2 つ、続けて山かっこの中に型。魚に見える。",
  ["Two cooks increment the same tray count. Without a lock that is a race. WaitGroup.Add, Done, Wait is how the pass knows both items are ready."] = "2人のコックが同じトレイ数を増やす。ロックなしでは競合です。WaitGroup.Add、Done、Wait で受け渡し口は両方が揃ったと分かります。",
  ["Two dots and one more character that says the end counts too."] = "ドット2つと、終端も含むことを表す文字がもうひとつ。",
  ["Two dots, then the sign that says equal too."] = "ドット 2 つ、続けて「等しいも含む」の記号。",
  ["Two goroutines touching one variable, one of them writing, is a data race: go test -race finds it. Share by sending on a channel instead, or protect the reference. A plain map crashes under concurrent writes; sync.Map is built for it. Closing a channel publishes everything written before the close."] = "二つの goroutine が同じ変数に触れ、片方が書けばデータレースだ：go test -race が見つける。代わりに channel で送って共有するか、参照を守ること。素の map は同時書き込みでクラッシュし、sync.Map はそのために作られている。channel を閉じると、閉じる前に書いたものがすべて公開される。",
  ["Two hands, one tray counter. Lock it. Then wait for both cooks."] = "手は2つ、トレイのカウンタは1つ。ロックしろ。そして両方のコックを待て。",
  ["Two less than n. The base case handles 0 and 1, so this never goes negative."] = "n より2つ小さい。基底ケースが 0 と 1 を処理するので、これは負になることがない。",
  ["Two letters, the same name a map lookup and a type assertion use."] = "二文字、map の参照や型アサーションが使うのと同じ名前。",
  ["Two letters, the same word except and import use to bind a name."] = "2文字、except と import が名前を束縛するのに使うのと同じ単語。",
  ["Two letters, the same word import and with use to give something a local name."] = "2文字、import と with がローカルな名前を付けるのに使うのと同じ単語。",
  ["Two letters, the same word the for loop uses between the name and the list."] = "2文字、for ループが名前とリストの間に使うのと同じ単語。",
  ["Two letters, the shortest keyword in the language, and the name of the language."] = "二文字、この言語で一番短いキーワードであり、言語の名前でもある。",
  ["Two letters. == only checks the outer error; this unwraps."] = "2文字。== は外側の error しか見ません。こちらは unwrap します。",
  ["Two letters. Go's func with the middle taken out."] = "2 文字。Go の func から真ん中を抜いたもの。",
  ["Two letters. In Rust it is an expression, so it can sit after =."] = "2 文字。Rust では式なので、= の後ろに置ける。",
  ["Two letters. Is matches a value; this matches a type and fills the pointer."] = "2文字。Is は値で一致、こちらは型で一致してポインタを埋めます。",
  ["Two letters. Rust never converts numbers silently; you write the cast."] = "2 文字。Rust は数値を黙って変換しない。キャストは自分で書く。",
  ["Two letters. The other nineteen goroutines wait inside it until the first is finished."] = "二文字。残り十九の goroutine は最初の一つが終わるまでその中で待つ。",
  ["Two letters. The same word the for loop uses. Its cost depends entirely on the type on the right."] = "2文字。for ループが使うのと同じ単語。そのコストは右側の型に完全に依存する。",
  ["Two letters. Then a function call. The caller does not wait."] = "2文字。その後に関数呼び出し。呼び出し側は待ちません。",
  ["Two letters: the same object, not merely equal values. == would work here too, but this is the honest one."] = "2文字: 同じオブジェクト、ただ値が等しいのではなく。== もここでは動くが、こちらが正直なほう。",
  ["Two numbers that add up to target. Store value to index; for each x ask if target - x is already there. Which method?"] = "足して target になる 2 つの数。値からインデックスへ記録し、x ごとに target - x がもうあるか尋ねる。どのメソッド？",
  ["Two of the same character. One of them alone gives 4.1666, a float, every time."] = "同じ文字を2つ。1つだけなら毎回 4.1666、float になる。",
  ["Two packages in one file. What keyword opens the grouped list?"] = "1つのファイルに2つのpackage。まとめたリストを開くキーワードは？",
  ["Two pointers that only move right: O(n) time, O(alphabet) space. 'abcabcbb' gives 3."] = "右にしか動かない 2 つのポインタ: 時間 O(n)、空間 O(アルファベット)。'abcabcbb' は 3。",
  ["Two pointers walk inward from both ends. Fill the step: i, j = i+1, ___"] = "2 つのポインタが両端から内側へ。ステップを穴埋め: i, j = i+1, ___",
  ["Two pointers: O(n) time, O(1) extra space. Same trick for sorted-array pair sums."] = "2 ポインタ: 時間 O(n)、追加空間 O(1)。ソート済み配列のペア和にも同じ技。",
  ["Two processes, one conversation, no queue machinery. Which function?"] = "プロセス二つ、会話一つ、キューの仕掛けは要らない。どの関数？",
  ["Two runners: slow hops one node a lap, fast two. hop turns Option<Box<T>> into Option<&T>. Which method?"] = "走者は 2 人: slow は 1 周に 1 ノード、fast は 2 ノード進む。hop は Option<Box<T>> を Option<&T> にする。どのメソッド？",
  ["Two separate loops over the same n items, one after the other: O(n) + O(n) simplifies to O(___)"] = "同じ n 個に対する2つの別々のループ、順番に: O(n) + O(n) は O(___) に簡約される",
  ["Two separate passes over the same n items, one after the other: O(n) + O(n) simplifies to O(___)"] = "同じ n 個に対する2つの別々の走査、順番に: O(n) + O(n) は O(___) に簡約される",
  ["Two singles, or one double. Count them."] = "1 段が 2 回か、2 段が 1 回。数えよ。",
  ["Two slashes. A single one makes a float, and a[3.5] raises TypeError."] = "スラッシュ2本。1本だと float になり、a[3.5] は TypeError を投げる。",
  ["Two slashes. Same as Go, C and JavaScript."] = "スラッシュ 2 本。Go、C、JavaScript と同じ。",
  ["Two slashes: floor division. A single slash would make 3.5 and the slice would raise TypeError."] = "スラッシュ2本: 切り捨て除算。1本だと 3.5 になり、スライスが TypeError を投げる。",
  ["Two sorted lists, two pointers: O(n log n). rooms peaks at the answer and never has to come down."] = "ソート済みリスト 2 つ、ポインタ 2 つ: O(n log n)。rooms は答えでピークになり、下がる必要はない。",
  ["Two stars, then the name the body reads .items() from. Inside, it is a dict."] = "星2つ、そして本体が .items() を読む名前。中では dict。",
  ["Two stars. Go has no operator for this; Python and Rust's pow() do."] = "星2つ。Go にはこの演算子がない。Python にはあり、Rust は pow()。",
  ["Two steps below i. The loop starts at 2 so this index never goes negative."] = "i の2段下。ループは 2 から始まるのでこの添字は負にならない。",
  ["Two steps below i. The same shape as fib, without the recursion."] = "i の2段下。fib と同じ形、再帰なしで。",
  ["Two tills need two senders into the same pipe. Which method makes the second?"] = "レジ 2 台には同じパイプへの送信者が 2 つ必要。2 つ目を作るメソッドは？",
  ["Two tills, both adding to sold. At 12:04 the screen says 311, the drawer says 317."] = "レジ二台が同じ sold を増やしている。12:04、画面は 311、金庫は 317。",
  ["Two tills, one counter"] = "レジ二台、カウンタ一つ",
  ["Two tills, one kitchen. Orders pile up on my side and never arrive."] = "レジ 2 台、厨房 1 つ。注文はこっち側に積み上がって、向こうには届かない。",
  ["Two tills, six woks and forty riders touch the same numbers. Lock it, share it, cancel it. And find Go's await."] = "レジ二台、中華鍋六つ、配達員四十人が同じ数字に触れる。ロックし、共有し、キャンセルする。そして Go の await を見つけよう。",
  ["Two underscores, the name of the function above, two underscores. As a module the value would be the file name."] = "アンダースコア2つ、上の関数の名前、アンダースコア2つ。モジュールとしてならファイル名になる。",
  ["Two underscores, the start of initialize, two underscores. Dunder methods all look like this."] = "アンダースコア2つ、initialize の頭、アンダースコア2つ。dunder メソッドはみんなこの形。",
  ["Two words are anagrams if their letters, put in order, match. Which built-in orders them?"] = "2つの単語は、文字を並べ替えて一致すればアナグラム。それらを並べる組み込み関数は？",
  ["Two words glued: the verb you call to wait, and a thing you hold."] = "2 語をくっつけたもの: 待つために呼ぶ動詞と、手に持つもの。",
  ["Two words joined by an underscore: the ones that appear the most, the way people say it."] = "アンダースコアでつないだ二語: いちばんよく現れるもの、人がよく言う言い方で。",
  ["Two words joined, CapWords: stop, and the thing generators do. A for loop catches it silently."] = "2語を繋いだ CapWords: 止まる、そしてジェネレータがすること。for ループはこれを黙って捕まえる。",
  ["Two words joined, lowercase. The first parameter is spelled cls by convention."] = "2語を繋いだ小文字。最初の引数は慣例で cls と綴る。",
  ["Two words joined, lowercase: not moving, and what a def in a class is."] = "2語を繋いだ小文字: 動かない、そしてクラス内の def の呼び名。",
  ["Two words joined, lowercase: the thing a with statement needs, as one name."] = "2語を繋いだ小文字: with 文が必要とするもの、1つの名前として。",
  ["Two words joined, no underscore: how it left, as a number. None until it has."] = "二語をつないでアンダースコアなし：どう去ったかを数で。去るまでは None。",
  ["Two words with an underscore: as, then the past participle of complete."] = "アンダースコアでつないだ二語：as と、complete の過去分詞。",
  ["Two words with an underscore: make one of the things the loop schedules. tokio::spawn."] = "アンダースコア付きの2語: ループがスケジュールするものを1つ作る。tokio::spawn。",
  ["Two words with an underscore: the task, and the state it is now in."] = "アンダースコア付きの2語: タスク、そしてそれが今ある状態。",
  ["Two words with an underscore: the unit of work, then the past tense of finish."] = "アンダースコアでつないだ二語：仕事の単位と、終わったという語。",
  ["Two words, CamelCase: a dict with an order."] = "二語、CamelCase: 順序つきの dict。",
  ["Two words: the moment you promised, and what the clock did to it. The other one is Canceled."] = "二語：約束した時刻と、時計がそれにしたこと。もう一方は Canceled。",
  ["Two-sum in one pass: for each x, is target minus x already known? Which dict is checked?"] = "一回の走査での two-sum: 各 x について、target 引く x はすでに知っているか？ どの dict を調べる？",
  ["Two-sum on a sorted slice, no HashMap: i from the left, j from the right. The sum is too big: which way does j move?"] = "ソート済みスライスの two-sum、HashMap なし: i は左から、j は右から。和が大きすぎる: j はどちらへ動く？",
  ["Two-sum, anagrams, palindromes"] = "two-sum、アナグラム、回文",
  ["Two-sum, palindrome, anagram"] = "Two-sum、回文、アナグラム",
  ["Two-sum: a dict of seen values, one pass. Anagram: sorted(a) == sorted(b), or a Counter. Palindrome: two pointers from both ends."] = "two-sum: 見た値の dict、一回の走査。アナグラム: sorted(a) == sorted(b)、または Counter。回文: 両端からの2つのポインタ。",
  ["Type hints"] = "型ヒント",
  ["Type name, two colons, the method that copies a handle."] = "型名、コロン 2 つ、ハンドルを複製するメソッド。",
  ["Type parameters go in [T any]. Embedding promotes methods. A closure captures nearby names."] = "型パラメータは [T any] に書く。埋め込みはメソッドを昇格。closure は周囲の名前をキャプチャします。",
  ["Type the answer, then ENTER."] = "答えを入力して ENTER。",
  ["Un + Marshal. It needs a pointer so it can fill your variable."] = "Un + Marshal。変数を埋めるためにポインタが必要です。",
  ["Unchanged. That is the whole meaning of the 1 in O(1)."] = "不変。それが O(1) の 1 の意味のすべて。",
  ["Unexported fields are skipped silently. Capital letters or nothing."] = "非エクスポートのフィールドは黙ってスキップされます。大文字か、さもなくば無し。",
  ["Unknown shape from the rider app. Which serde_json type holds any JSON?"] = "ライダーアプリからの形が不明。どんな JSON でも持てる serde_json の型は？",
  ["Unmarshal(data, &v). Without & it decodes into a copy and you see nothing."] = "Unmarshal(data, &v)。& がないとコピーにデコードされ、何も見えません。",
  ["Unpack the Some or leave the function, no match block. Which keyword completes it?"] = "Some を取り出すか、関数を抜ける。match ブロックなし。補うキーワードは？",
  ["Unseen neighbours go to the back of the queue. Fill: queue = ___(queue, nb)"] = "未訪問の隣駅はキューの末尾へ。穴埋め: queue = ___(queue, nb)",
  ["Up, down, right, left. A dirs table {{1,0},{-1,0},{0,1},{0,-1}} is the same thing in a loop."] = "上、下、右、左。dirs 表 {{1,0},{-1,0},{0,1},{0,-1}} はループにした同じもの。",
  ["Valid means matched and closed. O(n) time, O(n) stack in the worst case: a string of openers."] = "有効とは、対応して閉じていること。時間 O(n)、最悪ケースはスタック O(n): 開きカッコだけの文字列。",
  ["Valid parentheses and a min stack"] = "括弧の検証と最小値スタック",
  ["Valid parentheses, min stack"] = "有効なカッコ、min stack",
  ["Value and Array are the small end of shared memory: a type code, a size, and a lock in the box. SharedMemory is the large end."] = "Value と Array は共有メモリの小さいほう：型コード、大きさ、そして箱の中のロック。SharedMemory が大きいほうだ。",
  ["Value ships with a lock so you do not invent one. Read, add, write is three steps here exactly as it was in Go."] = "Value にはロックが付いてくるので自分で作らなくてよい。読み・加算・書き込みの三段階なのは Go とまったく同じだ。",
  ["Variables need no type. int() and str() convert. // divides down, ** is power. None is no value."] = "変数に型は要らない。int() と str() で変換。// は切り捨て除算、** は累乗。None は値なし。",
  ["Variables, types, const"] = "変数、型、const",
  ["Vec grows with push. Arrays have a fixed length in the type. HashMap stores key to value; get returns Option."] = "Vec は push で伸びる。配列は型に固定長を持つ。HashMap はキーから値を保存し、get は Option を返す。",
  ["Vec plus Deque, a double-ended queue. A ring buffer: O(1) at both ends. Vec::remove(0) would be O(n)."] = "Vec に Deque を足した名前、両端キュー。リングバッファで両端 O(1)。Vec::remove(0) なら O(n) になる。",
  ["Vec, arrays and HashMap"] = "Vec、配列、HashMap",
  ["Vec::sort is a merge sort; sort_unstable is pattern-defeating quicksort. Both n log n."] = "Vec::sort はマージソート。sort_unstable はパターン打破クイックソート。どちらも n log n。",
  ["Vec<Box<dyn Cook>>: every Box is one pointer wide, so the Vec is happy. Dispatch happens at run time. The kiosk shows one list."] = "Vec<Box<dyn Cook>>: どの Box もポインタ 1 つ分の幅なので Vec は満足。ディスパッチは実行時。キオスクにリストが 1 つ表示される。",
  ["VecDeque::from([start]) seeds the queue. seen starts with start too, so it is never queued twice."] = "VecDeque::from([start]) がキューの最初の 1 つ。seen も start から始まるので、二度とキューに入らない。",
  ["WHAT ALEX LEARNED: Go basics.   PRIZE: the morning set."] = "アレックスが学んだこと: Goの基本。   ごほうび: モーニングセット。",
  ["WHAT ALEX LEARNED: Mutex and atomics, shared references, worker pools, pipelines, context, and that go plus a channel is await.   PRIZE: the SYNCED stamp."] = "アレックスが学んだこと：Mutex とアトミック、共有参照、ワーカープール、パイプライン、context、そして go に channel を足せばそれが await だということ。   賞品：SYNCED のスタンプ。",
  ["WHAT ALEX LEARNED: O(1) to O(2^n), and how to read a loop.   PRIZE: the O(1) stamp."] = "アレックスが学んだこと: O(1) から O(2^n) まで、そしてループの読み方。   賞品: O(1) スタンプ。",
  ["WHAT ALEX LEARNED: O(1) to O(2^n), maps beat loops, sort then search.   PRIZE: the O(1) stamp."] = "アレックスが学んだこと: O(1) から O(2^n) まで、map はループに勝つ、ソートしてから探索。   賞品: O(1) スタンプ。",
  ["WHAT ALEX LEARNED: Python basics, lists, dicts, classes.   PRIZE: the shutter comes down."] = "アレックスが学んだこと: Python の基礎、list、dict、class。   賞品: シャッターが下りる。",
  ["WHAT ALEX LEARNED: Result, traits, lifetimes, threads, Arc<Mutex>.   PRIZE: milk tea and a pineapple bun."] = "アレックスが学んだこと: Result、トレイト、ライフタイム、スレッド、Arc<Mutex>。   賞品: ミルクティーとパイナップルパン。",
  ["WHAT ALEX LEARNED: Rust basics, ownership.   PRIZE: the afternoon tea set."] = "アレックスが学んだこと: Rust の基本、所有権。   賞品: アフタヌーンティーセット。",
  ["WHAT ALEX LEARNED: String, errors, iterators, serde, async, cargo.   PRIZE: the service shipped."] = "アレックスが学んだこと: String、エラー、イテレータ、serde、async、cargo。   賞品: サービス公開。",
  ["WHAT ALEX LEARNED: exceptions, generators, decorators, with, asyncio, typing.   PRIZE: the midnight bowl."] = "アレックスが学んだこと: 例外、ジェネレータ、デコレータ、with、asyncio、型ヒント。   賞品: 深夜の一杯。",
  ["WHAT ALEX LEARNED: goroutines, channels, sync.   PRIZE: the morning set."] = "アレックスが学んだこと: goroutine、channel、sync。   ごほうび: モーニングセット。",
  ["WHAT ALEX LEARNED: recursion, trees, graphs, lists, sorting, hashing, workers.   PRIZE: HIRED."] = "アレックスが学んだこと: 再帰、木、グラフ、リスト、ソート、ハッシュ、ワーカー。   ごほうび: 採用。",
  ["WHAT ALEX LEARNED: stacks, DP, sliding windows, heaps, intervals, LRU, grid DFS.   PRIZE: the OFFER."] = "アレックスが学んだこと: スタック、DP、スライディングウィンドウ、ヒープ、区間、LRU、グリッド DFS。   ごほうび: OFFER。",
  ["WHAT ALEX LEARNED: strings, errors, JSON, HTTP.   PRIZE: the app is live."] = "アレックスが学んだこと: string、error、JSON、HTTP。   ごほうび: アプリ公開。",
  ["WHAT CHEF BO LEARNED: the GIL, Process and the main guard, Pool and chunksize, Queue and Pipe, locks and Value, shared_memory, ProcessPoolExecutor.   PRIZE: the SCALED stamp."] = "ボー料理長が学んだこと：GIL、Process と main ガード、Pool と chunksize、Queue と Pipe、ロックと Value、shared_memory、ProcessPoolExecutor。   賞品：SCALED のスタンプ。",
  ["WHAT CHEF BO SHOWED: list stacks, DP, windows, heapq, intervals, OrderedDict LRU, grid DFS.   PRIZE: the OFFER."] = "ボーシェフが見せたこと: list のスタック、DP、窓、heapq、区間、OrderedDict の LRU、グリッド DFS。   賞品: OFFER。",
  ["WHAT CHEF BO SHOWED: recursion, trees, graphs, lists, sorting, hashing, workers, in Python.   PRIZE: HIRED."] = "ボーシェフが見せたこと: 再帰、木、グラフ、リスト、ソート、ハッシュ、ワーカー、すべて Python で。   賞品: 採用。",
  ["WHAT MEI SHOWED: O(1) to O(2^n), HashMap beats Vec::contains, sort then binary_search.   PRIZE: the O(1) stamp."] = "メイが見せたこと: O(1) から O(2^n) まで、HashMap は Vec::contains に勝つ、ソートしてから binary_search。   賞品: O(1) スタンプ。",
  ["WHAT MEI SHOWED: Vec as a stack, DP tables, windows, BinaryHeap, intervals, an LRU, grid DFS.   PRIZE: the OFFER."] = "メイが見せたこと: スタックとしての Vec、DP 表、窓、BinaryHeap、区間、LRU、グリッド DFS。   賞品: OFFER。",
  ["WHAT MEI SHOWED: recursion, trees, graphs, lists, sorting, hashing, workers, in Rust.   PRIZE: HIRED."] = "メイが見せたこと: 再帰、木、グラフ、リスト、ソート、ハッシュ、ワーカー、すべて Rust で。   賞品: 採用。",
  ["WIND"] = "窓",
  ["Wait for all three woks before printing the receipt. Which method blocks until a thread is done?"] = "レシートを印字する前に3つの鍋を待つ。スレッドが終わるまでブロックするメソッドは？",
  ["Wait for every cook to finish before closing the kitchen. Which JoinHandle method blocks until the thread ends?"] = "厨房を閉める前に、料理人全員が終わるのを待つ。スレッドが終わるまでブロックする JoinHandle のメソッドは？",
  ["Wait for the tea thread and take its result. Which method?"] = "お茶のスレッドを待って結果を受け取る。メソッドは？",
  ["Wait on muffin or hash brown, whichever is ready. Which keyword?"] = "マフィンかハッシュブラウン、先に準備できた方を待つ。キーワードは？",
  ["Wait one second without freezing the loop. Which asyncio function, never time.sleep?"] = "ループを凍らせずに1秒待つ。どの asyncio 関数？ time.sleep は絶対に違う。",
  ["Wait then close(results) in a goroutine: the receiver's range ends cleanly. No leaks."] = "goroutine 内で Wait してから close(results): 受信側の range がきれいに終わる。リークなし。",
  ["Wait until both cooks call Done. Fill: var wg sync.___"] = "両方のコックが Done を呼ぶまで待つ。埋めて：var wg sync.___",
  ["WaitGroup.Add(n), Done(), Wait(). The tray leaves when n hits zero."] = "WaitGroup.Add(n)、Done()、Wait()。n がゼロになるとトレイが出ます。",
  ["Waiting on the network or burning the CPU: which word changes for CPU work?"] = "ネットワークを待つのか、CPU を燃やすのか：CPU 仕事ではどの語が変わる？",
  ["Waiting overlaps under the GIL; computing does not. That one sentence chooses the executor every time."] = "待ちは GIL の下でも重なるが、計算は重ならない。その一文が毎回 executor を選んでくれる。",
  ["Walk every cell. Each unsunk building starts a new island: sink it whole, then add one. Fill the operator."] = "全セルを歩く。沈んでいない建物ごとに新しい島が始まる: 丸ごと沈めて、1 を足す。演算子を埋めろ。",
  ["Walk every cell. Land that is still standing is a new island: count it and sink all of it. Which function does the sinking?"] = "全セルを歩く。まだ残っている陸は新しい島: 数えて全部沈める。沈めるのはどの関数？",
  ["Walk every shop name in a slice. Fill: for _, name := ___ shops"] = "slice の店名を全部たどる。埋める: for _, name := ___ shops",
  ["Walk from the flat to Lucky Mac. Fix every Go bug on the way."] = "家からラッキーマックまで歩く。道中の Go バグをすべて直す。",
  ["Walk names and quantities side by side. Which built-in pairs two lists?"] = "名前と数量を並べて歩く。2つのリストを組にする組み込み関数は？",
  ["Walk over a Vec by reference, no index. Which method starts the iterator?"] = "Vec を参照で歩く、インデックスなし。イテレータを始めるメソッドは？",
  ["Walk with Mei to Lucky Mac Express. Fix every Rust kiosk on the way."] = "メイと一緒にラッキーマック Express まで歩く。道中の Rust キオスクをすべて直す。",
  ["Walking by reference: no clone, no take, nothing moves. node is &Box<ListNode>, auto-deref reaches next."] = "参照で歩く: clone もなし、take もなし、何もムーブしない。node は &Box<ListNode> で、自動デリファレンスが next に届く。",
  ["Warm the grill exactly once, however many cooks call it. Fill: var once sync.___"] = "何人のコックが呼んでもグリルの予熱は一度だけ。埋めて：var once sync.___",
  ["Warm, fry and brew at once; stop all three on the first error. Which package?"] = "温めと揚げと茶を同時に。最初のエラーで三つとも止める。どのパッケージ？",
  ["Was the key there? The second result is a bool named ___."] = "キーはあった？ 2つ目の結果は ___ という名前の bool。",
  ["Water, or land already sunk, ends the flood. The grid holds bytes: which byte literal is land?"] = "水か、すでに沈めた陸なら洪水は終わり。グリッドはバイトを持つ: 陸のバイトリテラルは？",
  ["Ways to climb 0 steps and 1 step: one each. Fill the base cases."] = "0段と1段を登る方法: それぞれ1通り。基底ケースを埋めろ。",
  ["We already checked mid, so skip past it. hi = mid keeps the half-open rule."] = "mid は確認済みなので飛ばす。hi = mid で半開区間の規則を保ちます。",
  ["Welcome back, Alex. The callback is the whiteboard round. First: are these brackets balanced?"] = "おかえり、アレックス。コールバックはホワイトボードのラウンドだ。まずは: このカッコは釣り合っている？",
  ["Welcome to CODE RUSH! Round one: factorial, then fib without the exponential blowup. Buzzer's live!"] = "CODE RUSH へようこそ！第 1 ラウンド: 階乗、次は指数爆発しない fib。ブザー、オン！",
  ["What a channel does. The -ing form of the verb in the first half of the line."] = "channel がやっていること。行の前半の動詞の -ing 形。",
  ["What goes between the parameter list and the return type u32?"] = "引数リストと戻り値の型 u32 の間に入るものは？",
  ["What is __name__ equal to when the file is run directly, not imported?"] = "ファイルがインポートではなく直接実行されたとき、__name__ は何と等しい？",
  ["What is the lightweight thread go starts called?"] = "go が起動する軽量スレッドの名前は？",
  ["What is the three-letter name of the lock that lets one thread run bytecode at a time?"] = "一度に一つのスレッドだけがバイトコードを走らせる、そのロックの三文字の名前は？",
  ["Whatever opened last must close first. That sentence is a stack."] = "最後に開いたものが最初に閉じる。その一文がスタックそのもの。",
  ["When fast reaches the end, slow is halfway. One pass, no length count."] = "fast が末尾に着いたとき、slow は半分の位置。一回の走査、長さは数えない。",
  ["When fast runs out, slow stands in the middle. O(n) time, O(1) space, and Option<&T> is Copy so the hops are free. Combo x4."] = "fast が尽きたとき、slow は中央に立っている。時間 O(n)、空間 O(1)、Option<&T> は Copy なので跳躍はタダ。コンボ x4。",
  ["Where do cur and best start? Not at 0: a list of only losses still has a best hour."] = "cur と best はどこから始める？ 0 ではない: 損失だけのリストにも最良の1時間はある。",
  ["Where does a context go? Name the first parameter every Go API uses."] = "context はどこに置く？ どの Go API も使う第一引数の名前は？",
  ["Where is await?"] = "await はどこ？",
  ["Which Cargo.toml section lists the crates the project uses?"] = "プロジェクトが使うクレートを並べる Cargo.toml のセクションは？",
  ["Which Go type finds a price by name in O(1), on average?"] = "どの Go の型が名前から値段を平均 O(1) で見つける？",
  ["Which built-in reads a line typed at the terminal?"] = "ターミナルに打ち込まれた一行を読む組み込み関数は？",
  ["Which built-in tells you what kind of value price is?"] = "price がどんな種類の値か教えてくれる組み込み関数は？",
  ["Which built-in type finds a price by name in O(1), on average?"] = "どの組み込み型が名前から値段を平均 O(1) で見つける？",
  ["Which built-in writes a line to the terminal?"] = "ターミナルに一行を書く組み込み関数は？",
  ["Which keyword before def makes fetch a coroutine?"] = "def の前のどのキーワードが fetch をコルーチンにする？",
  ["Which keyword binds a name to a value in Rust?"] = "Rust で名前を値に束縛するキーワードは？",
  ["Which keyword brings HashMap from the standard library into this file?"] = "標準ライブラリの HashMap をこのファイルに持ち込むキーワードは？",
  ["Which keyword brings the time module in?"] = "time モジュールを持ち込むキーワードは？",
  ["Which keyword declares a function in Rust?"] = "Rust で関数を宣言するキーワードは？",
  ["Which keyword declares a set of methods that types can promise?"] = "型が約束できるメソッドの集まりを宣言するキーワードは？",
  ["Which keyword defines a new type?"] = "新しい型を定義するキーワードは？",
  ["Which keyword opens the block whose errors you want to catch?"] = "エラーを捕まえたいブロックを開くキーワードは？",
  ["Which keyword starts a function definition?"] = "関数定義を始めるキーワードは？",
  ["Which letter before the quote lets {n} be replaced by the value of n?"] = "引用符の前のどの文字が {n} を n の値に置き換える？",
  ["Which method returns 9 for the three characters of 銅鑼灣?"] = "銅鑼灣 の3文字に対して 9 を返すメソッドは？",
  ["Which operator raises 2 to the tenth power?"] = "2 の 10 乗を求める演算子は？",
  ["Which placeholder inside the string prints the value of n?"] = "文字列の中で n の値を出力するプレースホルダーは？",
  ["Which special method runs when Order('noodles') is created?"] = "Order('noodles') が生成されたとき、どの特殊メソッドが走る？",
  ["Which standard library module gives real parallelism for CPU work?"] = "CPU 仕事に本物の並列をくれる標準ライブラリのモジュールは？",
  ["Which standard package prints to the terminal?"] = "ターミナルに出力する標準packageはどれですか？",
  ["Which std collection finds a price by name in O(1), on average?"] = "どの std コレクションが名前から値段を平均 O(1) で見つける？",
  ["Which std trait, with an empty body, makes OrderError a real error?"] = "空の本体で OrderError を本物のエラーにする std のトレイトは？",
  ["Why do four threads not make four times the arithmetic? Name the lock, three letters."] = "なぜ4スレッドで計算が4倍にならない？ そのロックの名前を、3文字で。",
  ["Why does a second process escape the lock? Each one has its own ___."] = "なぜ二つ目のプロセスはこのロックから逃れられる？ それぞれが自分の ___ を持つからだ。",
  ["Why threads do not go faster"] = "なぜスレッドでは速くならないのか",
  ["With a JoinableQueue the parent waits for the work, not the workers. Which call acknowledges one item?"] = "JoinableQueue では親はワーカーではなく仕事を待つ。一件の完了を知らせる呼び出しは？",
  ["With a cache every fib(k) is computed once. The cost drops to O(___)"] = "cache があれば各 fib(k) は一度だけ計算される。コストは O(___) に下がる",
  ["With a memo every fib(k) is computed once. The cost drops to O(___)"] = "memo があれば各 fib(k) は一度だけ計算される。コストは O(___) に下がる",
  ["With cap 1 the sender finishes even if the context won the select. With an unbuffered channel that goroutine would block for ever: a leak."] = "容量 1 なら、select で context が勝っても送り手は走り終える。バッファなしだとその goroutine は永遠に止まる：リークだ。",
  ["With, then a duration word. The twin that takes a time.Time is WithDeadline."] = "With に、時間の長さを表す語。time.Time を取る双子は WithDeadline。",
  ["With, then the verb for stopping. Its siblings are WithTimeout and WithDeadline."] = "With に、止めることを表す動詞。兄弟は WithTimeout と WithDeadline。",
  ["With, then the word for a time limit. WithDeadline takes a clock time instead."] = "With の後に制限時間を表す単語。WithDeadline は代わりに時刻を取ります。",
  ["With, then the word for what is stored. The key is a private type so nobody can collide with it."] = "With に、しまわれるものを表す語。キーは私有の型なので誰ともぶつからない。",
  ["WithTimeout returns a child that cancels itself. Always defer cancel() or you leak."] = "WithTimeout は自らキャンセルする子を返します。必ず defer cancel() を、さもないとリークします。",
  ["WithValue is for request-scoped data that crosses API boundaries: a trace id, not the parameters of your function."] = "WithValue は API 境界をまたぐリクエスト単位のデータのためのもの：trace id はよいが、あなたの関数の引数はだめだ。",
  ["Without a with block, what must always follow acquire()?"] = "with ブロックを使わないなら、acquire() のあとに必ず何が続く？",
  ["Without the guard, spawn re-imports the file, the import starts another Process, and that is the fork bomb you just wrote by accident."] = "ガードがないと spawn がファイルを import し直し、その import がまた Process を起動する。それがうっかり書いてしまった fork 爆弾だ。",
  ["Without with, which method must you remember to call on the file?"] = "with なしなら、ファイルに対してどのメソッドを呼ぶのを忘れてはいけない？",
  ["Word count. New word: start at 0. Seen word: bump it. One entry call does both. Fill: entry(w).___(0)"] = "単語数。新しい単語なら 0 から。見たことがある単語なら増やす。entry の呼び出し 1 つで両方できる。埋めて: entry(w).___(0)",
  ["Worker pool and pipeline"] = "worker pool とパイプライン",
  ["Worker pool with threads"] = "スレッドによるワーカープール",
  ["Worker pool: N goroutines range over a jobs channel; close(jobs) ends them; WaitGroup then close(results)."] = "worker pool: N 個の goroutine が jobs channel を range; close(jobs) で終了; WaitGroup の後 close(results)。",
  ["Worker pool: an mpsc channel of jobs, the Receiver in Arc<Mutex<>>, N thread::spawn workers looping on recv. drop(tx) ends them, join waits."] = "ワーカープール: ジョブを流す mpsc チャネル、Arc<Mutex<>> に入れた Receiver、recv をループする N 個の thread::spawn ワーカー。drop(tx) で終わらせ、join で待つ。",
  ["Worker pools and how many to start"] = "ワーカープールと何個立てるか",
  ["Workers are identical goroutines sharing one input channel. The channel is the queue."] = "worker は 1 つの入力 channel を共有する同一の goroutine。channel がキューです。",
  ["Works on slices, strings, maps, channels. cap is the capacity."] = "slice、string、map、channel に使えます。cap は容量です。",
  ["Wrap the bytes as an array without copying them. Which attribute is the memoryview?"] = "コピーせずにバイト列を配列として包む。memoryview である属性は？",
  ["Write the reply into w, not the terminal. Which fmt function?"] = "返信をターミナルではなく w に書きます。fmt のどの関数？",
  ["You did tokio this afternoon. asyncio is the same shape: one loop, many awaits."] = "今日の午後 tokio をやったでしょ。asyncio も同じ形: ループ1つ、await たくさん。",
  ["You got HIRED at seven. This is the OFFER round. A stack, Mei, it's always a stack."] = "7時に HIRED を取った。これは OFFER ラウンド。スタックだ、メイ、いつだってスタック。",
  ["You only need a bool: is the order in one of two states? Which macro?"] = "欲しいのは bool だけ: 注文は2つの状態のどちらかにあるか？ どのマクロ？",
  ["You reach step i from one below or two below. Fill the second term: dp[i - 1] + dp[___]"] = "段 i には1つ下か2つ下から着く。第2項を埋めろ: dp[i - 1] + dp[___]",
  ["You reach step i from one step below or two steps below. Fill the second index."] = "i 段目には1段下か2段下から着く。2つ目の添字を埋めろ。",
  ["You still want the position of every dish on the ticket. Which adapter adds it?"] = "伝票の各料理の位置はやはり欲しい。それを足すアダプタは？",
  ["Your workers each pickled two gigabytes of the same table. That is the whole runtime, right there."] = "ワーカーがそれぞれ同じ 2 ギガの表を pickle していたのよ。実行時間の正体はそこ。",
  ["[0i32; 26] lives on the stack: no HashMap, no allocation. Add for a, subtract for b, all zero means anagram."] = "[0i32; 26] はスタックに置かれる: HashMap もなし、確保もなし。a で足し、b で引き、全部ゼロならアナグラム。",
  ["[1,6] absorbs [2,4]: without the larger-end rule you would shrink it to [1,4]. last is a slice, so out sees the change."] = "[1,6] は [2,4] を飲み込む: 大きい end の規則がなければ [1,4] に縮んでしまう。last は slice なので out にも変更が見える。",
  ["[3]string is an array: a value, fixed length, copied on assignment. []string is a slice."] = "[3]string は配列: 値型、固定長、代入でコピー。[]string は slice。",
  ["[T any] is the widest constraint. comparable is for map keys."] = "[T any] が最も広い制約。comparable は map のキー用です。",
  ["[[9, 11], [10, 12], [13, 15]] becomes [[9, 12], [13, 15]]. Sort plus one pass: O(n log n)."] = "[[9, 11], [10, 12], [13, 15]] は [[9, 12], [13, 15]] になる。ソートと一回の走査: O(n log n)。",
  ["[]int is a slice. [3]int is an array of three. Slices are what you use."] = "[]int は slice。[3]int は要素3つの配列。普段使うのは slice です。",
  ["[]rune(s) once, then index freely. Interviewers check this in Go."] = "[]rune(s) を一度、あとは自由にインデックス。Go の面接で必ず見られます。",
  ["[dependencies] asks for versions; Cargo.lock records the exact ones. Commit the lock for binaries."] = "[dependencies] はバージョンを要求し、Cargo.lock は正確な値を記録する。バイナリなら lock をコミットする。",
  ["[expr for x in xs if cond] is a list comprehension. Rust's iter().map().collect(), in one readable line."] = "[expr for x in xs if cond] はリスト内包表記。Rust の iter().map().collect() を、読みやすい一行に。",
  ["[i32; 3] lives on the stack and never grows. Vec is for lists that change size."] = "[i32; 3] はスタック上にあり、決して伸びない。サイズが変わるリストには Vec。",
  ['[package]\nname = "delivery"\nedition = "2021"\n\n[___]\nserde = { version = "1", features = ["derive"] }\ntokio = { version = "1", features = ["full"] }\n'] = '[package]\nname = "delivery"\nedition = "2021"\n\n[___]\nserde = { version = "1", features = ["derive"] }\ntokio = { version = "1", features = ["full"] }\n',
  ["_ matches anything and binds nothing. Without it the match is not exhaustive and will not compile. The gate shows set."] = "_ は何にでもマッチし、何も束縛しない。これがないと match は網羅的でなくコンパイルできない。ゲートに set が表示される。",
  ["_ means I know this exists and I am ignoring it on purpose."] = "_ は「存在は知っているが、わざと無視する」という意味です。",
  ['___ OPEN: u8 = 7;        // hour the Express opens\n\nfn main() {\n    println!("opens at {}", OPEN);\n}\n'] = '___ OPEN: u8 = 7;        // Express が開く時刻\n\nfn main() {\n    println!("opens at {}", OPEN);\n}\n',
  ['___ Order {\n    item: String,\n    qty: u32,\n}\nlet o = Order { item: "muffin".to_string(), qty: 2 };\n'] = '___ Order {\n    item: String,\n    qty: u32,\n}\nlet o = Order { item: "muffin".to_string(), qty: 2 };\n',
  ["___ Order:\n    pass\n\no = Order()\n"] = "___ Order:\n    pass\n\no = Order()\n",
  ["___ Size { Small, Large }\n\nlet size = Size::Large;\nlet extra = match size {\n    Size::Small => 0,\n    Size::Large => 5,       // every variant handled\n};\n"] = "___ Size { Small, Large }\n\nlet size = Size::Large;\nlet extra = match size {\n    Size::Small => 0,\n    Size::Large => 5,       // すべてのバリアントを処理\n};\n",
  ['___ fry("hashbrown")\n___ toast("muffin")\n'] = '___ fry("hashbrown")\n___ toast("muffin")\n',
  ['___ fry(item):\n    print("frying", item)\n\nfry("egg")\n'] = '___ fry(item):\n    print("frying", item)\n\nfry("egg")\n',
  ['___ greet() {\n    println!("welcome to Lucky Mac Express");\n}\n// no arrow: this one returns the unit type ()\n'] = '___ greet() {\n    println!("welcome to Lucky Mac Express");\n}\n// 矢印なし: これは unit 型 () を返す\n',
  ["___ luckymac/delivery\n\ngo 1.22\n\nrequire github.com/lib/pq v1.10.9\n"] = "___ luckymac/delivery\n\ngo 1.22\n\nrequire github.com/lib/pq v1.10.9\n",
  ['___ night shift starts at 21:00\nprint("open")\n'] = '___ 夜勤は 21:00 に始まる\nprint("open")\n',
  ['___ open("stock.csv") as f:\n    for line in f:\n        count(line)\n# f is closed here\n'] = '___ open("stock.csv") as f:\n    for line in f:\n        count(line)\n# ここで f は閉じている\n',
  ['___ queue:\n    person = queue.pop(0)\n    print("bowl for", person)\n'] = '___ queue:\n    person = queue.pop(0)\n    print("bowl for", person)\n',
  ['___ std::collections::HashMap;\n\nfn main() {\n    let mut stock = HashMap::new();\n    stock.insert("muffin", 4);\n}\n'] = '___ std::collections::HashMap;\n\nfn main() {\n    let mut stock = HashMap::new();\n    stock.insert("muffin", 4);\n}\n',
  ["___ tap(card string) bool {\n    return true\n}\n"] = "___ tap(card string) bool {\n    return true\n}\n",
  ['___ time\ntime.sleep(1)     # let the wok heat\nprint("ready")\n'] = '___ time\ntime.sleep(1)     # 中華鍋を温める\nprint("ready")\n',
  ["___ {\ncase m := <-muffin:\n    serve(m)\ncase h := <-hash:\n    serve(h)\n}\n"] = "___ {\ncase m := <-muffin:\n    serve(m)\ncase h := <-hash:\n    serve(h)\n}\n",
  ['___("Lucky Mac night shift")\n'] = '___("Lucky Mac night shift")\n',
  ["___(ch)\nx, ok := <-ch          // ok is false after\n"] = "___(ch)\nx, ok := <-ch          // その後 ok は false\n",
  ["___(floors)                  // len(floors) == 0 after\n"] = "___(floors)                  // 実行後 len(floors) == 0\n",
  ['___(prices, "closed")\n'] = '___(prices, "closed")\n',
  ['___, err := tap("octopus")\n'] = '___, err := tap("octopus")\n',
  ["___:\n    qty = int(raw)\nexcept ValueError:\n    qty = 0\n"] = "___:\n    qty = int(raw)\nexcept ValueError:\n    qty = 0\n",
  ['___timer\ndef fry(item):\n    return f"fried {item}"\n'] = '___timer\ndef fry(item):\n    return f"fried {item}"\n',
  ["__enter__ runs at the with line. Return self or the resource. Rust would use Drop for the other half."] = "__enter__ は with の行で走る。self かリソースを返す。Rust なら残り半分に Drop を使う。",
  ["__exit__(self, exc_type, exc, tb) always runs. Return True to swallow the exception; return None to let it propagate."] = "__exit__(self, exc_type, exc, tb) は常に走る。True を返せば例外を飲み込み、None を返せば伝播させる。",
  ["__init__ is the constructor body; self.item = item makes an attribute. __new__ exists too, rarely needed."] = "__init__ はコンストラクタの本体。self.item = item が属性を作る。__new__ もあるが、めったに要らない。",
  ["__str__ is what print and str() use; __repr__ is the unambiguous form, used when __str__ is missing. Go's String()."] = "__str__ は print と str() が使う。__repr__ は曖昧さのない形式で、__str__ がないときに使われる。Go の String()。",
  ["a + b with no semicolon is the value of the block. Go coders write return; Rust coders usually do not."] = "セミコロンのない a + b がブロックの値。Go 使いは return を書くが、Rust 使いはふつう書かない。",
  ["a := []int{1, 2, 3}\nb := a[:2]\nb[0] = 9\nfmt.Println(a[0])       // prints ___\n"] = "a := []int{1, 2, 3}\nb := a[:2]\nb[0] = 9\nfmt.Println(a[0])       // ___ を出力\n",
  ["a if cond else b reads left to right like English. The shutter sign flips to 'closed' at the last bowl."] = "a if cond else b は英語のように左から右に読める。最後の一杯でシャッターの看板が 'closed' に変わる。",
  ["a lesson you can carry in a photo album"] = "フォトアルバムに入れて持ち歩けるレッスン",
  ["a to z. The array length is part of the type, so it must be a constant."] = "a から z まで。配列の長さは型の一部なので、定数でなければならない。",
  ["a.clone() allocates a second buffer. Cheap types derive Copy instead and never need it."] = "a.clone() は 2 つ目のバッファを確保する。軽い型は代わりに Copy を derive し、これを必要としない。",
  ["a.clone(). Allocation is where space complexity is paid; drop frees it at the end of scope, no collector needed."] = "a.clone()。確保が空間複雑度を支払う場所。drop がスコープの終わりで解放する。コレクタは要らない。",
  ["a.sort()                              # once: n log n\nfor x in queries:\n    i = bisect.bisect_left(a, x)      # each: O(___)\n"] = "a.sort()                              # 一度: n log n\nfor x in queries:\n    i = bisect.bisect_left(a, x)      # 各回: O(___)\n",
  ["a.sort()    # in place: O(___) extra space (Timsort's small buffer aside)\n"] = "a.sort()    # その場: O(___) の追加空間 (Timsort の小さなバッファは別として)\n",
  ["a.sort() sorts the list where it is. Extra memory, in Big O: O(___)"] = "a.sort() はリストをその場でソートする。追加のメモリは Big O で: O(___)",
  ["a.sort();                                  // once: n log n\nfor x in &queries {\n    let hit = a.binary_search(x).is_ok();  // each: O(___)\n}\n"] = "a.sort();                                  // 一度: n log n\nfor x in &queries {\n    let hit = a.binary_search(x).is_ok();  // 各回: O(___)\n}\n",
  ["a.sort_unstable();    // in place: O(___) extra space\n"] = "a.sort_unstable();    // その場: O(___) の追加空間\n",
  ["a[-1] is the last item, a[-2] the one before. Bo's off-by-one is gone."] = "a[-1] は最後の要素、a[-2] はその前。ボーの1つずれが消えた。",
  ["a[1:3] copies items 1 and 2 into a new list. a[:2], a[2:], a[::2] and a[::-1] (reversed) all work."] = "a[1:3] は項目 1 と 2 を新しいリストにコピーする。a[:2]、a[2:]、a[::2]、a[::-1]（逆順）もすべて使える。",
  ["a[mid] is too small: the answer is to the right. Fill: lo = ___ + 1"] = "a[mid] が小さすぎる: 答えは右側。穴埋め: lo = ___ + 1",
  ["add changes qty. Which receiver borrows the order with write access?"] = "add は qty を変える。書き込みアクセス付きで注文を借用するレシーバは？",
  ["amounts.___();     // pdqsort, no scratch buffer, O(n log n)\n"] = "amounts.___();     // pdqsort、作業バッファなし、O(n log n)\n",
  ["amounts.sort();    // ___ : stable merge sort\n"] = "amounts.sort();    // ___ : 安定なマージソート\n",
  ["append is amortized O(1). Python has no stack class; a list is the stack."] = "append は償却 O(1)。Python にスタッククラスはない。リストがスタックだ。",
  ["apply_async returned a handle. Which method waits for the value?"] = "apply_async がハンドルを返した。値を待つメソッドは？",
  ["arr writes straight into the shared block, so every process sees the change with no send at all. This is how big NumPy jobs go parallel."] = "arr は共有の塊へ直接書くので、送信ゼロで全プロセスが変更を見る。大きな NumPy の仕事はこうして並列になる。",
  ["arrows walk   ESC map"] = "矢印 移動   ESC 地図",
  ["as f binds what __enter__ returned. with a() as x, b() as y: manages two at once."] = "as f は __enter__ が返したものを束縛する。with a() as x, b() as y: で2つ同時に管理する。",
  ["as usize widens the u8 for free. A u8 index would not compile: Rust never converts integers silently."] = "as usize は u8 をタダで広げる。u8 の添字はコンパイルできない: Rust は整数を黙って変換しない。",
  ["as_ followed by the short word for reference. Its cousin as_deref goes one step further, to Option<&Node>."] = "as_ の後ろに、参照を意味する短い 3 文字。親戚の as_deref はもう一歩進んで Option<&Node> になる。",
  ["as_completed is Go's select over many channels: whoever finishes first is served first, and a slow chunk never holds up the log."] = "as_completed は多数の channel に対する Go の select だ：先に終わった者から相手をし、遅い塊がログを止めることはない。",
  ["as_ref would give Option<&Box<T>>. This one also derefs the Box. as_ plus deref."] = "as_ref なら Option<&Box<T>> になる。こちらは Box もデリファレンスする。as_ に deref を足したもの。",
  ["async and tokio"] = "async と tokio",
  ["async def fetch(rider):\n    await asyncio.___(1)     # the radio takes a second\n    return rider\n"] = "async def fetch(rider):\n    await asyncio.___(1)     # 無線は1秒かかる\n    return rider\n",
  ['async def main():\n    riders = ["Ken", "Mei", "Bo"]\n    where = await asyncio.___(*(fetch(r) for r in riders))\n    print(where)     # one second total, not three\n'] = 'async def main():\n    riders = ["Ken", "Mei", "Bo"]\n    where = await asyncio.___(*(fetch(r) for r in riders))\n    print(where)     # 合計1秒、3秒ではない\n',
  ['async def main():\n    t = asyncio.___(fetch("Ken"))\n    print("radio sent")\n    print(await t)\n'] = 'async def main():\n    t = asyncio.___(fetch("Ken"))\n    print("radio sent")\n    print(await t)\n',
  ['async def main():\n    where = ___ fetch("Ken")\n    print(where)\n'] = 'async def main():\n    where = ___ fetch("Ken")\n    print(where)\n',
  ["async def makes a coroutine; await pauses it until the result is in. asyncio.run starts the loop, gather runs several at once, sleep waits without blocking, create_task fires and forgets."] = "async def はコルーチンを作る。await は結果が来るまで止める。asyncio.run はループを始め、gather は複数を同時に走らせ、sleep はブロックせずに待ち、create_task は投げて忘れる。",
  ["async def returns a coroutine object when called; nothing runs until it is awaited or scheduled."] = "async def は呼ばれるとコルーチンオブジェクトを返す。await されるかスケジュールされるまで何も走らない。",
  ["async fn eta(url: &str) -> Result<String, Box<dyn Error>> {\n    // GET, wait for headers, then wait for the body\n    let body = ___::get(url).await?.text().await?;\n    Ok(body)\n}\n"] = "async fn eta(url: &str) -> Result<String, Box<dyn Error>> {\n    // GET してヘッダを待ち、それから本文を待つ\n    let body = ___::get(url).await?.text().await?;\n    Ok(body)\n}\n",
  ["async fn fetch_eta(..) -> u32 really returns impl Future<Output = u32>. Nothing runs until polled."] = "async fn fetch_eta(..) -> u32 は実際には impl Future<Output = u32> を返す。poll されるまで何も動かない。",
  ['async fn plan() {\n    // suspends here; other tasks run while we wait\n    let eta = fetch_eta(7)___;\n    println!("rider back in {eta} min");\n}\n'] = 'async fn plan() {\n    // ここで中断。待っている間に他のタスクが動く\n    let eta = fetch_eta(7)___;\n    println!("rider back in {eta} min");\n}\n',
  ["async fn returns a Future; .await drives it. tokio runs them; spawn and join! run them at once."] = "async fn は Future を返し、.await が駆動する。tokio が動かす。spawn と join! で同時に走らせる。",
  ["asyncio"] = "asyncio",
  ["asyncio handles the waiting, processes handle the computing, and await joins them. Go does the same thing with one goroutine and no ceremony."] = "asyncio が待ちを、プロセスが計算を受け持ち、await が両者をつなぐ。Go は goroutine 一つで同じことを、儀式なしにやる。",
  ["asyncio.run(main()) creates the loop, runs the coroutine, closes the loop. Rust's #[tokio::main]."] = "asyncio.run(main()) はループを作り、コルーチンを走らせ、ループを閉じる。Rust の #[tokio::main]。",
  ["atomic.Int64 keeps its own value, so nobody can read it the unsafe way. The old atomic.AddInt64(&n, 1) still works, but the type is safer."] = "atomic.Int64 は値を自分の中に持つので、危険な読み方はできない。古い atomic.AddInt64(&n, 1) も動くが、型のほうが安全だ。",
  ["atomic.Pointer[Menu] gives copy-on-write config: build a new menu, Store it, and every reader after that sees the new one whole."] = "atomic.Pointer[Menu] はコピーオンライトの設定を与える：新しいメニューを作って Store すれば、以後の読み手は新しいものを丸ごと見る。",
  ["await asyncio.sleep(1) yields to the loop; time.sleep(1) would freeze every task. Same trap as in tokio."] = "await asyncio.sleep(1) はループに譲る。time.sleep(1) はすべてのタスクを凍らせる。tokio と同じ罠。",
  ["await hands control to the event loop until the coroutine finishes. Only allowed inside async def."] = "await はコルーチンが終わるまで制御をイベントループに渡す。async def の中でのみ許される。",
  ["b := make([]int, ___(a))    // allocate n ints\ncopy(b, a)                  // O(n) time, O(n) space\n"] = "b := make([]int, ___(a))    // n 個の int を確保\ncopy(b, a)                  // O(n) 時間、O(n) 空間\n",
  ["b := slices.Clone(a)    // a second slice of n ints: O(___)\nsort.Ints(b)\n"] = "b := slices.Clone(a)    // n 個の int の2つ目のスライス: O(___)\nsort.Ints(b)\n",
  ["b = ___(a)    # allocate n slots and copy: O(n) time, O(n) space\n"] = "b = ___(a)    # n 個のスロットを確保してコピー: O(n) 時間、O(n) 空間\n",
  ["b = sorted(a)    # a second list of n items: O(___)\n"] = "b = sorted(a)    # n 項目の2つ目のリスト: O(___)\n",
  ["b shares a's array. After b[0] = 9, what does a[0] print?"] = "b は a の配列を共有。b[0] = 9 のあと、a[0] は何を出力？",
  ["b'1' is 49u8, the ASCII byte. Vec<Vec<u8>> is what you get from lines of a text map via as_bytes()."] = "b'1' は 49u8、ASCII のバイト。Vec<Vec<u8>> はテキスト地図の各行を as_bytes() で得たもの。",
  ['b, err := json.___(order)   // []byte\nfmt.Println(string(b))      // {"dish":"set"}\n'] = 'b, err := json.___(order)   // []byte\nfmt.Println(string(b))      // {"dish":"set"}\n',
  ["binary, underscore, search. Takes a reference to the wanted value. Err carries the insertion point."] = "binary、アンダースコア、search。探したい値への参照を取る。Err は挿入位置を運ぶ。",
  ["binary_search has one precondition. The slice must be ___"] = "binary_search には前提が1つある。スライスは ___ でなければならない",
  ["bisect has one precondition. The list must be ___"] = "bisect には前提が1つある。リストは ___ でなければならない",
  ["bisect_left returns the first index >= x; bisect_right the one after equals. insort inserts. Round five to Bo."] = "bisect_left は >= x の最初のインデックスを返す。bisect_right は等しいものの後。insort は挿入する。第5ラウンドはボーに。",
  ["break ends the loop; continue skips to the next item. A for loop may have an else: that runs only if no break happened."] = "break はループを終える。continue は次の項目へ飛ぶ。for ループには else を付けられる: break が起きなかったときだけ走る。",
  ["break leaves the innermost for, switch or select. A label breaks an outer one."] = "break は一番内側の for、switch、select を抜けます。ラベルで外側も抜けられます。",
  ["brew takes a whole number of cups and returns text. Annotate the parameter."] = "brew は整数のカップ数を受け取りテキストを返す。引数に注釈を付けよ。",
  ["c - b'a' is a u8 from 0 to 25. Arrays are indexed by exactly one integer type. Cast to which?"] = "c - b'a' は 0 から 25 までの u8。配列の添字になれる整数型はただ 1 つ。どれにキャストする？",
  ["cap is the room in the backing array. append doubles it when len reaches cap."] = "cap は内部配列の余裕。len が cap に達すると append が倍にします。",
  ["cargo add serde --features derive writes the line for you and picks the newest version."] = "cargo add serde --features derive が行を書いてくれて、最新バージョンを選ぶ。",
  ["cargo clippy is the linter; -- -D warnings makes CI fail on any lint. The crab approves."] = "cargo clippy がリンター。-- -D warnings で CI はどんな lint でも失敗にする。カニも納得。",
  ["cargo fmt rewrites in place; --check only reports. Build green, lint clean. Ticket six closed."] = "cargo fmt はその場で書き換える。--check は報告だけ。ビルドは緑、lint はきれい。チケット6完了。",
  ["cargo new makes Cargo.toml, src/main.rs and a git repo. cargo init does it in an existing folder."] = "cargo new は Cargo.toml、src/main.rs、git リポジトリを作る。cargo init は既存フォルダで同じことをする。",
  ["cargo new, add, build --release, test, clippy, fmt. Cargo.toml asks, Cargo.lock pins."] = "cargo new、add、build --release、test、clippy、fmt。Cargo.toml が要求し、Cargo.lock が固定する。",
  ["cargo run. cargo new makes a project, cargo build compiles, cargo test runs tests. The kiosk boots."] = "cargo run。cargo new でプロジェクト作成、cargo build でコンパイル、cargo test でテスト実行。キオスクが起動する。",
  ["cargo test builds a test binary and runs #[test] fns in parallel. cargo test name filters."] = "cargo test はテストバイナリを作り、#[test] の関数を並列に走らせる。cargo test name で絞り込める。",
  ["ch := make(___)        // unbuffered\n"] = "ch := make(___)        // バッファなし\n",
  ["ch := make(chan Order, 8)\nch <- Order{id: 1}\nfmt.Println(len(ch), ___(ch))\n// 1 8\n"] = "ch := make(chan Order, 8)\nch <- Order{id: 1}\nfmt.Println(len(ch), ___(ch))\n// 1 8\n",
  ["ch := make(chan int)\nch <- 1                // nobody receives\nfmt.Println(<-ch)\n// fatal error: all goroutines are asleep - ___!\n"] = "ch := make(chan int)\nch <- 1                // 誰も受信しない\nfmt.Println(<-ch)\n// fatal error: all goroutines are asleep - ___!\n",
  ['ch := make(chan string)\nch ___ "muffin"        // send\n'] = 'ch := make(chan string)\nch ___ "muffin"        // 送信\n',
  ['ch := make(chan string, ___)   // buffered\nch <- "muffin"                 // does not block yet\n'] = 'ch := make(chan string, ___)   // バッファあり\nch <- "muffin"                 // まだブロックしない\n',
  ["ch <- x sends. x := <-ch receives. Same operator, different place."] = "ch <- x が送信。x := <-ch が受信。同じ演算子、違う位置。",
  ["chan is a typed pipe. <- sends and receives. close tells receivers to stop."] = "chan は型付きパイプ。<- で送受信。close で受信側に終了を伝えます。",
  ["chan struct{} plus close is the cheapest done signal. context.Done() returns one."] = "chan struct{} と close が最も安価な完了シグナル。context.Done() もこれを返します。",
  ["chars().count() walks the string and counts. The receipt prints 銅鑼灣 in full."] = "chars().count() は文字列を歩いて数える。レシートに 銅鑼灣 が全部印字された。",
  ["cheapest := ___(muffin, hash, coffee)   // built-in\n"] = "cheapest := ___(muffin, hash, coffee)   // 組み込み\n",
  ["class ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = ___\n"] = "class ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = ___\n",
  ["class MinStack:\n    def __init__(self):\n        self.st, self.lows = [], []\n    def push(self, x):\n        self.st.append(x)\n        m = self.lows[-1] if self.lows else x\n        self.lows.append(___(x, m))\n"] = "class MinStack:\n    def __init__(self):\n        self.st, self.lows = [], []\n    def push(self, x):\n        self.st.append(x)\n        m = self.lows[-1] if self.lows else x\n        self.lows.append(___(x, m))\n",
  ["class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = ___\n        self.right = ___\n"] = "class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = ___\n        self.right = ___\n",
  ["class Order:\n    @___\n    def from_line(cls, line):\n        qty, _, item = line.split()\n        return cls(item, int(qty))\n"] = "class Order:\n    @___\n    def from_line(cls, line):\n        qty, _, item = line.split()\n        return cls(item, int(qty))\n",
  ['class Order:\n    def ___(self, item):\n        self.item = item\n\no = Order("noodles")\nprint(o.item)\n'] = 'class Order:\n    def ___(self, item):\n        self.item = item\n\no = Order("noodles")\nprint(o.item)\n',
  ['class Order:\n    def __init__(self, item):\n        self.item = item\n\n    def ___(self):\n        return f"Order({self.item})"\n'] = 'class Order:\n    def __init__(self, item):\n        self.item = item\n\n    def ___(self):\n        return f"Order({self.item})"\n',
  ['class Order:\n    def __init__(self, item):\n        self.item = item\n\n    def label(___):\n        return f"1 x {___.item}"\n'] = 'class Order:\n    def __init__(self, item):\n        self.item = item\n\n    def label(___):\n        return f"1 x {___.item}"\n',
  ["class Order:\n    def __init__(self, qty, price):\n        self.qty, self.price = qty, price\n\n    @___\n    def total(self):\n        return self.qty * self.price\n"] = "class Order:\n    def __init__(self, qty, price):\n        self.qty, self.price = qty, price\n\n    @___\n    def total(self):\n        return self.qty * self.price\n",
  ["class Order: then the body. Order() calls it to make an instance. pass is the empty statement."] = "class Order: そして本体。Order() を呼ぶとインスタンスができる。pass は空文。",
  ["class OutOfStock(Exception) is enough. Callers write except OutOfStock:. The refund desk stops crashing."] = "class OutOfStock(Exception) で十分。呼び出し側は except OutOfStock: と書く。返金デスクは落ちなくなる。",
  ['class OutOfStock(___):\n    pass\n\nraise OutOfStock("egg")\n'] = 'class OutOfStock(___):\n    pass\n\nraise OutOfStock("egg")\n',
