  ["class Till:\n    @___\n    def round_up(cents):\n        return (cents + 9) // 10 * 10\n\nprint(Till.round_up(123))    # 130\n"] = "class Till:\n    @___\n    def round_up(cents):\n        return (cents + 9) // 10 * 10\n\nprint(Till.round_up(123))    # 130\n",
  ["class defines a type. __init__ runs on creation; self is the object, written explicitly. __str__ is the print form. super() reaches the parent. @dataclass writes the boilerplate."] = "class は型を定義する。__init__ は生成時に走る。self はオブジェクト自身で、明示的に書く。__str__ は印字形式。super() は親に届く。@dataclass が定型文を書いてくれる。",
