  ["fn climb(n: usize) -> u64 {\n    let mut dp = vec![0u64; n + 1];\n    dp[0] = 1;              // stand still\n    dp[1] = ___;            // a single step\n"] = "fn climb(n: usize) -> u64 {\n    let mut dp = vec![0u64; n + 1];\n    dp[0] = 1;              // その場に立つ\n    dp[1] = ___;            // 1段だけ\n",
  ['fn count(s: ___String) -> usize {\n    s.len()\n}\nlet a = String::from("coffee");\nlet n = count(&a);\nprintln!("{} {}", a, n);   // a still alive\n'] = 'fn count(s: ___String) -> usize {\n    s.len()\n}\nlet a = String::from("coffee");\nlet n = count(&a);\nprintln!("{} {}", a, n);   // a はまだ生きている\n',
  ['fn dfs(g: &Graph, start: u32, seen: &mut HashSet<u32>) {\n    let mut stack = vec![start];     // a Vec is a stack too\n    while let Some(n) = stack.___() { // LIFO: newest first\n        if !seen.insert(n) { continue; }\n        print!("{n} "); stack.extend(&g[&n]);\n    }\n}\n'] = 'fn dfs(g: &Graph, start: u32, seen: &mut HashSet<u32>) {\n    let mut stack = vec![start];     // Vec もスタック\n    while let Some(n) = stack.___() { // LIFO: 新しいものから\n        if !seen.insert(n) { continue; }\n        print!("{n} "); stack.extend(&g[&n]);\n    }\n}\n',
