  ["out := make([]Dish, len(orders))\nfor i := range orders {\n    go func() {\n        out[___] = cook(orders[i])\n    }()\n}\n"] = "out := make([]Dish, len(orders))\nfor i := range orders {\n    go func() {\n        out[___] = cook(orders[i])\n    }()\n}\n",
  ["out = [[9, 12], [13, 15], [16, 18]]\n# the free slots between blocks: (12, 13), (15, 16)\nfree = [(a[1], b[0]) for a, b in zip(out, out[___])]\n"] = "out = [[9, 12], [13, 15], [16, 18]]\n# ブロック間の空き枠: (12, 13), (15, 16)\nfree = [(a[1], b[0]) for a, b in zip(out, out[___])]\n",
  ["out[-1] is the last merged block, [1] its end. The sort guarantees s is never before the block's start."] = "out[-1] が最後にマージしたブロック、[1] がその終わり。ソートのおかげで s がブロックの開始より前になることはない。",
  ['p := ___Order{Item: "set"}   // p is *Order\np.Price = 25                  // Go dereferences for you\n'] = 'p := ___Order{Item: "set"}   // p は *Order\np.Price = 25                  // Goが自動で参照外し\n',
