  ["package main\n___ opens = 6          // Lucky Mac hour, never changes\n"] = "package main\n___ opens = 6          // Lucky Macの開店時刻、変わらない\n",
  ['package main\n___ shop string = "Lucky Mac"   // package level: no :=\nfunc main() {\n    fmt.Println(shop)\n}\n'] = 'package main\n___ shop string = "Lucky Mac"   // packageレベル: := は不可\nfunc main() {\n    fmt.Println(shop)\n}\n',
  ["package main\nfunc main() {\n    floor ___ 8      // type inferred as int\n}\n"] = "package main\nfunc main() {\n    floor ___ 8      // 型は int と推論される\n}\n",
  ['package main\nimport "___"\nfunc main() {\n    Println("hash brown")\n}\n'] = 'package main\nimport "___"\nfunc main() {\n    Println("hash brown")\n}\n',
  ['package main\nimport "fmt"\nfunc main() {\n    fmt.___("morning set")   // capital P: exported\n}\n'] = 'package main\nimport "fmt"\nfunc main() {\n    fmt.___("morning set")   // 大文字のP: エクスポート\n}\n',
  ['package main\nvar menu map[string]int\nfunc ___() {                // before main\n    menu = map[string]int{"muffin": 18}\n}\nfunc main() {}\n'] = 'package main\nvar menu map[string]int\nfunc ___() {                // main の前\n    menu = map[string]int{"muffin": 18}\n}\nfunc main() {}\n',
  ["package main is the entry. Other folders are libraries."] = "package main が入口です。他のフォルダはライブラリです。",
  ["pairs := map[rune]rune{\n    ')': ___,           // closer -> opener\n    ']': '[',\n    '}': '{',\n}\n"] = "pairs := map[rune]rune{\n    ')': ___,           // 閉じ -> 開き\n    ']': '[',\n    '}': '{',\n}\n",
  ["panic stops the goroutine. recover() inside defer can save it. Rare in libraries."] = "panic は goroutine を止めます。defer 内の recover() で救えます。ライブラリでは稀です。",
  ["panic unwinds the stack running every defer. recover in a defer can stop it."] = "panic はスタックを巻き戻し、全 defer を実行します。defer 内の recover で止められます。",
