  ["select {\ncase m := <-muffin:\n    serve(m)\n___:\n    skip()\n}\n"] = "select {\ncase m := <-muffin:\n    serve(m)\n___:\n    skip()\n}\n",
  ["select {\ncase m := <-muffin:\n    serve(m)\ncase <-ctx.___():\n    return ctx.Err()\n}\n"] = "select {\ncase m := <-muffin:\n    serve(m)\ncase <-ctx.___():\n    return ctx.Err()\n}\n",
  ['select {\ncase m := <-muffin:\n    serve(m)\ncase <-time.___(time.Second):\n    fmt.Println("timeout")\n}\n'] = 'select {\ncase m := <-muffin:\n    serve(m)\ncase <-time.___(time.Second):\n    fmt.Println("timeout")\n}\n',
  ["select { case x := <-ch: ... }. Random choice if several are ready."] = "select { case x := <-ch: ... }。複数が準備済みならランダムに選びます。",
  ["sem := make(chan struct{}, 4)\nsem <- struct{}{}\ngo func() {\n    deliver(o)\n    ___\n}()\n"] = "sem := make(chan struct{}, 4)\nsem <- struct{}{}\ngo func() {\n    deliver(o)\n    ___\n}()\n",
  ["sem := make(chan struct{}, ___)\nfor _, u := range urls {\n    sem <- struct{}{}        // acquire (blocks when full)\n    go func(u string) {\n        defer func() { <-sem }()   // release\n        fetch(u) }(u)\n}\n"] = "sem := make(chan struct{}, ___)\nfor _, u := range urls {\n    sem <- struct{}{}        // 取得（満杯ならブロック）\n    go func(u string) {\n        defer func() { <-sem }()   // 解放\n        fetch(u) }(u)\n}\n",
  ["serde and JSON"] = "serde と JSON",
  ["serde_json::Value indexes with [] and returns Null when missing. Ticket four closed."] = "serde_json::Value は [] で添字アクセスでき、なければ Null を返す。チケット4完了。",
  ["serde_json::from_str::<Order>(text). from_slice for bytes, from_reader for files."] = "serde_json::from_str::<Order>(text)。バイト列には from_slice、ファイルには from_reader。",
  ["serde_json::to_string(&order) -> compact JSON. to_vec gives bytes, to_writer streams."] = "serde_json::to_string(&order) -> コンパクトな JSON。to_vec はバイト列、to_writer はストリームに書く。",
  ["set(names) drops duplicates; x in s is O(1). {1, 2} is a set literal, but {} is a dict. Sets have no order."] = "set(names) は重複を落とす。x in s は O(1)。{1, 2} は set リテラルだが {} は dict。set に順序はない。",
  ["set: one O(1) check per guest, O(n) total. Fifty million checks become ten thousand."] = "set: 客ごとに O(1) のチェック1回、合計 O(n)。5000万回のチェックが1万回になる。",
  ["shared_memory: no copy at all"] = "shared_memory：コピーはまったくなし",
  ["shifts = [[13, 15], [9, 11], [10, 12]]\n# sort by start so overlapping shifts sit side by side\nshifts.sort(key=lambda iv: iv[___])\nprint(shifts)    # [[9, 11], [10, 12], [13, 15]]\n"] = "shifts = [[13, 15], [9, 11], [10, 12]]\n# 開始でソートし、重なるシフトを隣に\nshifts.sort(key=lambda iv: iv[___])\nprint(shifts)    # [[9, 11], [10, 12], [13, 15]]\n",
  ["shm.close()\n\n# in the parent only, once:\nshm.___()\n"] = "shm.close()\n\n# 親でだけ、一度：\nshm.___()\n",
  ['shops := []string{"Lucky Mac", "Sogo"}\nfor _, name := ___ shops {\n    fmt.Println(name)\n}\n'] = 'shops := []string{"Lucky Mac", "Sogo"}\nfor _, name := ___ shops {\n    fmt.Println(name)\n}\n',
  ['sign = "open" if bowls > 0 ___ "closed"\nprint(sign)\n'] = 'sign = "open" if bowls > 0 ___ "closed"\nprint(sign)\n',
  ["sink stops off the map. usize never goes below zero, so only the far edges need a test. Row r is outside when r is what, compared with the row count?"] = "sink は地図の外で止まる。usize は 0 を下回らないので、遠い側の端だけ確認すればいい。行 r が外にあるのは、行数と比べて r がどうのとき？",
  ['skip_serializing_if = "Option::is_none" drops empty fields. default fills them on the way in.'] = 'skip_serializing_if = "Option::is_none" で空のフィールドを省く。default は読み込み時に埋める。',
  ["slices.Contains, Index, Reverse, Max: the loops you used to write by hand."] = "slices.Contains、Index、Reverse、Max: 昔は手で書いていたループたち。",
  ["slices.Sort is generic: no sort.Strings / sort.Ints per type any more."] = "slices.Sort はジェネリック: 型ごとの sort.Strings / sort.Ints はもう不要。",
  ["slow, fast := head, head\nfor fast != nil && fast.Next != nil {\n    slow = slow.Next\n    fast = fast.Next.___\n    if slow == fast { return true }   // cycle\n}\n"] = "slow, fast := head, head\nfor fast != nil && fast.Next != nil {\n    slow = slow.Next\n    fast = fast.Next.___\n    if slow == fast { return true }   // 循環\n}\n",
  ["sold++ is three machine steps. Two goroutines can land between them. Put a lock around it."] = "sold++ は機械語で三段階。二つの goroutine がその間に割り込める。ロックで囲もう。",
  ["sort, an underscore, and the word for 'may reorder equal items'."] = "sort、アンダースコア、そして「等しい項目を並べ替えるかもしれない」を意味する単語。",
  ["sort, by, key with underscores. The closure returns something Ord; here a u32."] = "sort、by、key をアンダースコアでつなぐ。クロージャは Ord なものを返す。ここでは u32。",
  ["sort, underscore, the opposite of stable. A pattern-defeating quicksort inside."] = "sort、アンダースコア、stable の反対語。中身は pattern-defeating quicksort。",
  ["sort.Ints on n receipts: what does it cost, in Big O?"] = "n 枚のレシートへの sort.Ints: Big O でコストは？",
  ["sort.Ints sorts the slice where it is. Extra memory, in Big O: O(___)"] = "sort.Ints はスライスをその場でソートする。追加のメモリは Big O で: O(___)",
  ["sort.Ints(a)                        // once: n log n\nfor _, x := range queries {\n    _, ok := slices.BinarySearch(a, x)   // each: O(___)\n}\n"] = "sort.Ints(a)                        // 一度: n log n\nfor _, x := range queries {\n    _, ok := slices.BinarySearch(a, x)   // 各回: O(___)\n}\n",
  ["sort.Ints(a)    // in place: O(___) extra space\n"] = "sort.Ints(a)    // その場: O(___) の追加空間\n",
  ["sort.Ints(amounts)    // ___ : pdqsort, comparison-based\n"] = "sort.Ints(amounts)    // ___ : pdqsort、比較ベース\n",
  ["sort.Ints(starts); sort.Ints(ends)\nrooms, e := 0, 0\nfor _, s := range starts {\n    if s ___ ends[e] {      // one meeting already over\n        e++\n    } else {\n        rooms++\n"] = "sort.Ints(starts); sort.Ints(ends)\nrooms, e := 0, 0\nfor _, s := range starts {\n    if s ___ ends[e] {      // 会議が 1 つもう終わった\n        e++\n    } else {\n        rooms++\n",
  ["sort.Slice with a less function. slices.SortFunc is the generic Go 1.21 way."] = "less 関数付きの sort.Slice。slices.SortFunc は Go 1.21 のジェネリック版。",
  ["sort.Slice(iv, func(i, j int) bool {\n    return iv[i][0] ___ iv[j][0]    // earliest start first\n})\n"] = "sort.Slice(iv, func(i, j int) bool {\n    return iv[i][0] ___ iv[j][0]    // 早い start が先\n})\n",
  ["sort.Strings(names). Go 1.21's slices.Sort(names) is generic and does the same. Both n log n."] = "sort.Strings(names)。Go 1.21 の slices.Sort(names) はジェネリックで同じことをする。どちらも n log n。",
  ["sort.___(orders, func(i, j int) bool {\n    return orders[i].Price < orders[j].Price\n})\n"] = "sort.___(orders, func(i, j int) bool {\n    return orders[i].Price < orders[j].Price\n})\n",
  ["sort_by_key is a stable merge sort, like the one you just wrote. sort_by takes a full comparator instead."] = "sort_by_key は安定なマージソート、いま書いたのと同じもの。sort_by の方は完全な比較関数を取る。",
  ["sort_unstable sorts the Vec where it is. Extra memory, in Big O: O(___)"] = "sort_unstable は Vec をその場でソートする。追加のメモリは Big O で: O(___)",
  ["sort_unstable: O(n log n), in place, usually faster than sort. Use sort only when order among equals matters. Combo x5."] = "sort_unstable: O(n log n)、その場で、たいてい sort より速い。等しいもの同士の順序が大事なときだけ sort を使う。コンボ x5。",
  ["sort_unstable: same O(n log n), less memory, usually faster. sort_by_key(|o| o.price) sorts by a field."] = "sort_unstable: 同じ O(n log n)、メモリは少なく、たいてい速い。sort_by_key(|o| o.price) はフィールドでソートする。",
  ["sorted on n receipts: what does it cost, in Big O?"] = "n 枚のレシートへの sorted: Big O でコストは？",
  ["sorted() is Timsort: merge sort that notices runs already in order. Still n log n in the worst case."] = "sorted() は Timsort: すでに順序の整った並びに気づくマージソート。最悪の場合はやはり n log n。",
  ["sorted(a) == sorted(b) is O(n log n) and one line. Counter(a) == Counter(b) is O(n) and just as short."] = "sorted(a) == sorted(b) は O(n log n) で一行。Counter(a) == Counter(b) は O(n) で同じくらい短い。",
  ["sorted(names, key=len). The key is called n times, O(n), then Timsort. Both together: n log n."] = "sorted(names, key=len)。key は n 回呼ばれ O(n)、それから Timsort。合わせて n log n。",
  ["sorted(xs) returns a new list, xs.sort() sorts in place. Both take key= and reverse=True. The rack is in order."] = "sorted(xs) は新しいリストを返し、xs.sort() はその場で並べる。どちらも key= と reverse=True を取る。棚が整った。",
  ["spawn returns a handle you can wait on. What is its type?"] = "spawn は待てるハンドルを返す。その型は？",
  ["spawn starts a clean interpreter and pickles the target across, so nothing is silently inherited. fork is faster and shares everything, including locks held at the wrong moment."] = "spawn はきれいなインタプリタを起こし、target を pickle して渡すので、黙って継承されるものはない。fork は速いがすべてを共有する。悪い瞬間に握られていたロックまで。",
  ["split, underscore, at. Panics if mid is past the end; here it never is."] = "split、アンダースコア、at。mid が末尾を越えると panic するが、ここでは決して越えない。",
  ["split_at gives (&v[..mid], &v[mid..]) as one tuple. Two shared borrows of one slice are fine."] = "split_at は (&v[..mid], &v[mid..]) を 1 つのタプルで返す。1 つのスライスへの共有借用は 2 つあっても平気。",
  ["st := []rune{}\nfor _, c := range s {\n    if _, closer := pairs[c]; !closer {\n        st = ___(st, c)     // an opener waits here\n        continue\n    }\n}\n"] = "st := []rune{}\nfor _, c := range s {\n    if _, closer := pairs[c]; !closer {\n        st = ___(st, c)     // 開きカッコはここで待つ\n        continue\n    }\n}\n",
  ['st = []\nst.append("(")\nst.append("[")\ntop = st[___]        # the most recent opener\nprint(top)           # [\n'] = 'st = []\nst.append("(")\nst.append("[")\ntop = st[___]        # 直近の開き括弧\nprint(top)           # [\n',
  ["st[-1] is the peek. Guard it with if st: the same way as pop."] = "st[-1] が peek。pop と同じく if st: で守れ。",
  ["starmap(f, [(a, b), ...]) calls f(a, b). It is the difference between one argument and several, and the reason you rarely need a wrapper function."] = "starmap(f, [(a, b), ...]) は f(a, b) を呼ぶ。引数一つと複数の違いであり、ラッパー関数がめったに要らない理由だ。",
  ["start:stop, the stop is not included. Same rule as Go's a[1:3]."] = "start:stop、stop は含まれない。Go の a[1:3] と同じ規則。",
  ['str(4) is "4". "Table " + 4 raises TypeError: Python never converts silently. The stock count comes out whole.'] = 'str(4) は "4"。"Table " + 4 は TypeError: Python は黙って変換しない。在庫数が整数で出る。',
  ["strconv.Atoi / Itoa for ints, ParseFloat and FormatFloat for floats."] = "int には strconv.Atoi / Itoa、float には ParseFloat と FormatFloat。",
  ["string is bytes, rune is a code point. utf8 counts characters, strconv converts."] = "string はバイト列、rune はコードポイント。utf8 は文字を数え、strconv は変換します。",
  ["strings has Split, Join, Contains, TrimSpace, ToUpper... all return new strings."] = "strings には Split、Join、Contains、TrimSpace、ToUpper など。すべて新しい string を返します。",
  ['struct Grill;\n// Grill promises every method of Cook.\nimpl Cook ___ Grill {\n    fn name(&self) -> String {\n        "grill".to_string()\n    }\n}\n'] = 'struct Grill;\n// Grill は Cook のすべてのメソッドを約束する。\nimpl Cook ___ Grill {\n    fn name(&self) -> String {\n        "grill".to_string()\n    }\n}\n',
  ["struct ListNode {\n    val: i32,\n    next: ___<Box<ListNode>>,   // the rest, or the end\n}\n"] = "struct ListNode {\n    val: i32,\n    next: ___<Box<ListNode>>,   // 残り、または終わり\n}\n",
  ["struct Order { id: u32, price: u32 }\nlet mut orders = vec![\n    Order { id: 7, price: 45 },\n    Order { id: 3, price: 18 },\n];\n// cheapest first; equal prices keep their order (stable)\norders.___(|o| o.price);\n"] = "struct Order { id: u32, price: u32 }\nlet mut orders = vec![\n    Order { id: 7, price: 45 },\n    Order { id: 3, price: 18 },\n];\n// 安い順。同じ値段は順序を保つ (安定)\norders.___(|o| o.price);\n",
  ["struct Order { item: String, qty: u32 } Fields are private to the module unless marked pub."] = "struct Order { item: String, qty: u32 } フィールドは pub を付けない限りモジュール内だけの非公開。",
  ["struct Order { qty: u32 }\n\n___ Order {\n    fn total(&self) -> u32 {\n        self.qty * 18\n    }\n}\n"] = "struct Order { qty: u32 }\n\n___ Order {\n    fn total(&self) -> u32 {\n        self.qty * 18\n    }\n}\n",
  ["struct Receipt<'a> { name: &'a str }: a Receipt cannot outlive the name it borrows. The compiler now checks it for you."] = "struct Receipt<'a> { name: &'a str }: Receipt は借りている名前より長生きできない。これでコンパイラが検査してくれる。",
  ['struct Wok;\nimpl Cook for Wok {\n    fn name(&self) -> String { "wok".to_string() }\n}\n// Any Cook, decided at run time, behind a reference.\nfn call(c: &___ Cook) { println!("{}", c.greet()); }\ncall(&Grill); call(&Wok);\n'] = 'struct Wok;\nimpl Cook for Wok {\n    fn name(&self) -> String { "wok".to_string() }\n}\n// 実行時に決まる任意の Cook、参照の向こうに。\nfn call(c: &___ Cook) { println!("{}", c.greet()); }\ncall(&Grill); call(&Wok);\n',
  ["struct groups fields. *T is a pointer. Methods have a receiver. interface is a set of methods."] = "struct はフィールドをまとめる。*T は pointer。メソッドにはレシーバがある。interface はメソッドの集まり。",
  ["struct groups fields. impl adds methods that take &self or &mut self. enum lists variants; match handles them all."] = "struct はフィールドをまとめる。impl は &self か &mut self を取るメソッドを足す。enum はバリアントを並べ、match がすべて処理する。",
  ["struct, impl and enum"] = "struct、impl、enum",
  ["submit(f, *args) is go f(args): the call is already running somewhere else and you hold the receipt."] = "submit(f, *args) は go f(args) だ：呼び出しはもうどこかで走っていて、あなたは受領証を持っている。",
  ["sum := 0\nfor _, p := range prices {    // ___ : n items, n adds\n    sum += p\n}\n"] = "sum := 0\nfor _, p := range prices {    // ___ : n 項目、n 回の加算\n    sum += p\n}\n",
  ["sum over n prices: what is the cost in Big O?"] = "n 個の値段への sum: Big O でコストは？",
  ["sum takes any number of fares. Fill the parameter type: fares ___"] = "sum は任意の数の運賃を受け取る。引数の型を埋める: fares ___",
  ["sum::<i32>() adds &i32 into an i32. Without the turbofish Rust cannot pick the type."] = "sum::<i32>() は &i32 を i32 に足し込む。ターボフィッシュなしでは Rust は型を決められない。",
  ["super().__init__(item) runs the parent constructor. class SetMeal(Order) is inheritance; Go embeds instead."] = "super().__init__(item) は親のコンストラクタを走らせる。class SetMeal(Order) は継承。Go は代わりに埋め込む。",
  ['switch light { case "green": walk() }. No break: cases do not fall through.'] = 'switch light { case "green": walk() }。break 不要。case はフォールスルーしません。',
  ["switch v.(type) gives x the concrete type in every case."] = "switch v.(type) では各 case で x が具体的な型になります。",
  ['switch x := v.(___) {\ncase int:\n    fmt.Println(x + 1)      // x is an int here\ncase string:\n    fmt.Println(x + "!")    // and a string here\n}\n'] = 'switch x := v.(___) {\ncase int:\n    fmt.Println(x + 1)      // ここでは x は int\ncase string:\n    fmt.Println(x + "!")    // ここでは string\n}\n',
  ["sync, underscore, then the word for the pipe itself."] = "sync、アンダースコア、そしてパイプそのものを表す単語。",
  ["sync.Map pays off for keys written once and read often. For anything else a plain map behind a Mutex is faster and clearer."] = "sync.Map は一度書いて何度も読むキーで効く。それ以外なら Mutex で包んだ素の map のほうが速く、わかりやすい。",
  ["sync.Mutex. Lock, change, Unlock. Prefer channels when you can."] = "sync.Mutex。Lock、変更、Unlock。できれば channel を優先しましょう。",
  ["sync.Mutex: one goroutine at a time"] = "sync.Mutex：一度に一つの goroutine",
  ["sync.Once.Do runs the function once and blocks the others until it finishes. Go 1.21 adds sync.OnceValue."] = "sync.Once.Do は関数を一度だけ実行し、終わるまで他をブロックします。Go 1.21 で sync.OnceValue が追加。",
  ["sync.OnceValue(f) returns a function: the first call runs f, every later call returns the cached value. sync.OnceValues does the (T, error) pair."] = "sync.OnceValue(f) は関数を返す：最初の呼び出しだけ f を走らせ、以後はキャッシュした値を返す。(T, error) の組は sync.OnceValues。",
  ["sync.Pool recycles short-lived allocations across goroutines. It is a garbage-collector optimisation, never a place to keep state."] = "sync.Pool は短命な確保を goroutine 間で再利用する。ガベージコレクタの最適化であって、状態を置く場所では決してない。",
  ["sync.RWMutex: any number of RLock holders, or exactly one Lock holder. Worth it when reads dominate."] = "sync.RWMutex：RLock の保持者は何人でも、Lock の保持者はちょうど一人。読みが圧倒的なときに元が取れる。",
  ["sync/atomic is for single words: counters, flags. Anything bigger wants a Mutex."] = "sync/atomic は単一ワード向け：カウンタ、フラグ。それより大きいものは Mutex です。",
  ["sync_channel(n) is bounded: send blocks when n values wait. Backpressure, like a buffered Go channel. The queue moves."] = "sync_channel(n) は上限付き: n 個の値が待っていると send はブロックする。バックプレッシャー、Go の buffered channel のように。キューが動き出す。",
  ['t = threading.Thread(target=fry, args=("egg",))\nt.___()\nprint("frying in the background")\n'] = 't = threading.Thread(target=fry, args=("egg",))\nt.___()\nprint("frying in the background")\n',
  ["t.Errorf marks failure and continues; t.Fatalf stops. Table tests loop over cases with t.Run."] = "t.Errorf は失敗を記録して続行、t.Fatalf は停止。テーブルテストは t.Run でケースをループします。",
  ["t.start() spawns the OS thread and returns at once. t.run() is the body; calling it yourself gains nothing."] = "t.start() は OS スレッドを生み、すぐ戻る。t.run() は本体。自分で呼んでも得るものはない。",
  ['table = 4\nlabel = "Table " + ___(table)\nprint(label)       # Table 4\n'] = 'table = 4\nlabel = "Table " + ___(table)\nprint(label)       # Table 4\n',
  ["thiserror derives Display + Error; #[from] even writes the From impl. Ticket two closed."] = "thiserror が Display + Error を derive する。#[from] なら From の impl まで書いてくれる。チケット2完了。",
  ["thread::scope(|s| ...) joins every s.spawn before returning, so the closures may borrow without move. Three cooks, one menu."] = "thread::scope(|s| ...) は戻る前にすべての s.spawn を join するので、クロージャは move なしで借用できる。料理人 3 人、メニュー 1 つ。",
  ["thread::sleep(Duration) takes a Duration, never a bare number. Duration::from_secs and from_millis build one."] = "thread::sleep(Duration) は Duration を受け取り、生の数は受け取らない。Duration::from_secs や from_millis で作る。",
  ["thread::spawn returns JoinHandle<T>. Keep them in a Vec, or the threads are detached and main may exit first."] = "thread::spawn は JoinHandle<T> を返す。Vec に持っておかないとスレッドは切り離され、main が先に終わるかもしれない。",
  ["thread::spawn starts a thread; move gives it its data; join waits. thread::scope may borrow."] = "thread::spawn がスレッドを起こし、move がデータを渡し、join が待つ。thread::scope なら借用もできる。",
  ["thread::spawn(closure) returns a JoinHandle and runs at once on an OS thread. Rust has no green threads built in."] = "thread::spawn(closure) は JoinHandle を返し、すぐに OS スレッドで走る。Rust にはグリーンスレッドは組み込まれていない。",
  ["threading.Thread(target=f).start() runs f beside the main thread; join waits. Lock guards shared state. ThreadPoolExecutor manages a pool. The GIL lets one thread run bytecode at a time."] = "threading.Thread(target=f).start() はメインスレッドの横で f を走らせる。join は待つ。Lock は共有状態を守る。ThreadPoolExecutor はプールを管理する。GIL は一度に1スレッドだけにバイトコードを走らせる。",
  ["time.After in a select is the classic timeout. In a loop prefer a time.Timer."] = "select 内の time.After が定番のタイムアウト。ループ内では time.Timer が良いです。",
  ["tokio::spawn needs a 'static + Send future. handle.await gives Result<T, JoinError>."] = "tokio::spawn には 'static + Send な Future が必要。handle.await は Result<T, JoinError> を返す。",
  ["top = prices[0]\nfor p in prices[1:]:    # ___ comparisons\n    if p > top:\n        top = p\n"] = "top = prices[0]\nfor p in prices[1:]:    # ___ 回の比較\n    if p > top:\n        top = p\n",
  ["total = 0\n\ndef add(rows):\n    global total\n    total += sum(rows)\n# the child changed its own ___ of total\n"] = "total = 0\n\ndef add(rows):\n    global total\n    total += sum(rows)\n# 子は自分の total の ___ を変えただけ\n",
  ["total = sum(prices)    # ___ : n items, n adds, inside C\n"] = "total = sum(prices)    # ___ : n 項目、n 回の加算、C の中で\n",
  ["total = sum(prices)    # n steps\ntop = max(prices)      # n more\n# 2n steps, written O(___)\n"] = "total = sum(prices)    # n ステップ\ntop = max(prices)      # さらに n\n# 2n ステップ、O(___) と書く\n",
  ["total only reads the order. Which receiver borrows it without change?"] = "total は注文を読むだけ。変更せずに借用するレシーバは？",
  ["total(3, 5) and total(3, 5, 8) should both work. How is the parameter written to take any number of items?"] = "total(3, 5) も total(3, 5, 8) も動くべき。いくつでも受け取るには引数をどう書く？",
  ["trait Cook lists methods. One with a body is a default; implementors may keep it or override it."] = "trait Cook はメソッドを並べる。本体付きのものはデフォルトで、実装側はそのまま使っても上書きしてもいい。",
  ['tray := []string{"muffin", "hash", "coffee", "tea"}\ntwo := tray[___]         // {"hash", "coffee"}\n'] = 'tray := []string{"muffin", "hash", "coffee", "tea"}\ntwo := tray[___]         // {"hash", "coffee"}\n',
