  ['try:\n    refund(receipt)\nexcept KeyError:\n    print("no such receipt")\n___:\n    printer.close()\n'] = 'try:\n    refund(receipt)\nexcept KeyError:\n    print("no such receipt")\n___:\n    printer.close()\n',
  ["try: guards the risky lines. Rust has Result and ?; Python unwinds the stack to the nearest except."] = "try: が危ない行を守る。Rust には Result と ? がある。Python はスタックを最も近い except まで巻き戻す。",
  ["try_recv() returns at once: Ok(v), Err(Empty) or Err(Disconnected). Good for polling loops; recv_timeout is the middle road."] = "try_recv() はすぐ返る: Ok(v)、Err(Empty)、Err(Disconnected) のどれか。ポーリングループ向き。recv_timeout は中間の道。",
  ["two-sum with a HashMap, palindrome with chars().rev(), anagram with a [0; 26] counter, word count with entry().or_insert(0)."] = "two-sum は HashMap、回文は chars().rev()、アナグラムは [0; 26] のカウンタ、単語数は entry().or_insert(0)。",
  ["type Floor int             // new type, underlying int\n\nf := ___(3)                // int -> Floor\n"] = "type Floor int             // 新しい型、基底は int\n\nf := ___(3)                // int -> Floor\n",
