  ["type IntHeap []int\n\nfunc (h IntHeap) Len() int { return len(h) }\nfunc (h IntHeap) Less(i, j int) bool {\n    return h[i] ___ h[j]    // the smallest rises to the top\n}\nfunc (h IntHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }\n"] = "type IntHeap []int\n\nfunc (h IntHeap) Len() int { return len(h) }\nfunc (h IntHeap) Less(i, j int) bool {\n    return h[i] ___ h[j]    // 最小が頂点に浮く\n}\nfunc (h IntHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }\n",
