  ["type Link = Option<Box<ListNode>>;\nfn pop(head: &mut Link) -> Option<i32> {\n    // move the first node out, leave None in its place\n    let node = head.___()?;\n    *head = node.next;\n    Some(node.val)\n}\n"] = "type Link = Option<Box<ListNode>>;\nfn pop(head: &mut Link) -> Option<i32> {\n    // 先頭ノードを取り出し、代わりに None を置く\n    let node = head.___()?;\n    *head = node.next;\n    Some(node.val)\n}\n",
  ["type ListNode struct {\n    Val  int\n    Next ___             // nil at the tail\n}\n"] = "type ListNode struct {\n    Val  int\n    Next ___             // 末尾では nil\n}\n",
  ["type Name ___, then curly braces with fields."] = "type 名前 ___、そのあと波括弧にフィールド。",
