  ['type RefundError struct{ Amount int }\n\nfunc (e *RefundError) ___() string {\n    return "refund " + strconv.Itoa(e.Amount)\n}\n'] = 'type RefundError struct{ Amount int }\n\nfunc (e *RefundError) ___() string {\n    return "refund " + strconv.Itoa(e.Amount)\n}\n',
  ["type names a type. v.(T) asserts, switch v.(type) branches. Sprintf formats."] = "type は型に名前を付け、v.(T) はアサート、switch v.(type) は分岐。Sprintf は整形します。",
  ["type orderKey struct{}\n\nctx = context.___(ctx, orderKey{}, id)\n// five calls deeper:\nid, ok := ctx.Value(orderKey{}).(int)\n"] = "type orderKey struct{}\n\nctx = context.___(ctx, orderKey{}, id)\n// 五段深いところで：\nid, ok := ctx.Value(orderKey{}).(int)\n",
  ["type the answer"] = "答えを入力",
  ["type(price) is float. Python is dynamically typed: the value carries the type, the name does not."] = "type(price) は float。Python は動的型付け: 型は値が持ち、名前は持たない。",
  ["u for unsigned, then the word for pointer size. Same type as len() returns."] = "符号なしの u に、ポインタの大きさを表す語を続ける。len() が返すのと同じ型。",
