  ['use serde::{Deserialize, ___};\n// Cargo.toml: serde = {version="1", features=["derive"]}\n#[derive(Debug, ___, Deserialize)]\nstruct Order {\n    name: String,\n    qty: u32,\n}\n'] = 'use serde::{Deserialize, ___};\n// Cargo.toml: serde = {version="1", features=["derive"]}\n#[derive(Debug, ___, Deserialize)]\nstruct Order {\n    name: String,\n    qty: u32,\n}\n',
  ["use std::collections::HashMap;\n// station id -> the ids one hop away (an adjacency list)\ntype Graph = HashMap<u32, ___<u32>>;\nfn degree(g: &Graph, n: u32) -> usize {\n    g[&n].len()          // how many exits this station has\n}\n"] = "use std::collections::HashMap;\n// 駅 id -> 1 ホップ先の id たち (隣接リスト)\ntype Graph = HashMap<u32, ___<u32>>;\nfn degree(g: &Graph, n: u32) -> usize {\n    g[&n].len()          // この駅の出口の数\n}\n",
  ['use std::collections::HashMap;\nfn main() {\n    let mut count = HashMap::new();\n    count.insert("t7", 2);\n    *count.___("t4").or_insert(0) += 1;   // t4 is 1\n    println!("{:?}", count.get("t9"));    // None\n}\n'] = 'use std::collections::HashMap;\nfn main() {\n    let mut count = HashMap::new();\n    count.insert("t7", 2);\n    *count.___("t4").or_insert(0) += 1;   // t4 は 1\n    println!("{:?}", count.get("t9"));    // None\n}\n',
  ["use std::collections::HashMap; The :: walks the path. std is always there, no Cargo.toml line needed."] = "use std::collections::HashMap; の :: がパスをたどる。std は常にあるので、Cargo.toml に行を足す必要はない。",
  ['use std::collections::___;\n\nlet mut menu = ___::new();\nmenu.insert("tea", 12);\nlet price = menu["tea"];    // hash, bucket, compare\n'] = 'use std::collections::___;\n\nlet mut menu = ___::new();\nmenu.insert("tea", 12);\nlet price = menu["tea"];    // ハッシュ、バケット、比較\n',
  ['use std::error::Error;\nfn main() -> Result<(), ___<dyn Error>> {\n    let qty: i32 = "18".parse()?;   // ParseIntError fits\n    let text = std::fs::read_to_string("menu.txt")?;\n    println!("{qty} sets, {} bytes of menu", text.len());\n    Ok(())\n}\n'] = 'use std::error::Error;\nfn main() -> Result<(), ___<dyn Error>> {\n    let qty: i32 = "18".parse()?;   // ParseIntError も収まる\n    let text = std::fs::read_to_string("menu.txt")?;\n    println!("{qty} sets, {} bytes of menu", text.len());\n    Ok(())\n}\n',
  ['use std::fmt;\n// Receipt carries a lifetime; fmt does not need its name.\nimpl fmt::Display for Receipt<___> {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} paid {}", self.name, self.total)\n    }\n}\n'] = 'use std::fmt;\n// Receipt はライフタイムを持つ。fmt にはその名前は要らない。\nimpl fmt::Display for Receipt<___> {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} paid {}", self.name, self.total)\n    }\n}\n',
  ['use std::fmt;\n// Teach println!("{}") how to print an Order.\nimpl fmt::___ for Order {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} x{}", self.bun, self.qty)\n    }\n}\n'] = 'use std::fmt;\n// println!("{}") に Order の出力方法を教える。\nimpl fmt::___ for Order {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} x{}", self.bun, self.qty)\n    }\n}\n',
  ['use std::fmt;\nimpl fmt::___ for OrderError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "order failed")\n    }\n}\n'] = 'use std::fmt;\nimpl fmt::___ for OrderError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "order failed")\n    }\n}\n',
  ['use std::fs;\n// A missing menu file is a bug: stop with a message.\nlet menu = fs::read_to_string("menu.txt")\n    .___("menu.txt must exist");\n'] = 'use std::fs;\n// メニューファイルがないのはバグ: メッセージを出して止める。\nlet menu = fs::read_to_string("menu.txt")\n    .___("menu.txt must exist");\n',
  ["use std::num::ParseIntError;\n\n#[derive(Debug)]\n___ OrderError {\n    Empty,\n    BadQty(ParseIntError),\n}\n"] = "use std::num::ParseIntError;\n\n#[derive(Debug)]\n___ OrderError {\n    Empty,\n    BadQty(ParseIntError),\n}\n",
  ["use std::num::ParseIntError;\n// Hand any parse error straight back to the caller.\nfn cents(s: &str) -> Result<u32, ParseIntError> {\n    let n: u32 = s.parse()___;\n    Ok(n * 100)\n}\n"] = "use std::num::ParseIntError;\n// parse のエラーはそのまま呼び出し側に渡す。\nfn cents(s: &str) -> Result<u32, ParseIntError> {\n    let n: u32 = s.parse()___;\n    Ok(n * 100)\n}\n",
  ["use std::sync::Arc;\n// Arc: one receiver, many owners across threads.\n// The lock: only one cook holds the rail at a time.\nlet rx = Arc::new(___::new(rx));\nlet rx2 = Arc::clone(&rx);       // one clone per cook\n"] = "use std::sync::Arc;\n// Arc: 受信者は 1 つ、所有者はスレッドをまたいで多数。\n// 鍵: 一度にレールを握る料理人は 1 人だけ。\nlet rx = Arc::new(___::new(rx));\nlet rx2 = Arc::clone(&rx);       // 料理人 1 人につき clone 1 つ\n",
  ['use std::sync::RwLock;\nlet menu = RwLock::new(vec!["bun", "egg tart"]);\n// Many may look at once; only .write() has to wait.\nlet first = menu.___().unwrap()[0];\n'] = 'use std::sync::RwLock;\nlet menu = RwLock::new(vec!["bun", "egg tart"]);\n// 同時に何人でも見られる。待つのは .write() だけ。\nlet first = menu.___().unwrap()[0];\n',
  ["use std::sync::atomic::{AtomicUsize, Ordering};\nstatic SERVED: AtomicUsize = AtomicUsize::new(0);\n// No lock needed: add one in a single hardware step.\nSERVED.___(1, Ordering::SeqCst);\n"] = "use std::sync::atomic::{AtomicUsize, Ordering};\nstatic SERVED: AtomicUsize = AtomicUsize::new(0);\n// ロック不要: ハードウェアの 1 ステップで 1 を足す。\nSERVED.___(1, Ordering::SeqCst);\n",
  ['use std::sync::mpsc;\n// One pipe from till to kitchen: a sender and a receiver.\nlet (tx, rx) = mpsc::___();\ntx.send("egg tart").unwrap();\n'] = 'use std::sync::mpsc;\n// レジから厨房へのパイプ 1 本: 送信者と受信者。\nlet (tx, rx) = mpsc::___();\ntx.send("egg tart").unwrap();\n',
  ["use std::sync::mpsc;\ntype Job = Box<dyn FnOnce() + Send>;\n// one rail: many senders allowed, exactly one receiver\nlet (tx, rx) = mpsc::___::<Job>();\n"] = "use std::sync::mpsc;\ntype Job = Box<dyn FnOnce() + Send>;\n// レールは 1 本: 送信者は多数、受信者はちょうど 1 人\nlet (tx, rx) = mpsc::___::<Job>();\n",
  ['use std::thread;\n// The grill gets its own thread; the till keeps serving.\nlet grill = thread::___(|| {\n    println!("bun is toasting");\n});\ngrill.join().unwrap();\n'] = 'use std::thread;\n// グリルは自分のスレッドをもらう。レジは接客を続ける。\nlet grill = thread::___(|| {\n    println!("bun is toasting");\n});\ngrill.join().unwrap();\n',
  ['use std::time::Duration;\n// Steep the tea for 300 ms before pouring.\nthread::___(Duration::from_millis(300));\nprintln!("pour");\n'] = 'use std::time::Duration;\n// 注ぐ前に 300 ms お茶を蒸らす。\nthread::___(Duration::from_millis(300));\nprintln!("pour");\n',
  ["utf8.RuneCountInString counts code points. []rune(s) makes them indexable."] = "utf8.RuneCountInString はコードポイントを数えます。[]rune(s) ならインデックスで参照できます。",
  ["v is an any that holds a string. Take it out: s := v.(___)"] = "v は string を持つ any。取り出します: s := v.(___)",
  ["v is smaller than the node's value. Which side does the insert recurse into?"] = "v がノードの値より小さい。挿入はどちら側に再帰する？",
  ["v, ___ := <-orders\nif !___ {\n    return\n}\n"] = "v, ___ := <-orders\nif !___ {\n    return\n}\n",
  ["v, ok := <-ch tells a closed channel from a zero value. Receiving from a closed channel returns the zero value at once; sending on one panics. A nil channel blocks for ever, which is how a select case is switched off. len and cap look inside a buffer, and the sender closes, never the receiver."] = "v, ok := <-ch は「閉じた channel」と「ゼロ値」を区別する。閉じた channel から受け取るとすぐゼロ値が返り、そこへ送ると panic する。nil の channel は永遠にブロックし、それが select の分岐を消す方法だ。len と cap はバッファの中身を教え、閉じるのは常に送り手であって受け手ではない。",
  ["v, ok := m[k]. If ok is false, v is the zero value and the key was missing."] = "v, ok := m[k]。ok が false なら v はゼロ値で、キーは無かったということです。",
  ["v.(T) is a type assertion. s, ok := v.(T) never panics."] = "v.(T) は型アサーション。s, ok := v.(T) は決して panic しません。",
