  ["var count [26]int\nfor _, c := range a {\n    count[c-'a']___          // add\n}\nfor _, c := range b {\n    count[c-'a']--           // remove\n}\n"] = "var count [26]int\nfor _, c := range a {\n    count[c-'a']___          // 加算\n}\nfor _, c := range b {\n    count[c-'a']--           // 減算\n}\n",
